  ui_story_5004_50040101_7_dialog_content = "（此刻，薇絲和卡蓮正擋在我身前，試圖以這種徒勞的方式保護我……）",
  ui_story_5004_50040101_8_dialog_content = "（然而，一切都已無法挽回。）",
