  ui_story_5004_50040101_41_dialog_content = "只要認真地貫徹和執行她的命令，就能走近真理。",
  ui_story_5004_50040101_42_dialog_content = "（居然直接用這種話術來應付我，更可疑了吧……）",
  ui_story_5004_50040101_43_dialog_content = "好吧，正好拉斐爾在巨像上，我去找她。",
  ui_story_5004_50040101_44_dialog_content = "<color=#e8d9bb>幾分鐘後</color>",
  ui_story_5004_50040101_45_dialog_content = "嗯……",
  ui_story_5004_50040101_46_dialog_content = "嗯……嗯……",
  ui_story_5004_50040101_47_dialog_content = "怎麼樣，尊敬的天使小姐。",
  ui_story_5004_50040101_48_dialog_content = "從現有的手段來看，完全檢查不出她的身體有什麼異常耶……！",
  ui_story_5004_50040101_49_dialog_content = "妳叫拜里厄，對嗎？",
  ui_story_5004_50040101_50_dialog_content = "嗯……",
  ui_story_5004_50040101_51_dialog_content = "那小拜里厄，妳感覺自己哪裡不舒服呢？",
  ui_story_5004_50040101_52_dialog_content = "小拜里厄……",
  ui_story_5004_50040101_53_dialog_content = "抱歉，我對身體的感覺一向比較遲鈍……",
  ui_story_5004_50040101_54_dialog_content = "但最近總是感覺非常疲勞，對光能的掌握也變得非常不穩定……",
  ui_story_5004_50040101_55_dialog_content = "偶爾還會全身劇痛……蟻噬般的疼痛在全身蔓延……",
  ui_story_5004_50040101_56_dialog_content = "這樣呀……",
  ui_story_5004_50040101_57_dialog_content = "拉斐爾也是第一次遇到小拜里厄這種情況的病人呢。",
  ui_story_5004_50040101_58_dialog_content = "PlayerName怎麼看？",
  ui_story_5004_50040101_59_dialog_content = "（拜里厄一直眉頭緊鎖的，看起來是有什麼心事吧。）",
  ui_story_5004_50040101_60_option_content = "是不是有不開心的事？",
  ui_story_5004_50040101_61_dialog_content = "有這個可能呢！",
  ui_story_5004_50040101_62_dialog_content = "每次卡蓮姐姐和城主大人吵架之後，都會露出這樣的表情。",
  ui_story_5004_50040101_63_dialog_content = "很像現在的小拜里厄。",
  ui_story_5004_50040101_64_option_content = "要不要讓我用感應能力試試——",
  ui_story_5004_50040101_65_dialog_content = "不行！這樣對待女孩子也太失禮了！",
  ui_story_5004_50040101_66_dialog_content = "就像是直接切開皮膚尋找患處一樣粗魯！",
  ui_story_5004_50040101_67_dialog_content = "總之呢！",
  ui_story_5004_50040101_68_dialog_content = "不管是身體還是心理疾病，都儘管交給拉斐爾吧！",
  ui_story_5004_50040101_69_dialog_content = "小拜里厄不用擔心，我身為妳的主治醫生，會一直陪在妳身邊的！",
  ui_story_5004_50040101_70_dialog_content = "我會找到妳的病因，然後用「一口氣的治療」讓妳恢復精神喔！",
  ui_story_5004_50040101_71_dialog_content = "一口氣的治療……是指只剩下一口氣嗎？",
  ui_story_5004_50040101_72_dialog_content = "PlayerName！",
  ui_story_5004_50040101_X72_dialog_content = "請不要在病人面前開這種玩笑！",
  ui_story_5004_50040101_73_dialog_content = "謝謝……",
  ui_story_5004_50040101_74_dialog_content = "大家都聚在這裡做什麼呢？",
  ui_story_5004_50040101_75_dialog_content = "PlayerName你好，拉斐爾也在呢。",
  ui_story_5004_50040101_76_dialog_content = "啊，卡蓮姐姐，妳怎麼來啦。",
  ui_story_5004_50040101_77_dialog_content = "我代表白夜城定期聯絡，順便和薇絲談一點私事。",
  ui_story_5004_50040101_78_dialog_content = "這邊的兩位……",
  ui_story_5004_50040101_79_dialog_content = "這位是浮士德。",
  ui_story_5004_50040101_80_dialog_content = "日安，尊貴的女士。",
  ui_story_5004_50040101_81_dialog_content = "你是<color=#FFB400>真理結社</color>的人？",
  ui_story_5004_50040101_82_dialog_content = "真沒想到，您居然知道真理結社。",
  ui_story_5004_50040101_83_dialog_content = "莫非您也是真理的追尋者？",
  ui_story_5004_50040101_84_dialog_content = "我對所謂的「真理」沒興趣，我有自己的信仰。",
  ui_story_5004_50040101_85_dialog_content = "真是可惜。",
  ui_story_5004_50040101_86_dialog_content = "然而值得慶幸的是，當您開始評價真理之時，就意味著您又向真理邁出了一步。",
  ui_story_5004_50040101_87_dialog_content = "或許我們會在終點相見。",
  ui_story_5004_50040101_88_dialog_content = "真是油嘴滑舌……PlayerName，這個女孩子是？",
  ui_story_5004_50040101_89_dialog_content = "她是拜里厄，浮士德委託我照顧她……好像是浮士德的朋友？",
  ui_story_5004_50040101_90_dialog_content = "卡蓮姐姐~小拜里厄現在是我的病人喔。",
  ui_story_5004_50040101_91_dialog_content = "原來如此……很好，拉斐爾。",
  ui_story_5004_50040101_92_dialog_content = "妳別辱白夜之名，要努力照顧好這位病人。",
  ui_story_5004_50040101_93_dialog_content = "嗯哼哼~當然啦！",
  ui_story_5004_50040101_94_dialog_content = "不過現在還不清楚小拜里厄究竟患了什麼病……",
  ui_story_5004_50040101_X94_dialog_content = "現在推測可能是心理狀況……或者壓力過大之類的……",
  ui_story_5004_50040101_95_dialog_content = "拉斐爾連心理方面的疾病也能處理嗎，看來不只是會發射飛彈的戰鬥天使呢！",
  ui_story_5004_50040101_96_dialog_content = "嘿嘿，不要小看了白夜城的天使，小薇絲~",
  ui_story_5004_50040101_97_dialog_content = "（看來拉斐爾和薇絲的關係已經很要好了……真不錯。）",
  ui_story_5004_50040101_98_dialog_content = "PlayerName在傻笑什麼呢？我帶來了一個好東西。",
  ui_story_5004_50040101_99_dialog_content = "說不定能幫上你的忙呢。",
  ui_story_5004_50040101_100_dialog_content = "來，這是給你的信。",
  ui_story_5004_50040101_101_dialog_content = "給我的信？",
  ui_story_5004_50040101_102_dialog_content = "剛剛阿褐給我之後就跑掉了，信封上印著<color=#FFB400>「白金夏潮飯店」</color>。",
  ui_story_5004_50040101_103_dialog_content = "不過我看了一眼，上面連寄信人都沒有，有點奇怪。",
  ui_story_5004_50040101_104_dialog_content = "要不要拆開看看？",
  ui_story_5004_50040101_105_option_content = "有點可疑……先不要拆吧",
  ui_story_5004_50040101_106_dialog_content = "別這麼膽小嘛，沒事的沒事的。",
  ui_story_5004_50040101_107_dialog_content = "那我來幫你拆好啦，嘿！",
  ui_story_5004_50040101_108_dialog_content = "喂喂，小心會爆炸的……！",
  ui_story_5004_50040101_109_dialog_content = "裡面只有一張紙嘛。看起來也只是普通的紙張，上面有磨砂的紋路。",
  ui_story_5004_50040101_110_dialog_content = "還好沒事……",
  ui_story_5004_50040101_111_option_content = "應該沒關係吧，拆了拆了",
  ui_story_5004_50040101_112_dialog_content = "快拆快拆，我也想知道裡面是什麼。",
  ui_story_5004_50040101_113_dialog_content = "嗯？好像只有一張紙。",
  ui_story_5004_50040101_114_dialog_content = "就只有一張紙嗎？",
  ui_story_5004_50040101_115_dialog_content = "PlayerName，上面寫了什麼？",
  ui_story_5004_50040101_116_dialog_content = "嗯……",
  ui_story_5004_50040101_117_dialog_content = "尊敬的PlayerName：",
  ui_story_5004_50040101_118_dialog_content = "本店竭誠邀請您蒞臨白金夏潮沙灘飯店度假。",
  ui_story_5004_50040101_X118_dialog_content = "參與我們精心為您奉上的<color=#FFB400>潮汐祭</color>活動。",
  ui_story_5004_50040101_119_dialog_content = "還有一張邀請函，上面寫著最多可以帶六位親友隨同。",
  ui_story_5004_50040101_120_dialog_content = "免費享受飯店的高級客房和所有娛樂設施……！",
  ui_story_5004_50040101_121_dialog_content = "那不是很好嗎！我早就想去海邊看看了！",
  ui_story_5004_50040101_122_dialog_content = "祭典活動呀……感覺會對小拜里厄很有幫助！",
  ui_story_5004_50040101_123_dialog_content = "如果拜里厄是心病的話，玩個痛快說不定就能不藥而癒！",
  ui_story_5004_50040101_124_dialog_content = "PlayerName，我們就和小拜里厄一起去海邊嘛~好不好~好不好嘛~",
  ui_story_5004_50040101_125_dialog_content = "等一下，我還沒搞懂狀況，這種名字都沒聽過的地方……",
  ui_story_5004_50040101_126_dialog_content = "不用擔心喔，PlayerName，這間飯店其實還挺有名的。",
  ui_story_5004_50040101_127_dialog_content = "的確，白金夏潮飯店近幾年在白夜城貴族的圈子裡小有名氣，就連我也有所耳聞。",
  ui_story_5004_50040101_128_dialog_content = "聽說飯店的所有者十分擅長經營。",
  ui_story_5004_50040101_129_dialog_content = "這張邀請函和所謂的「潮汐祭」，很可能都是他的某種商業手法吧。",
  ui_story_5004_50040101_130_dialog_content = "不過他為什麼會邀請我呢？",
  ui_story_5004_50040101_131_dialog_content = "可能也是他的某種經營策略。",
  ui_story_5004_50040101_132_dialog_content = "畢竟大多數光靈都對「空裔」充滿了好奇心。",
  ui_story_5004_50040101_133_dialog_content = "空裔來過的飯店、空裔住過的房間、空裔用過的餐桌，都可能被打造成旅遊景點用來做宣傳。",
  ui_story_5004_50040101_134_dialog_content = "妳這麼一說，我就好像某種珍稀動物一樣……",
  ui_story_5004_50040101_135_dialog_content = "……",
  ui_story_5004_50040101_136_dialog_content = "……",
  ui_story_5004_50040101_137_dialog_content = "妳們也稍微反駁一下吧！",
  ui_story_5004_50040101_138_dialog_content = "不過既然是白夜城貴族消遣的地方……又是互利互惠的行為。",
  ui_story_5004_50040101_139_dialog_content = "應該沒什麼危險吧。",
  ui_story_5004_50040101_140_dialog_content = "看來意見已經達成一致。",
  ui_story_5004_50040101_141_dialog_content = "嗯？你還在啊？",
  ui_story_5004_50040101_142_dialog_content = "那麼拜里厄就交給你們了，請好好享受假期，在下告辭了。",
  ui_story_5004_50040101_143_dialog_content = "……浮士德先生還是這樣來去如風啊。",
  ui_story_5004_50040101_144_dialog_content = "太好了，小拜里厄。我會負起醫生的責任好好照顧妳的~！",
  ui_story_5004_50040101_145_dialog_content = "總感覺事情……不會那麼簡單啊。",
  ui_story_5004_50040101_146_dialog_content = "快看快看，已經能遠遠地看到海了。",
  ui_story_5004_50040101_147_dialog_content = "PlayerName，我是第一次看到海喔。",
  ui_story_5004_50040101_148_dialog_content = "欸？薇絲也是嗎？",
  ui_story_5004_50040101_149_dialog_content = "我以為只有我……",
  ui_story_5004_50040101_150_dialog_content = "並不只有你啦。沒有巨像的話很難來到這麼遠的地方。",
  ui_story_5004_50040101_151_dialog_content = "海風好舒服，放眼望去全是瑰麗的藍色，讓人整個心曠神怡。",
  ui_story_5004_50040101_152_dialog_content = "這樣一定會對拜里厄小姐的病大有益處的！",
  ui_story_5004_50040101_153_dialog_content = "妳啊……嘴上說是為了拜里厄，其實還是自己想去海邊玩吧。",
  ui_story_5004_50040101_154_dialog_content = "確實也有這個原因。",
  ui_story_5004_50040101_155_dialog_content = "因為對大多數光靈來說，能去海邊的機會少之又少。",
  ui_story_5004_50040101_156_dialog_content = "你一直生活在巨像裡，可能不太瞭解。",
  ui_story_5004_50040101_157_dialog_content = "去海邊度假，對現在的光靈來說可是<color=#FFB400>勇者的遊戲</color>喔！",
  ui_story_5004_50040101_158_dialog_content = "為什麼這麼說……？",
  ui_story_5004_50040101_159_dialog_content = "你想想看，現在大部分海岸都徘徊著很多暗鬼。",
  ui_story_5004_50040101_160_dialog_content = "在享受著陽光和海浪的同時，隨時準備應付突然襲來的暗鬼。",
  ui_story_5004_50040101_161_dialog_content = "這種安逸與危險並存的感覺，是不是很有挑戰性呢！",
  ui_story_5004_50040101_162_dialog_content = "這個叫做「挑戰性」嗎？聽起來純粹是非常危險吧……",
  ui_story_5004_50040101_163_dialog_content = "比如說我被沙子埋在下面的時候，突然有暗鬼出現。",
  ui_story_5004_50040101_164_dialog_content = "薇絲妳不會丟下我就跑吧！！",
  ui_story_5004_50040101_165_dialog_content = "我們不是夥伴嗎，才不會做那種事！",
  ui_story_5004_50040101_166_dialog_content = "不管怎麼說，夏天就是療癒心靈的良藥，再配上清涼的海水……",
  ui_story_5004_50040101_167_dialog_content = "在這裡，拜里厄一定能放鬆身心。",
  ui_story_5004_50040101_168_dialog_content = "海水，是要游泳嗎……但我們沒有<color=#FFB400>泳裝</color>吧。",
  ui_story_5004_50040101_169_dialog_content = "這一點不用擔心。",
  ui_story_5004_50040101_170_dialog_content = "據我所知，飯店裡就有賣名牌泳裝了。",
  ui_story_5004_50040101_171_dialog_content = "畢竟那裡主要的服務對象可是白夜城的貴族。",
  ui_story_5004_50040101_172_dialog_content = "連泳裝都有賣，真是貼心呢。",
  ui_story_5004_50040101_173_dialog_content = "當然了，泳裝之於沙灘，相當於盔甲之於戰場。",
  ui_story_5004_50040101_174_dialog_content = "不管是啟光的士兵，還是白夜城的貴族，在沙灘上就是必須身著泳裝。",
  ui_story_5004_50040101_175_dialog_content = "這就是所謂的「沙灘禮儀」！",
  ui_story_5004_50040101_176_dialog_content = "是……是這樣嗎？",
  ui_story_5004_50040101_177_dialog_content = "（怎麼和臨空者教我的不太一樣……泳裝是這麼回事嗎？）",
  ui_story_5004_50040101_178_dialog_content = "卡蓮怎麼好像……對飯店和泳裝都挺瞭解的？",
  ui_story_5004_50040101_179_dialog_content = "這有什麼奇怪的，我是白夜城的衛隊長。",
  ui_story_5004_50040101_180_dialog_content = "瞭解貴族中流行的話題也是職責的一部分。",
  ui_story_5004_50040101_181_dialog_content = "總之PlayerName，你可以期待我披甲上陣的英姿。",
  ui_story_5004_50040101_182_dialog_content = "（卡蓮的泳裝嗎……）",
  ui_story_5004_50040101_183_dialog_content = "嗯……嗯。",
  ui_story_5004_50040101_184_dialog_content = "PlayerName，為什麼這樣看著我？",
  ui_story_5004_50040101_185_dialog_content = "我的身上有哪裡不對勁嗎？",
  ui_story_5004_50040101_186_dialog_content = "沒......沒什麼。對了！關於這間飯店，卡蓮還知道些什麼嗎？",
  ui_story_5004_50040101_187_dialog_content = "我只知道它似乎曾是白夜城某位貴族的資產。",
  ui_story_5004_50040101_188_dialog_content = "後來因為經營不善而轉手給影鎮的某個神祕幫派。",
  ui_story_5004_50040101_189_dialog_content = "影鎮這種地方，本來就錯綜複雜，相關情報的真實性很難判斷。",
  ui_story_5004_50040101_190_dialog_content = "更別提這種刻意隱藏真面目的幫派。",
  ui_story_5004_50040101_191_dialog_content = "如果不是情報靈通的影鎮本地人，外人恐怕很難知道詳細的內幕。",
  ui_story_5004_50040101_192_dialog_content = "原來如此……影鎮真是一個複雜的地方。",
  ui_story_5004_50040101_193_dialog_content = "是的，現在影鎮能維持相對的穩定和諧，也要歸功於那位……",
  ui_story_5004_50040101_194_dialog_content = "等一下！大家不要一直說這麼嚴肅的事啦。",
  ui_story_5004_50040101_195_dialog_content = "我們這次的主要目標是幫助小拜里厄散心，讓她盡快恢復健康喔！",
  ui_story_5004_50040101_196_dialog_content = "我沒關係的……",
  ui_story_5004_50040101_197_dialog_content = "！！！",
  ui_story_5004_50040101_198_dialog_content = "PlayerName？！",
  ui_story_5004_50040101_199_dialog_content = "臨空者號！",
  ui_story_5004_50040101_200_dialog_content = "PlayerName，巡航系統正受到來自目的地方向的強烈干擾。",
  ui_story_5004_50040101_201_dialog_content = "如果執意繼續前進，恐怕會造成飛行姿態失控。",
  ui_story_5004_50040101_202_dialog_content = "嗚——！！",
  ui_story_5004_50040101_203_dialog_content = "小拜里厄？小拜里厄？",
  ui_story_5004_50040101_204_dialog_content = "哪裡不舒服嗎？",
  ui_story_5004_50040101_205_dialog_content = "臨空者號！先拉開和目的地的距離，然後馬上找地方降落！",
  ui_story_5004_50040101_206_dialog_content = "明白。",
  ui_story_5004_50040101_207_dialog_content = "拜里厄，妳沒事吧？",
  ui_story_5004_50040101_208_dialog_content = "……這是？",
  ui_story_5004_50040101_209_dialog_content = "這是哪……？",
  ui_story_5004_50040101_210_dialog_content = "火焰的溫度……燒焦的氣味……還有許許多多光靈的哭喊聲……",
  ui_story_5004_50040101_211_dialog_content = "但是什麼都看不清……",
  ui_story_5004_50040101_212_dialog_content = "這裡究竟……是哪裡？",
  ui_story_5004_50040101_213_dialog_content = "PlayerName！",
  ui_story_5004_50040101_214_dialog_content = "PlayerName！！",
  ui_story_5004_50040101_215_dialog_content = "薇絲……？",
  ui_story_5004_50040101_216_dialog_content = "PlayerName，你不要緊吧？",
  ui_story_5004_50040101_217_dialog_content = "剛剛怎麼了……",
  ui_story_5004_50040101_218_dialog_content = "你剛剛碰了拜里厄之後就一直愣著不動。",
  ui_story_5004_50040101_219_dialog_content = "又感應到什麼了嗎？",
  ui_story_5004_50040101_220_dialog_content = "嗯……不過只是很模糊的畫面……算了，現在情況怎麼樣？",
  ui_story_5004_50040101_221_dialog_content = "我已脫離干擾範圍，正在尋找著陸點。",
  ui_story_5004_50040101_222_dialog_content = "小拜里厄，妳沒受傷吧？",
  ui_story_5004_50040101_223_dialog_content = "嗯……",
  ui_story_5004_50040101_224_dialog_content = "剛剛那到底是……",
  ui_story_5004_50040201_1_dialog_content = "真是……為什麼非要我開車載你們過去啊，又不是我把巨像弄到非降落不可的。",
  ui_story_5004_50040201_2_dialog_content = "我剛才正想去巨像酒吧裡彈一段呢。",
  ui_story_5004_50040201_3_dialog_content = "那邊那個什麼飯店，真的有超豪華音響嗎？",
  ui_story_5004_50040201_4_dialog_content = "敢騙我的話……就讓你們知道知道烈陽的溫度！",
  ui_story_5004_50040201_5_dialog_content = "別、別敲車頂了！再敲我要掉下去了。",
  ui_story_5004_50040201_6_dialog_content = "應該……會有的！",
  ui_story_5004_50040201_7_dialog_content = "如果沒有……",
  ui_story_5004_50040201_8_dialog_content = "我就把巨像裡的音響換成妳上次想要的「轟隆轟隆震天雷」音響套組！",
  ui_story_5004_50040201_9_dialog_content = "總之請妳先認真開車，我還在車頂上！拜託了！",
  ui_story_5004_50040201_10_dialog_content = "真抱歉……還要PlayerName坐車頂……",
  ui_story_5004_50040201_11_dialog_content = "沒關係，不用太在意的。",
  ui_story_5004_50040201_12_dialog_content = "總不能讓女孩子去坐那種「特別座」吧。",
  ui_story_5004_50040201_13_dialog_content = "真看不出啊，PlayerName你還挺紳士的。",
  ui_story_5004_50040201_14_dialog_content = "看路啊，開車請看路。手不要離開方向盤！",
  ui_story_5004_50040201_15_dialog_content = "不用怕——開車這種小事，每個紅油扳手的人從出生就會了。",
  ui_story_5004_50040201_16_dialog_content = "就算來了一隻高級暗鬼，我也能直接從它臉上碾過去。",
  ui_story_5004_50040201_17_dialog_content = "你們的確很幸運，還好<color=#FFB400>黑潮</color>的<color=#FFB400>車</color>放在你這裡修，不然你們幾個要走——",
  ui_story_5004_50040201_18_dialog_content = "小心前面！",
  ui_story_5004_50040201_19_dialog_content = "蕾吉娜！前面有暗鬼！",
  ui_story_5004_50040201_20_dialog_content = "什麼？！",
  ui_story_5004_50040201_21_dialog_content = "痛痛痛……該死，哪來的暗鬼……！我二十幾年來第一次開車就……",
  ui_story_5004_50040201_22_dialog_content = "吼——",
  ui_story_5004_50040201_23_dialog_content = "嗚……腦袋好暈……暗鬼被撞飛出去了嗎？",
  ui_story_5004_50040201_24_dialog_content = "大家沒事吧……",
  ui_story_5004_50040201_25_dialog_content = "還好，只是輕傷。",
  ui_story_5004_50040201_26_dialog_content = "嘎——！！",
  ui_story_5004_50040201_27_dialog_content = "怎麼會有這麼多暗鬼……大家！準備戰鬥。",
  ui_story_5004_50040201_28_dialog_content = "為了騰出座位，武器都放到後車箱裡了……！",
  ui_story_5004_50040201_29_dialog_content = "再拖拖拉拉的就要被暗鬼包圍了！",
  ui_story_5004_50040201_30_dialog_content = "拜里厄、小拜里厄，快醒醒！",
  ui_story_5004_50040201_31_dialog_content = "嗚……",
  ui_story_5004_50040201_32_dialog_content = "拉斐爾……？",
  ui_story_5004_50040201_33_dialog_content = "小心——！",
  ui_story_5004_50040201_34_dialog_content = "……！！",
  ui_story_5004_50040201_35_dialog_content = "血晶……！",
  ui_story_5004_50040201_36_dialog_content = "嘎嗚……",
  ui_story_5004_50040201_37_dialog_content = "吼！！吼！！！",
  ui_story_5004_50040201_38_dialog_content = "它們想撞翻車子？！",
  ui_story_5004_50040201_39_dialog_content = "綻放吧！！",
  ui_story_5004_50040201_40_dialog_content = "嗷……",
  ui_story_5004_50040201_41_dialog_content = "好強，一瞬間就都解決掉了嗎？！",
  ui_story_5004_50040201_42_dialog_content = "想不到妳還有這麼強大的力量，看來真理結社也不全是泛泛之輩。",
  ui_story_5004_50040201_43_dialog_content = "能瞬間釋放出這麼多晶石擊敗一群暗鬼，和白夜城天使相比也不遑多讓了吧。",
  ui_story_5004_50040201_44_dialog_content = "確實如此。",
  ui_story_5004_50040201_45_dialog_content = "好厲害……啊，謝謝妳！小拜里厄！",
  ui_story_5004_50040201_46_dialog_content = "呼……呼……",
  ui_story_5004_50040201_47_dialog_content = "小拜里厄？……妳沒事吧？",
  ui_story_5004_50040201_48_dialog_content = "喂喂，小姐們別聊個沒完了，趁這個機會拿好武器，有更多暗鬼過來了！",
  ui_story_5004_50040301_1_dialog_content = "呼——總算快到了啊，再也不想開車了。",
  ui_story_5004_50040301_2_dialog_content = "謝謝您把我們肢體健全地送到……",
  ui_story_5004_50040301_3_dialog_content = "別貧嘴了，找個地方把車停好吧。",
  ui_story_5004_50040301_4_dialog_content = "喂喂！！你們幾個在這裡幹嘛？",
  ui_story_5004_50040301_5_dialog_content = "我的車怎麼也在這，前蓋還凹了一個洞？！",
  ui_story_5004_50040301_6_dialog_content = "PlayerName，雖然我們交情不錯，但這你得給我說清楚。",
  ui_story_5004_50040301_7_option_content = "其、其實是蕾吉娜說想開車兜兜風……！",
  ui_story_5004_50040301_8_dialog_content = "得了吧，她就算想兜風也不可能親自開車。",
  ui_story_5004_50040301_9_dialog_content = "你是抓到她什麼把柄了？",
  ui_story_5004_50040301_10_dialog_content = "別瞧不起人啊，我是那種被抓住把柄才會幹活的人嗎？",
  ui_story_5004_50040301_11_dialog_content = "那是PlayerName答應幫妳升級音響系統了？",
  ui_story_5004_50040301_12_dialog_content = "居然被黑潮猜到了！",
  ui_story_5004_50040301_13_dialog_content = "什麼啊？我又不是笨蛋，一秒鐘就看穿你們的交易了！",
  ui_story_5004_50040301_14_option_content = "我是把車修好，然後特地幫你送過來！",
  ui_story_5004_50040301_15_dialog_content = "啊？我告訴過你我在這裡嗎？",
  ui_story_5004_50040301_16_dialog_content = "是感應能力啦，感應！",
  ui_story_5004_50040301_17_dialog_content = "這麼遠也能感應？！真是不得了啊！",
  ui_story_5004_50040301_18_dialog_content = "車蓋的這個形狀……是暗鬼吧?",
  ui_story_5004_50040301_19_dialog_content = "這也看得出來嗎？！",
  ui_story_5004_50040301_20_dialog_content = "喂，別小看人啊。我一年至少要撞飛幾百隻暗鬼。",
  ui_story_5004_50040301_21_dialog_content = "這個形狀已經印入靈魂裡了好嗎。是撞到「悍鋒」了吧？",
  ui_story_5004_50040301_22_dialog_content = "連暗鬼的類型都有辦法辨認嗎？！啊，抱歉。之後我會幫你修好的！",
  ui_story_5004_50040301_23_dialog_content = "也不用太在意，這次算你幫我的愛車又添了一筆殺敵數。",
  ui_story_5004_50040301_24_dialog_content = "我之後讓那個<color=#FFB400>機械師朋友</color>幫忙修就可以了。",
  ui_story_5004_50040301_25_dialog_content = "話說回來，你們來這裡幹嘛，度假嗎？",
  ui_story_5004_50040301_26_dialog_content = "嗯！PlayerName他收到了白金夏潮飯店的邀請函喔！住宿免費！",
  ui_story_5004_50040301_27_dialog_content = "嗄？真是稀奇了，那個老闆有這麼大方嗎？",
  ui_story_5004_50040301_28_dialog_content = "也許是想利用PlayerName空裔的身分打廣告吧。",
  ui_story_5004_50040301_29_dialog_content = "喔，那倒是非常可能。",
  ui_story_5004_50040301_X29_dialog_content = "欸？！怎麼是妳！",
  ui_story_5004_50040301_30_dialog_content = "你是越獄的紅油扳手匪徒……",
  ui_story_5004_50040301_31_dialog_content = "等、等等！我們這次是帶拜里厄來旅遊的，不是來緝拿犯人的吧！",
  ui_story_5004_50040301_32_dialog_content = "何況又不是在白夜城，沒必要在這裡動武啦！",
  ui_story_5004_50040301_33_dialog_content = "……可以。",
  ui_story_5004_50040301_34_dialog_content = "但如果你敢在這段時間做出任何不利於白夜城的事。",
  ui_story_5004_50040301_35_dialog_content = "我一定會把你捉回去接受審判。",
  ui_story_5004_50040301_36_dialog_content = "對了，黑潮為什麼會在這裡，還對老闆很熟悉的樣子。",
  ui_story_5004_50040301_37_dialog_content = "這個嘛……我是來幫老朋友一點忙。就是剛剛提到的機械師朋友。",
  ui_story_5004_50040301_38_dialog_content = "啊，怎麼說呢……我和我的車都受過他不少照顧。有恩必報才是紅油扳手的美德嘛！",
  ui_story_5004_50040301_39_dialog_content = "你們如果去白金夏潮飯店的話，應該馬上能見到他。",
  ui_story_5004_50040301_40_dialog_content = "那傢伙很好認。他很顯眼……各種意義上來說都是。",
  ui_story_5004_50040301_41_dialog_content = "啊，還有一件事。",
  ui_story_5004_50040301_42_dialog_content = "臨空者號飛向這裡的時候遇到了干擾，你有什麼頭緒嗎？",
  ui_story_5004_50040301_43_dialog_content = "不知道，我又沒開過巨像。",
  ui_story_5004_50040301_44_dialog_content = "你把巨像當做什麼人人都有的東西嗎？",
  ui_story_5004_50040301_45_dialog_content = "巨像這種東西不就是生物和機械的結合嗎。",
  ui_story_5004_50040301_46_dialog_content = "也可能是臨空者號最近感冒發燒了吧。",
  ui_story_5004_50040301_47_dialog_content = "<size=30>PlayerName，這…這裡是不是該配合他的笑話笑一笑？</size>",
  ui_story_5004_50040301_48_dialog_content = "<size=30>不行……我分辨不出他是在開玩笑還是認真的……</size>",
  ui_story_5004_50040301_49_dialog_content = "別在我面前碎碎唸了。",
  ui_story_5004_50040301_50_dialog_content = "那我就把車開走了，你們順著這條路走就是飯店。",
  ui_story_5004_50040301_51_dialog_content = "（好漂亮……金色的沙灘被翻湧的碧波拍打著。）",
  ui_story_5004_50040301_52_dialog_content = "（那邊叫不出名字的挺拔綠樹，在帶有些微鹹味的海風吹拂下，搖曳得如此美麗。）",
  ui_story_5004_50040301_53_dialog_content = "（還有沙灘上玩耍嬉戲的人群。）",
  ui_story_5004_50040301_54_dialog_content = "（沐浴著和煦陽光的一切，都顯得如此生機勃勃，讓我心馳神往。）",
  ui_story_5004_50040301_55_dialog_content = "……",
  ui_story_5004_50040301_56_dialog_content = "這個地方……風景比我想像中還要好得多。",
  ui_story_5004_50040301_57_dialog_content = "PlayerName！這就是海邊嗎……",
  ui_story_5004_50040301_58_dialog_content = "真是想不到，在現在的局勢下還能有如此讓人放鬆身心的地方。",
  ui_story_5004_50040301_59_dialog_content = "好漂亮的大海……",
  ui_story_5004_50040301_60_dialog_content = "小拜里厄，那邊的小攤排了很多人呢！我們等等也過去看一下吧！",
  ui_story_5004_50040301_61_dialog_content = "呵呵……看起來，諸位對<color=#FFB400>天堂階梯海灘</color>十分滿意呢~",
  ui_story_5004_50040301_62_dialog_content = "！？",
  ui_story_5004_50040301_63_dialog_content = "不用這麼緊張啦，我叫<color=#FFB400>波娜瑟</color>，負責接待諸位貴賓的飯店人員，同時也是本次潮汐祭的主持人喔。",
  ui_story_5004_50040301_64_dialog_content = "啊，波娜瑟小姐……",
  ui_story_5004_50040301_65_dialog_content = "拜里厄妳也來了呀，那個很討厭的眼鏡男沒跟來吧？",
  ui_story_5004_50040301_66_dialog_content = "您是說浮士德先生嗎……他說還有工作，就把我委託給PlayerName照顧了……",
  ui_story_5004_50040301_67_dialog_content = "原來如此，那想必這位就是PlayerName吧。",
  ui_story_5004_50040301_68_dialog_content = "真是很有異性緣呢~有這麼多可愛的女孩子陪著。",
  ui_story_5004_50040301_69_dialog_content = "我們只是夥伴。",
  ui_story_5004_50040301_70_dialog_content = "夥伴嗎……呵呵……",
  ui_story_5004_50040301_71_dialog_content = "不過仔細看看PlayerName的話，雖說是空裔，但沒看到頭上有長角或第三隻眼睛嘛——",
  ui_story_5004_50040301_72_option_content = "那還真是對不起啊。",
  ui_story_5004_50040301_73_dialog_content = "嗯？客人您還真是有趣。",
  ui_story_5004_50040301_74_option_content = "空裔和光靈在外表上還是很接近的。",
  ui_story_5004_50040301_75_dialog_content = "客人您一本正經回答的樣子真是有趣~",
  ui_story_5004_50040301_76_dialog_content = "我只是跟您開個小玩笑，不用如此拘束。",
  ui_story_5004_50040301_77_dialog_content = "諸位可是飯店的重要貴賓，也是潮汐祭的種子參加者。",
  ui_story_5004_50040301_78_dialog_content = "就由我波娜瑟，為諸位獻上充滿夏日海灘風情的華麗熱情服務——",
  ui_story_5004_50040301_79_dialog_content = "服務就不用麻煩了，我們自己可以的！",
  ui_story_5004_50040301_80_dialog_content = "我有件事想問，這個潮汐祭到底是什麼。",
  ui_story_5004_50040301_81_dialog_content = "這個啊~是曾經在這片海灘上生活過的光靈所遺留的祭典儀式喔。",
  ui_story_5004_50040301_82_dialog_content = "「大海，萬物的起源。它以寬廣的胸懷迎接著一切，滋養著萬物。」",
  ui_story_5004_50040301_83_dialog_content = "「守護海的女神與每一位前來挑戰的英雄都在這裡共舞。」",
  ui_story_5004_50040301_84_dialog_content = "人們透過潮汐祭，讓參加者模擬傳說中的試煉。",
  ui_story_5004_50040301_85_dialog_content = "藉由<color=#FFB400>力量</color>、<color=#FFB400>智慧</color>、<color=#FFB400>勇氣</color>三方面的較量，角逐出最終勝利者。",
  ui_story_5004_50040301_86_dialog_content = "而神明則會給予勝利者獎勵，並保佑此處風調雨順，魚獲豐厚。",
  ui_story_5004_50040301_87_dialog_content = "勝利者可以獲得<color=#FFB400>「沙灘勇者」</color>的稱號。",
  ui_story_5004_50040301_88_dialog_content = "還有各種豐厚的物質獎勵以及神祕大獎！",
  ui_story_5004_50040301_89_dialog_content = "一邊享受著夏日和海灘風情，一邊和女孩子們參加各種比賽。",
  ui_story_5004_50040301_90_dialog_content = "PlayerName應該不會拒絕的吧。",
  ui_story_5004_50040301_91_dialog_content = "沙灘……勇者……",
  ui_story_5004_50040301_92_dialog_content = "這個我還是要和大家商量一下。",
  ui_story_5004_50040301_93_dialog_content = "嗯~沒關係，總之我先帶諸位去飯店大廳辦理入住手續吧。",
  ui_story_5004_50040301_94_dialog_content = "祭典是後天正式開始，今天和明天就請大家先盡情地放鬆享受。",
  ui_story_5004_50040301_95_dialog_content = "好華麗！",
  ui_story_5004_50040301_96_dialog_content = "的確，建築風格和白夜城或啟光都截然不同。",
  ui_story_5004_50040301_97_dialog_content = "可能是某種舊文明的風格吧。",
  ui_story_5004_50040301_98_dialog_content = "這裡就是飯店大廳了~接下來就交給大廳經理<color=#FFB400>弗勞爾</color>——",
  ui_story_5004_50040301_99_dialog_content = "嗯？弗勞爾？能麻煩你動作快一點嗎~",
  ui_story_5004_50040301_100_dialog_content = "我還有些事就先告辭了~很快就會再跟各位見面的。",
  ui_story_5004_50040301_101_dialog_content = "弗勞爾？",
  ui_story_5004_50040301_102_dialog_content = "抱......抱歉！",
  ui_story_5004_50040301_103_dialog_content = "我馬上就來……！",
  ui_story_5004_50040301_104_dialog_content = "弗勞爾！",
  ui_story_5004_50040301_105_dialog_content = "弗勞爾先生~",
  ui_story_5004_50040301_106_dialog_content = "弗勞爾先生，您今晚有空嗎？",
  ui_story_5004_50040301_107_dialog_content = "小勞爾~！跟我去健身房，讓你看看我完美的腓腸肌——！！",
  ui_story_5004_50040301_108_dialog_content = "這是剛烤好的點心，你快嚐一口。啊——",
  ui_story_5004_50040301_109_dialog_content = "這是什麼情況，這些看起來怪怪的傢伙，還有那個叫弗勞爾的人。",
  ui_story_5004_50040301_110_dialog_content = "那傢伙身上……有種奇怪的感覺。",
  ui_story_5004_50040301_111_dialog_content = "PlayerName，看起來弗勞爾比你還要受歡迎啊。",
  ui_story_5004_50040301_112_dialog_content = "別拿我開玩笑啦。",
  ui_story_5004_50040301_113_dialog_content = "抱歉抱歉，在下是弗勞爾，諸位就是巨像小隊的人吧。",
  ui_story_5004_50040301_114_dialog_content = "還有空裔PlayerName先生，經常聽黑潮提起你們。",
  ui_story_5004_50040301_115_dialog_content = "你認識黑潮嗎？",
  ui_story_5004_50040301_116_dialog_content = "是的，其實在下本職是紅油扳手的機械師，和黑潮也算是舊識。",
  ui_story_5004_50040301_117_dialog_content = "你就是黑潮剛剛說的機械師吧！（還真的很顯眼……）",
  ui_story_5004_50040301_118_dialog_content = "沒錯，這次我拜託他來幫忙。",
  ui_story_5004_50040301_119_dialog_content = "啊！我想起來了，弗勞爾就是那個啟光機械學院的傳奇人物吧！",
  ui_story_5004_50040301_120_dialog_content = "我聽啟光的前輩提過你。",
  ui_story_5004_50040301_121_dialog_content = "說你不僅非常擅長機械技術，而且性格溫和，<size=40>但好像也有一些</size><size=35>奇怪</size><size=30><color=#FFB400>的負面傳聞</color>……</size>",
  ui_story_5004_50040301_122_dialog_content = "是啊，所以這小子就不知怎地跑來紅油扳手了。",
  ui_story_5004_50040301_123_dialog_content = "他還幫醒山他們修過陸行者號，算是挺厲害的。",
  ui_story_5004_50040301_124_dialog_content = "小子，你不是說有事要忙，跟醒山請了「暑期特別假」嗎？",
  ui_story_5004_50040301_125_dialog_content = "結果跑來這邊當什麼大廳經理……雖說如此，你這身打扮好像有點不太對吧。",
  ui_story_5004_50040301_126_dialog_content = "不該像白夜城貴族那樣人模狗樣地打個小領帶嗎？",
  ui_story_5004_50040301_127_dialog_content = "……",
  ui_story_5004_50040301_128_dialog_content = "（喂喂！這邊還有一位白夜城貴族呢！）",
  ui_story_5004_50040301_129_dialog_content = "我會來主要是受到波娜瑟小姐的邀請，順便還有一些其他原因。",
  ui_story_5004_50040301_130_dialog_content = "有那種被賣了還幫人數錢的感覺，很符合你的性格呢。",
  ui_story_5004_50040301_131_dialog_content = "導遊和司機工作就到這裡，我要去酒吧看看那些音響設備了。",
  ui_story_5004_50040301_132_dialog_content = "沒事的話別來找我。",
  ui_story_5004_50040301_133_dialog_content = "請慢走，蕾吉娜小姐。",
  ui_story_5004_50040301_134_dialog_content = "那麼其他諸位請到這邊。我帶大家到房間去。",
  ui_story_5004_50040301_135_dialog_content = "請問準備怎麼安排呢？",
  ui_story_5004_50040301_136_dialog_content = "那個，我想……",
  ui_story_5004_50040301_137_dialog_content = "我！我要和小拜里厄住一間！",
  ui_story_5004_50040301_138_dialog_content = "我可是小拜里厄的主治醫生喔，一刻都不能離開妳身邊！",
  ui_story_5004_50040301_139_dialog_content = "好不好嘛，好嘛，好嘛~",
  ui_story_5004_50040301_140_dialog_content = "好……好的，我是……沒什麼問題……",
  ui_story_5004_50040301_141_dialog_content = "我和薇絲就一人一間房好了。",
  ui_story_5004_50040301_142_option_content = "那我……",
  ui_story_5004_50040301_143_dialog_content = "你當然是自己睡了。你一個人在臨空者號上睡了十幾年，想必不會怕黑吧。",
  ui_story_5004_50040301_144_dialog_content = "當、當然！我一個人睡就可以！",
  ui_story_5004_50040301_145_option_content = "那蕾吉娜呢？",
  ui_story_5004_50040301_146_dialog_content = "蕾吉娜她應該會沉迷在那些音響設備裡，好幾天無法自拔吧……",
  ui_story_5004_50040301_147_dialog_content = "總之先幫她開好房間吧，我等會再把鑰匙給她。",
  ui_story_5004_50040301_148_dialog_content = "那麼……一共是五間房。",
  ui_story_5004_50040301_149_dialog_content = "小、小費。",
  ui_story_5004_50040301_150_dialog_content = "這幾位是我們飯店的貴賓，不收小費。",
  ui_story_5004_50040301_151_dialog_content = "喔……喔。",
  ui_story_5004_50040301_152_dialog_content = "來，這是幾位的房間鑰匙。",
  ui_story_5004_50040301_153_dialog_content = "剛剛那個侍者怎麼長得有些奇怪……？",
  ui_story_5004_50040301_154_dialog_content = "哈哈，PlayerName先生，不能說那種話喔。",
  ui_story_5004_50040301_155_dialog_content = "畢竟我的頭上也長著角呢。",
  ui_story_5004_50040301_156_dialog_content = "不管怎麼說，我還是希望大家能融洽相處。",
  ui_story_5004_50040301_157_dialog_content = "（還真是老好人的性格啊……）",
  ui_story_5004_50040301_158_dialog_content = "嗯……不過他們的行為舉止確實也有些奇怪。",
  ui_story_5004_50040301_159_dialog_content = "這裡的老闆看中他們，是因為他們的工資要價很低，還接受無償加班。",
  ui_story_5004_50040301_160_dialog_content = "所以毫不猶豫地僱傭了一大批。",
  ui_story_5004_50040301_161_dialog_content = "我剛剛也聽黑潮說這裡的老闆好像很不一般？",
  ui_story_5004_50040301_162_dialog_content = "這裡的老闆啊……好像是影鎮的幫派老大。",
  ui_story_5004_50040301_163_dialog_content = "很有商業頭腦，一心只有賺錢。之前一直有傳言，說他經營這間飯店的同時，也有在做一些……檯面下的事情。",
  ui_story_5004_50040301_164_dialog_content = "雖然我也挺看不慣的，但因為和波娜瑟小姐還有約定，就只能在這裡臨時幫忙了。",
  ui_story_5004_50040301_165_dialog_content = "對了，你們要小心喔，這間飯店和海灘有不少誇張的消費陷阱。",
  ui_story_5004_50040301_166_dialog_content = "也就是所謂的黑心商店吧，我們會小心的。",
  ui_story_5004_50040301_167_dialog_content = "那現在就讓我來帶大家去各自的房間吧。這邊請。",
  ui_story_5004_50040401_168_dialog_content = "請進，PlayerName先生。",
  ui_story_5004_50040401_169_dialog_content = "這裡就是我的房間嗎？",
  ui_story_5004_50040401_170_dialog_content = "希望您滿意。",
  ui_story_5004_50040401_171_dialog_content = "對了，有些關於機械學的問題，我想和您這個巨像所有者討教一下。",
  ui_story_5004_50040401_172_dialog_content = "不過想必您今天已經很累了，我想就約下次再聊吧。",
  ui_story_5004_50040401_173_dialog_content = "現在請先好好休息。有什麼問題可以用那邊的<color=#FFB400>通訊器</color>隨時聯絡櫃台。",
  ui_story_5004_50040401_174_dialog_content = "好的，謝謝你。",
  ui_story_5004_50040401_175_dialog_content = "……",
  ui_story_5004_50040401_176_dialog_content = "房間很乾淨整潔，床看起來也很軟。拉開窗簾就能直接看到外面的海景……",
  ui_story_5004_50040401_177_dialog_content = "這裡的一切和啟光的井然有序和白夜城的雍容華貴都不一樣，而是處處充滿了生機與活力。",
  ui_story_5004_50040401_178_dialog_content = "呼……",
  ui_story_5004_50040401_179_dialog_content = "果然很軟……",
  ui_story_5004_50040401_180_dialog_content = "突然就收到邀請函，來到海邊……躺在這麼舒服的床上……感覺好沒真實感……",
  ui_story_5004_50040401_181_dialog_content = "還有潮汐祭……到底要不要參加呢，總感覺有點奇怪……",
  ui_story_5004_50040401_182_dialog_content = "不知道大家都在做些什麼……",
  ui_story_5004_50040401_183_dialog_content = "<color=#e8d9bb>嘀嘀嘀——</color>",
  ui_story_5004_50040401_184_dialog_content = "嗯？！是什麼在響？這個就是弗勞爾剛剛提到的通訊器嗎？",
  ui_story_5004_50040401_185_dialog_content = "喂……？",
  ui_story_5004_50040401_186_dialog_content = "喂喂喂！！",
  ui_story_5004_50040401_187_dialog_content = "你在傳單上寫的那個什麼……「七天挖掘全部的潛能，成為更強大的自己」，是真的嗎？！",
  ui_story_5004_50040401_188_dialog_content = "嗄？是黑潮嗎？你在說什麼？",
  ui_story_5004_50040401_189_dialog_content = "…………怎麼是PlayerName啊，我弄錯號碼了。",
  ui_story_5004_50040401_190_dialog_content = "下次再聊，我現在有事要忙！",
  ui_story_5004_50040401_191_dialog_content = "<color=#e8d9bb>嘟嘟——</color>",
  ui_story_5004_50040401_192_dialog_content = "怎麼就掛斷了？有點擔心他會不會碰上什麼騙局......",
  ui_story_5004_50040401_193_dialog_content = "這個設備應該也能輸入房號直接打過去吧……",
  ui_story_5004_50040401_194_dialog_content = "就試試看好了——！",
  ui_story_5004_50040401_195_option_content = "打給薇絲",
  ui_story_5004_50040401_196_dialog_content = "喂？是PlayerName嗎？",
  ui_story_5004_50040401_197_dialog_content = "想不到飯店裡還有這麼方便的通訊器。",
  ui_story_5004_50040401_198_dialog_content = "沒有打擾到妳吧，突然閒下來之後有點好奇薇絲在做什麼。",
  ui_story_5004_50040401_199_dialog_content = "也沒做什麼，正躺在床上。這邊的床好舒服啊。",
  ui_story_5004_50040401_200_dialog_content = "那個，潮汐祭的事薇絲怎麼看？我們要參加嗎？",
  ui_story_5004_50040401_201_dialog_content = "當然了！你剛剛也聽弗勞爾說了吧。",
  ui_story_5004_50040401_202_dialog_content = "雖然飯店內住宿是免費的，但是用餐和泳裝啦，還有其他活動都是要收費的。",
  ui_story_5004_50040401_203_dialog_content = "如果只是單純花錢的話，我們的財務狀況本就入不敷出……",
  ui_story_5004_50040401_204_dialog_content = "我、我對運動比賽之類的沒什麼信心……",
  ui_story_5004_50040401_205_dialog_content = "不用擔心啦，有我和大家在呢，我們會努力幫忙的。",
  ui_story_5004_50040401_206_dialog_content = "而且別忘了，PlayerName的指揮能力可是其他人沒有的巨大優勢喔！",
  ui_story_5004_50040401_207_dialog_content = "嗯，也許妳說得對……",
  ui_story_5004_50040401_208_dialog_content = "那如果獎品不是白夜幣怎麼辦？",
  ui_story_5004_50040401_209_dialog_content = "那也沒關係啦，交給涉女士她們設法變賣就好了。",
  ui_story_5004_50040401_210_dialog_content = "放心吧PlayerName，好好休息。我們一定能贏的！",
  ui_story_5004_50040401_211_dialog_content = "既然薇絲都這麼說了，那一起加油吧！",
  ui_story_5004_50040401_212_option_content = "打給卡蓮",
  ui_story_5004_50040401_213_dialog_content = "PlayerName？有什麼事嗎？",
  ui_story_5004_50040401_214_dialog_content = "啊，打擾了。我只是好奇卡蓮正在做什麼。",
  ui_story_5004_50040401_215_dialog_content = "按照我的每日計畫，馬上準備休息了。",
  ui_story_5004_50040401_216_dialog_content = "卡蓮對自己要求很嚴格啊。",
  ui_story_5004_50040401_217_dialog_content = "對了，關於潮汐祭的事，卡蓮妳怎麼看？",
  ui_story_5004_50040401_218_dialog_content = "我們一定會取得優勝。",
  ui_story_5004_50040401_219_dialog_content = "嗄？為什麼這麼說，我們還沒決定要參加吧。",
  ui_story_5004_50040401_220_dialog_content = "為什麼不呢？我們既然接受邀請來到這裡，這便是命運為我們設下的挑戰。",
  ui_story_5004_50040401_221_dialog_content = "真正的戰士從不畏懼任何挑戰。",
  ui_story_5004_50040401_222_dialog_content = "PlayerName，我知道你可能有點困惑或是不安。",
  ui_story_5004_50040401_223_dialog_content = "但你也要相信自己擁有破除困難、開拓前路的力量。",
  ui_story_5004_50040401_224_dialog_content = "你對於包括我在內的所有光靈來說，都是特別的存在。",
  ui_story_5004_50040401_225_dialog_content = "啊，這是在鼓勵我吧……",
  ui_story_5004_50040401_226_dialog_content = "當然，這是戰前激勵。",
  ui_story_5004_50040401_227_dialog_content = "不愧是白夜城的衛隊長大人，我受到鼓舞了。",
  ui_story_5004_50040401_228_dialog_content = "那就好，好好休息。",
  ui_story_5004_50040401_229_dialog_content = "好，既然決定要參加潮汐祭了，那就好好休息吧！",
  ui_story_5004_50040401_230_dialog_content = "說起來，房間都是單人床嗎？",
  ui_story_5004_50040401_230X1_dialog_content = "<color=#e8d9bb>咚——！</color>",
  ui_story_5004_50040401_230X2_dialog_content = "哎唷！",
  ui_story_5004_50040401_230X3_dialog_content = "啊，對不起！沒事吧？",
  ui_story_5004_50040401_230X4_dialog_content = "不過……為什麼要端著盤子一直站在門前呢？這樣很危險的喔！",
  ui_story_5004_50040401_230X5_dialog_content = "呼……呼……拉斐爾……妳跑太快啦……",
  ui_story_5004_50040401_230X6_dialog_content = "是，是這個房間的客人想吃點心，所以我特地送過來的。",
  ui_story_5004_50040401_230X7_dialog_content = "如果沒事的話，我就先回去了，廚房的工作還很忙。",
  ui_story_5004_50040401_230X8_dialog_content = "外面怎麼這麼吵……",
  ui_story_5004_50040401_230X9_dialog_content = "<color=#e8d9bb>咚咚咚</color>",
  ui_story_5004_50040401_231_dialog_content = "那拜里厄她們兩個……",
  ui_story_5004_50040401_232_dialog_content = "PlayerName~我們過來找你玩啦，你怎麼能背著我們偷吃點心嘛。",
  ui_story_5004_50040401_233_dialog_content = "拉斐爾？我沒有在吃點心啊……",
  ui_story_5004_50040401_234_dialog_content = "晚、晚安……",
  ui_story_5004_50040401_235_dialog_content = "拜里厄也來了？",
  ui_story_5004_50040401_236_dialog_content = "小拜里厄不是有話想對PlayerName說嗎~說吧說吧~",
  ui_story_5004_50040401_237_dialog_content = "嗚……這個……這種任性的話……",
  ui_story_5004_50040401_238_dialog_content = "嗯？拜里厄是不好意思說嗎？那就讓拉斐爾代替妳說可以嗎？",
  ui_story_5004_50040401_239_dialog_content = "嗯……",
  ui_story_5004_50040401_240_dialog_content = "好吧~嗯嗯~",
  ui_story_5004_50040401_241_dialog_content = "其實啊，拜里厄很想參加潮汐祭。",
  ui_story_5004_50040401_242_dialog_content = "嗯。",
  ui_story_5004_50040401_243_dialog_content = "但是她又不能參加潮汐祭。",
  ui_story_5004_50040401_244_dialog_content = "嗯嗯？",
  ui_story_5004_50040401_245_dialog_content = "真是的，PlayerName你能不能理解能力再強一點啦！",
  ui_story_5004_50040401_246_dialog_content = "那個……拉斐爾，妳也不要一直責怪PlayerName啦……是我的想法太任性了。",
  ui_story_5004_50040401_247_dialog_content = "PlayerName，你還記得波娜瑟說過的獎勵嗎？",
  ui_story_5004_50040401_248_dialog_content = "啊，拜里厄是缺錢嗎，其實我也——",
  ui_story_5004_50040401_249_dialog_content = "才不是——！是「沙灘勇者」的稱號啦！",
  ui_story_5004_50040401_250_dialog_content = "……",
  ui_story_5004_50040401_251_dialog_content = "你那是什麼表情，你對少女內心天真純潔的嚮往有什麼疑問嗎！",
  ui_story_5004_50040401_252_dialog_content = "哪敢！我只是……一下子沒反應過來而已！",
  ui_story_5004_50040401_253_dialog_content = "拜里厄……是認真的嗎？",
  ui_story_5004_50040401_254_dialog_content = "嗯……！",
  ui_story_5004_50040401_255_dialog_content = "參加是可以……大家正好也都有這個打算。",
  ui_story_5004_50040401_256_dialog_content = "真、真的嗎！",
  ui_story_5004_50040401_257_dialog_content = "太好了……",
  ui_story_5004_50040401_258_dialog_content = "不過妳說妳沒辦法參加，是什麼意思？",
  ui_story_5004_50040401_259_dialog_content = "拜里厄她啊——",
  ui_story_5004_50040401_260_dialog_content = "拉斐爾……我來和PlayerName說就好了，謝謝妳……",
  ui_story_5004_50040401_261_dialog_content = "呼……",
  ui_story_5004_50040401_262_dialog_content = "今天你也應該看到我的能力了……",
  ui_story_5004_50040401_263_dialog_content = "那是……很強大的能力。",
  ui_story_5004_50040401_264_dialog_content = "但也很容易失控，很危險……",
  ui_story_5004_50040401_265_dialog_content = "釋放出的力量愈強，對我的情緒和身體的影響就愈大……",
  ui_story_5004_50040401_266_dialog_content = "今天幫助大家的時候，因為同時對付太多的暗鬼……最近幾天都沒法做劇烈的運動了……",
  ui_story_5004_50040401_267_dialog_content = "原來如此。我知道了。既然妳幫助了大家，那大家一定也會願意幫助妳！",
  ui_story_5004_50040401_268_dialog_content = "我會和其他人溝通，讓拜里厄以替補隊員的身分參加比賽。",
  ui_story_5004_50040401_269_dialog_content = "要不要上場就由妳根據自己的身體情況判斷。",
  ui_story_5004_50040401_270_dialog_content = "這樣可以嗎？",
  ui_story_5004_50040401_271_dialog_content = "嗯！",
  ui_story_5004_50040401_272_dialog_content = "另外我還想問問，妳剛剛提到會對情緒造成影響，具體來說是什麼影響？",
  ui_story_5004_50040401_273_dialog_content = "……會變得非常悲傷和絕望，同時力量也會更強……也更容易失去控制。",
  ui_story_5004_50040401_274_dialog_content = "這不成了惡性循環了嗎……",
  ui_story_5004_50040401_275_dialog_content = "嗯……",
  ui_story_5004_50040401_276_dialog_content = "那……希望妳有一天能夠擺脫悲傷與絕望，鼓起勇氣控制自己的力量。",
  ui_story_5004_50040401_277_dialog_content = "很期待那個時候妳的力量，會有怎樣的變化。",
  ui_story_5004_50040501_1_dialog_content = "……",
  ui_story_5004_50040501_2_dialog_content = "……",
  ui_story_5004_50040501_3_dialog_content = "……在巨像之外的地方睡覺果然還是不太習慣。",
  ui_story_5004_50040501_4_option_content = "試著起床",
  ui_story_5004_50040501_5_dialog_content = "<color=#e8d9bb>咚咚咚——</color>",
  ui_story_5004_50040501_6_dialog_content = "PlayerName，你醒了嗎？",
  ui_story_5004_50040501_7_option_content = "再次試著起床",
  ui_story_5004_50040501_8_dialog_content = "嗯……等我過來開門。",
  ui_story_5004_50040501_9_dialog_content = "<color=#e8d9bb>喀噠</color>",
  ui_story_5004_50040501_10_dialog_content = "PlayerName早。快收拾一下吧。",
  ui_story_5004_50040501_11_dialog_content = "卡蓮她們都在餐廳等著了。",
  ui_story_5004_50040501_12_dialog_content = "早安，PlayerName，你看起來休息得不是很好。",
  ui_story_5004_50040501_13_dialog_content = "早，我還不是很適應在巨像之外的地方入睡……",
  ui_story_5004_50040501_14_dialog_content = "不過沒關係，能有這樣獨特的體驗我還是很高興。",
  ui_story_5004_50040501_15_dialog_content = "在遇到薇絲和卡蓮之後，我體驗到了許許多多以前不曾想過的事。",
  ui_story_5004_50040501_16_dialog_content = "PlayerName突然這麼一本正經地說話，感覺好成熟啊。",
  ui_story_5004_50040501_17_dialog_content = "莫非這裡的海風帶著某種「魔力」嗎？",
  ui_story_5004_50040501_18_dialog_content = "啊哈哈哈……也可能只是單純沒睡好吧。",
  ui_story_5004_50040501_19_dialog_content = "拉斐爾和拜里厄呢？",
  ui_story_5004_50040501_20_option_content = "睡得還好嗎？",
  ui_story_5004_50040501_21_dialog_content = "嗯……雖然床有點擠……",
  ui_story_5004_50040501_22_dialog_content = "（果然是單人床吧。）",
  ui_story_5004_50040501_23_dialog_content = "PlayerName，你知道嗎！拜里厄是睡覺喜歡抱著東西的類型~",
  ui_story_5004_50040501_24_dialog_content = "抱、抱著枕頭睡覺很正常吧……！",
  ui_story_5004_50040501_25_option_content = "妳們那邊是雙人床嗎？",
  ui_story_5004_50040501_26_dialog_content = "不是的，稍微……有點擠……",
  ui_story_5004_50040501_27_dialog_content = "因為單人床上除了拜里厄、拉斐爾，還有個巨——大的抱枕。",
  ui_story_5004_50040501_28_dialog_content = "那是我的……",
  ui_story_5004_50040501_29_dialog_content = "沒想到拜里厄會是睡覺喜歡抱著東西的類型啊。",
  ui_story_5004_50040501_30_dialog_content = "抱、抱著枕頭睡覺很正常吧……！",
  ui_story_5004_50040501_31_dialog_content = "前半夜確實是枕頭啦。",
  ui_story_5004_50040501_32_dialog_content = "請、請不要再說了——！",
  ui_story_5004_50040501_33_dialog_content = "各位早，請問休息得還好嗎。",
  ui_story_5004_50040501_34_dialog_content = "啊，早安，弗勞爾。",
  ui_story_5004_50040501_35_dialog_content = "還不錯，房間設施很齊全，床鋪也很舒服。",
  ui_story_5004_50040501_36_dialog_content = "但總是覺得不太習慣。",
  ui_story_5004_50040501_37_dialog_content = "哈哈哈，有很多客人都會這樣。畢竟現在對大家來說，不是能輕易外出旅行的時候。",
  ui_story_5004_50040501_38_dialog_content = "外面到處都是遊蕩的暗鬼，只有待在自己的居所時才比較有安全感吧。",
  ui_story_5004_50040501_39_dialog_content = "有道理。對了，卡蓮之前說過，飯店裡有<color=#FFB400>泳裝商店</color>吧。",
  ui_story_5004_50040501_40_dialog_content = "弗勞爾知道商店在哪裡嗎？",
  ui_story_5004_50040501_41_dialog_content = "當然，就在<color=#FFB400>餐廳的東北側</color>。",
  ui_story_5004_50040501_42_dialog_content = "好，那我們吃完飯就出發——！",
  ui_story_5004_50040501_43_dialog_content = "好——！！",
  ui_story_5004_50040601_44_dialog_content = "女孩子挑衣服都要這麼久嗎？",
  ui_story_5004_50040601_45_dialog_content = "叫我來<color=#FFB400>沙灘</color>這邊等著，但好像已經等了快一個多小時了吧……",
  ui_story_5004_50040601_46_dialog_content = "陽光有點強，不過這樣悠閒地曬太陽也不錯……",
  ui_story_5004_50040601_47_dialog_content = "薇絲她們就像是我的老朋友一樣……像這樣不用考慮暗鬼和它們的陰謀……",
  ui_story_5004_50040601_48_dialog_content = "安適地享受太陽和海風，真是太舒服啦……",
  ui_story_5004_50040601_49_dialog_content = "……",
  ui_story_5004_50040601_50_dialog_content = "沙子摸起來暖洋洋的，來畫點什麼吧。",
  ui_story_5004_50040601_51_dialog_content = "PlayerName，你畫的是什麼？章魚嗎？",
  ui_story_5004_50040601_52_dialog_content = "不是啦，是貓，是貓！",
  ui_story_5004_50040601_53_dialog_content = "啊，那些歪歪扭扭的觸手原來是鬍鬚嗎？！",
  ui_story_5004_50040601_54_dialog_content = "我來幫你把鬍鬚畫漂亮一點吧。",
  ui_story_5004_50040601_55_dialog_content = "啊啊~別用腳啊，哪有比手臂還粗的鬍子！真是的，薇絲——",
  ui_story_5004_50040601_56_dialog_content = "……",
  ui_story_5004_50040601_57_dialog_content = "嗯？",
  ui_story_5004_50040601_58_dialog_content = "還、還可以啦。",
  ui_story_5004_50040601_59_dialog_content = "什麼還可以啦？",
  ui_story_5004_50040601_60_dialog_content = "PlayerName，你看起來怪怪的。",
  ui_story_5004_50040601_61_dialog_content = "算了~還是好好享受這海風比較要緊呀。",
  ui_story_5004_50040601_62_dialog_content = "果然泳裝配上大海，才是充滿夏日氣息的假期——",
  ui_story_5004_50040601_63_dialog_content = "在我看來，妳的泳裝並不能稱為「沙灘金甲」！",
  ui_story_5004_50040601_64_dialog_content = "PlayerName！好好看著吧，讓我教教你什麼才叫不畏巨浪的騎士——！",
  ui_story_5004_50040601_65_dialog_content = "（儘管原因不同，但卡蓮似乎也很興奮……）",
  ui_story_5004_50040601_66_dialog_content = "（還主動讓我盯著泳裝看……這卡蓮也太投入了吧？）",
  ui_story_5004_50040601_67_dialog_content = "PlayerName，你感覺怎麼樣？",
  ui_story_5004_50040601_68_dialog_content = "什、什麼怎麼樣啊？",
  ui_story_5004_50040601_69_dialog_content = "當然是指泳裝，你認為誰是能征服這片沙灘的勇者？",
  ui_story_5004_50040601_70_option_content = "薇絲的泳裝看起來非常活潑可愛。",
  ui_story_5004_50040601_72_dialog_content = "原來PlayerName你喜歡這種嗎？",
  ui_story_5004_50040601_73_dialog_content = "不過薇絲確實在學校時就以精力充沛而聞名。",
  ui_story_5004_50040601_74_dialog_content = "像是雙倍完成體能訓練目標，或是通宵幾夜複習功課這樣的事，她都做過。",
  ui_story_5004_50040601_75_dialog_content = "當然啦，論精力和努力的話我可是不會輸的！",
  ui_story_5004_50040601_76_option_content = "還是卡蓮的泳裝看起來更為高貴優雅。",
  ui_story_5004_50040601_78_dialog_content = "我也是這麼認為！",
  ui_story_5004_50040601_79_dialog_content = "如果不是卡蓮這種經過嚴格禮儀訓練的人，是無法展現出如此高貴優雅的氣質的。",
  ui_story_5004_50040601_80_dialog_content = "畢竟啟光培養的是令行禁止的軍人氣質，和白夜城的風格不同啦。",
  ui_story_5004_50040601_81_dialog_content = "身為一名啟光軍人，薇絲在學時的理科成績可是緊緊咬在我後面呢。",
  ui_story_5004_50040601_82_dialog_content = "嘿嘿，我就是比較擅長這些嘛。",
  ui_story_5004_50040601_83_dialog_content = "然而藝術相關的科目就完全不行。",
  ui_story_5004_50040601_84_dialog_content = "這個……還不是因為白夜城沒開機械製圖相關的藝術課程。",
  ui_story_5004_50040601_85_dialog_content = "那算藝術課程嗎？！除了啟光，哪裡都不會開的吧！",
  ui_story_5004_50040601_86_dialog_content = "但……但是我說不定有音樂天分呀！你看我還幫PlayerName啟動過巨像！",
  ui_story_5004_50040601_87_dialog_content = "好的好的，那我代表自己以及臨空者號再次謝謝薇絲中尉。",
  ui_story_5004_50040601_88_dialog_content = "多虧有妳，大家才能有機會在海邊嬉戲呢。",
  ui_story_5004_50040601_89_dialog_content = "大家久等啦~",
  ui_story_5004_50040601_90_dialog_content = "拉斐爾？妳沒換泳裝嗎？",
  ui_story_5004_50040601_91_dialog_content = "拉斐爾可是工作中的醫生，怎麼能隨便換上泳裝和需要照料的人一起肆無忌憚地玩嘛。",
  ui_story_5004_50040601_92_dialog_content = "原來如此，那拜里厄呢？",
  ui_story_5004_50040601_93_dialog_content = "欸，拜里厄？",
  ui_story_5004_50040601_94_dialog_content = "喂~小拜里厄，快過來啦。",
  ui_story_5004_50040601_95_dialog_content = "不……不行啊這個，太讓人害羞了吧……",
  ui_story_5004_50040601_96_dialog_content = "我還沒穿過……露出這麼多肌膚的衣服……",
  ui_story_5004_50040601_97_dialog_content = "不用害羞啦！明明很可愛吧！",
  ui_story_5004_50040601_98_dialog_content = "對不對！PlayerName！",
  ui_story_5004_50040601_99_dialog_content = "嗯，感覺整個人的氣質都不一樣了，很適合妳。",
  ui_story_5004_50040601_100_dialog_content = "沒錯，就連我也很難否定妳現在是一名合格的騎士了。",
  ui_story_5004_50040601_101_dialog_content = "這種量身剪裁的設計，行動起來應該非常方便吧。",
  ui_story_5004_50040601_102_dialog_content = "我也同意，比拜里厄平時穿的那身衣服看起來可愛多啦。",
  ui_story_5004_50040601_103_dialog_content = "就穿著這身可愛的泳裝和我們一起去游泳吧。",
  ui_story_5004_50040601_104_dialog_content = "看吧~大家都覺得小拜里厄現在的樣子比較可愛呢。",
  ui_story_5004_50040601_105_dialog_content = "而且大家都穿成這樣啦~",
  ui_story_5004_50040601_106_dialog_content = "那、那也……",
  ui_story_5004_50040601_107_dialog_content = "好吧……",
  ui_story_5004_50040601_108_dialog_content = "好啦，小拜里厄~不要一直在意這種事！",
  ui_story_5004_50040601_108X1_dialog_content = "<color=#e8d9bb>喀嚓</color>",
  ui_story_5004_50040601_108X2_dialog_content = "<color=#e8d9bb>喀嚓、喀嚓</color>",
  ui_story_5004_50040601_108X3_dialog_content = "嗯？那個是昨天的侍者？",
  ui_story_5004_50040601_108X4_dialog_content = "他手裡拿著的是相機吧~我在白夜城的時候看過類似的東西！",
  ui_story_5004_50040601_108X5_dialog_content = "有點奇怪……他為什麼趴著在那裡拍照呀？",
  ui_story_5004_50040601_108X6_dialog_content = "可能是在拍攝一些風景照用作宣傳？我去試著把相機借來拍一張吧！",
  ui_story_5004_50040601_108X7_dialog_content = "這、這些女孩子……泳裝照、應該夠……業績……",
  ui_story_5004_50040601_108X8_dialog_content = "打擾啦~",
  ui_story_5004_50040601_108X9_dialog_content = "嗚咦！！",
  ui_story_5004_50040601_108X10_dialog_content = "欸？怎麼我都還沒開口借，就自己丟進我手裡了？",
  ui_story_5004_50040601_108X11_dialog_content = "是要借給我用嗎？那我就不客氣啦！",
  ui_story_5004_50040601_108X12_dialog_content = "是、是嚇到……",
  ui_story_5004_50040601_108X13_dialog_content = "那……還、還給我……",
  ui_story_5004_50040601_108X14_dialog_content = "拉斐爾……他看起來很困擾的樣子，還是把相機還回去吧……？",
  ui_story_5004_50040601_108X15_dialog_content = "小拜里厄還真是溫柔善良~這次可別再丟出來了喔。",
  ui_story_5004_50040601_108X16_dialog_content = "謝、謝謝……",
  ui_story_5004_50040601_109_dialog_content = "好啦~那我們去玩吧，小拜里厄。",
  ui_story_5004_50040601_110_dialog_content = "我們也走吧，PlayerName。",
  ui_story_5004_50040601_111_dialog_content = "嗯！",
  ui_story_5004_50040701_1_dialog_content = "她們為什麼體力這麼充沛……",
  ui_story_5004_50040701_2_dialog_content = "（薇絲如同裝了推進器一般，戴著游泳圈在海面上一邊游泳一邊激起誇張的水花。）",
  ui_story_5004_50040701_3_dialog_content = "（而卡蓮則是不停用長槍挑起各種我不認識的水生生物。）",
  ui_story_5004_50040701_4_dialog_content = "（再把那些比自己身體還大的生物甩到岸上。）",
  ui_story_5004_50040701_5_dialog_content = "（就連拜里厄和拉斐爾，也開心地在撿貝殼和堆沙堡。）",
  ui_story_5004_50040701_6_dialog_content = "（不得不說，拜里厄堆出來的那個沙堡外形看起來超厲害……）",
  ui_story_5004_50040701_7_dialog_content = "（不光充滿犬牙交錯的尖刺，還有一座巨大的鐘塔。）",
  ui_story_5004_50040701_X7_dialog_content = "（非常像是什麼邪惡勢力的城堡……）",
  ui_story_5004_50040701_8_dialog_content = "話說回來，可能……真的是我身體太虛弱了？",
  ui_story_5004_50040701_9_dialog_content = "在巨像裡也沒有什麼體力活動……",
  ui_story_5004_50040701_10_dialog_content = "戰鬥的時候也都是擔任指揮的角色……",
  ui_story_5004_50040701_11_dialog_content = "也許我該沿著沙灘跑幾圈鍛鍊一下身體。",
  ui_story_5004_50040701_12_dialog_content = "嗨~這不是偉大的巨像之主、啟光未來的將軍、白夜城的守護者，兼……",
  ui_story_5004_50040701_13_dialog_content = "紅油扳手未來老大的好兄弟——PlayerName老弟嘛。",
  ui_story_5004_50040701_14_dialog_content = "黑潮？你怎麼來了？",
  ui_story_5004_50040701_15_dialog_content = "你不是還要幫弗勞爾嗎？",
  ui_story_5004_50040701_16_dialog_content = "順便一提，我可不覺得你會打贏醒山成為紅油扳手的新老大。",
  ui_story_5004_50040701_17_dialog_content = "PlayerName，雖然你指揮作戰有一套，但是看人的眼光還是不行啊。",
  ui_story_5004_50040701_18_dialog_content = "醒山他已經開始走下坡路了，而我，正是冉冉升起的新星——！",
  ui_story_5004_50040701_X18_dialog_content = "敗\n北",
  ui_story_5004_50040701_19_dialog_content = "現在紅油扳手裡已經有很多人支持我了。",
  ui_story_5004_50040701_20_dialog_content = "很多人嗎……有誰？",
  ui_story_5004_50040701_21_dialog_content = "……有弗勞爾。",
  ui_story_5004_50040701_22_dialog_content = "……",
  ui_story_5004_50040701_23_dialog_content = "……還有呢。",
  ui_story_5004_50040701_24_dialog_content = "弗勞爾、弗勞爾和弗勞爾。喔，可以趁這個機會再和蕾吉娜談談！",
  ui_story_5004_50040701_25_dialog_content = "蕾吉娜應該不會想和你聊這個。",
  ui_story_5004_50040701_26_dialog_content = "那就和你聊聊。",
  ui_story_5004_50040701_27_dialog_content = "然後就可以宣傳說自己得到了空裔一族的支持嗎？",
  ui_story_5004_50040701_28_dialog_content = "欸，PlayerName，在我認識的空裔裡你應該是最聰明的！",
  ui_story_5004_50040701_29_dialog_content = "這個就省省吧，你也不認識別的空裔吧！",
  ui_story_5004_50040701_30_dialog_content = "……噓。",
  ui_story_5004_50040701_31_dialog_content = "……？",
  ui_story_5004_50040701_32_dialog_content = "PlayerName，你看到<color=#FFB400>那個人</color>了嗎？",
  ui_story_5004_50040701_33_dialog_content = "那個女孩子？",
  ui_story_5004_50040701_34_dialog_content = "對，感覺鬼鬼祟祟的……好像到處在翻看著什麼。",
  ui_story_5004_50040701_35_dialog_content = "沒有吧……說不定她只是在找丟了的東西。",
  ui_story_5004_50040701_36_dialog_content = "你見過把跟人一樣高的石頭翻開找東西的嗎？",
  ui_story_5004_50040701_37_dialog_content = "走，過去看看。",
  ui_story_5004_50040701_38_option_content = "好吧。",
  ui_story_5004_50040701_39_dialog_content = "不過你為什麼這麼在意她啊。",
  ui_story_5004_50040701_40_dialog_content = "萬一是小偷呢？",
  ui_story_5004_50040701_41_dialog_content = "翻開一個人高的石頭是要偷什麼？！誰會在那下面藏東西啊！",
  ui_story_5004_50040701_42_dialog_content = "我可不記得紅油扳手的你這麼有正義感。",
  ui_story_5004_50040701_43_dialog_content = "現在不一樣了，我接受了弗勞爾的委託，現在可是<color=#FFB400>天堂階梯海灘的保全大人</color>！",
  ui_story_5004_50040701_44_dialog_content = "……（究竟是哪個天才找紅油扳手的人來當保全的？）",
  ui_story_5004_50040701_45_option_content = "還是不要多管閒事了吧",
  ui_story_5004_50040701_46_dialog_content = "我可不記得紅油扳手的你這麼有正義感。",
  ui_story_5004_50040701_47_dialog_content = "現在不一樣了，我接受了弗勞爾的委託，現在可是<color=#FFB400>天堂階梯海灘的保全大人</color>！",
  ui_story_5004_50040701_48_dialog_content = "……（究竟是哪個天才找紅油扳手的人來當保全的？）",
  ui_story_5004_50040701_49_dialog_content = "別廢話了，跟緊點。",
  ui_story_5004_50040701_50_dialog_content = "喂，那個可疑的傢伙。",
  ui_story_5004_50040701_51_dialog_content = "……",
  ui_story_5004_50040701_52_dialog_content = "喂！",
  ui_story_5004_50040701_53_dialog_content = "別碰我！",
  ui_story_5004_50040701_54_dialog_content = "PlayerName，你看到了！是這傢伙先動手的——！",
  ui_story_5004_50040701_55_dialog_content = "等等，你不是躲開了嗎。先別使用暴力。",
  ui_story_5004_50040701_56_dialog_content = "你是誰啊，還有這個傻子是什麼人。",
  ui_story_5004_50040701_57_dialog_content = "突然對人大吼大叫，還想隨便亂碰淑女的肩膀。",
  ui_story_5004_50040701_58_dialog_content = "想搭訕的話找別人去！我可不是你們惹得起的。",
  ui_story_5004_50040701_59_dialog_content = "PlayerName，你讓開！我要把這小丫頭綁在車後面拖著兜風！",
  ui_story_5004_50040701_60_dialog_content = "好啊，我正想找人出氣——",
  ui_story_5004_50040701_61_dialog_content = "呵呵呵……<color=#FFB400>斯莫奇</color>，想不到許久不見，妳居然和這種粗俗的傢伙混在一起了啊。",
  ui_story_5004_50040701_62_dialog_content = "妳這樣也配得上貴族的身分嗎？",
  ui_story_5004_50040701_63_dialog_content = "妳又是誰啊……我是不是貴族關妳什麼事。",
  ui_story_5004_50040701_64_dialog_content = "什、什麼！妳居然不記得我了？",
  ui_story_5004_50040701_65_dialog_content = "喂，我們的事還——",
  ui_story_5004_50040701_66_dialog_content = "你先別吵！",
  ui_story_5004_50040701_67_dialog_content = "再看清楚點！",
  ui_story_5004_50040701_68_dialog_content = "沒印象，妳也離我遠一點。",
  ui_story_5004_50040701_69_dialog_content = "我是<color=#FFB400>吉納維芙</color>！<color=#FFB400>沃倫斯奇家族</color>的<color=#FFB400>吉納維芙</color>！",
  ui_story_5004_50040701_70_dialog_content = "喔……我想想……",
  ui_story_5004_50040701_71_dialog_content = "佩德羅堡的……",
  ui_story_5004_50040701_72_dialog_content = "啊，佩德羅堡的！",
  ui_story_5004_50040701_73_dialog_content = "<size=30>PlayerName，這兩個傢伙怎麼回事……</size>",
  ui_story_5004_50040701_74_dialog_content = "<size=30>我哪知道……</size>",
  ui_story_5004_50040701_75_dialog_content = "啊！想起來了！吉納維芙！長高了不少嘛。",
  ui_story_5004_50040701_76_dialog_content = "什、什麼……妳這種讓人火大的態度……！！",
  ui_story_5004_50040701_77_dialog_content = "我和我的家族竟然會因為妳這種傢伙而顏面掃地……榮耀盡失！",
  ui_story_5004_50040701_78_dialog_content = "妳在說什麼啊，這個我真的不記得了。",
  ui_story_5004_50040701_79_dialog_content = "啊，剛剛想妳的事用腦過度了，頭好痛。",
  ui_story_5004_50040701_80_dialog_content = "嗯，啊！對了，我失憶了，這樣可以嗎？",
  ui_story_5004_50040701_81_dialog_content = "那麼就告辭啦，變得如此美麗的吉納維芙小姐——！",
  ui_story_5004_50040701_82_dialog_content = "站住！不准走！",
  ui_story_5004_50040701_83_dialog_content = "……",
  ui_story_5004_50040701_84_dialog_content = "你看我也沒用啊……！",
  ui_story_5004_50040701_85_dialog_content = "喂？不要拉我。雖然我不會對女士出手。",
  ui_story_5004_50040701_86_dialog_content = "但是被人看到這樣拉拉扯扯的樣子我會很困擾的。",
  ui_story_5004_50040701_87_dialog_content = "萬一人家誤會我們的關係該怎麼辦？",
  ui_story_5004_50040701_88_dialog_content = "斯莫奇！！",
  ui_story_5004_50040701_89_dialog_content = "我絕對饒不了妳！！",
  ui_story_5004_50040701_90_dialog_content = "PlayerName，要開打了。",
  ui_story_5004_50040701_91_dialog_content = "你為什麼表現出一副很期待的樣子……",
  ui_story_5004_50040701_92_dialog_content = "你不懂。在紅油扳手，這是溝通感情和證明實力的重要運動。",
  ui_story_5004_50040701_93_dialog_content = "隨便吧……不過我感覺金髮那個會贏。",
  ui_story_5004_50040701_94_dialog_content = "為什麼？",
  ui_story_5004_50040701_95_dialog_content = "這就是所謂空裔的直覺啦。",
  ui_story_5004_50040701_96_dialog_content = "這可是你不懂了，你看那個叫斯莫奇的銀髮女孩。",
  ui_story_5004_50040701_97_dialog_content = "她步伐穩健，即使在平時的舉手投足間也毫無破綻。",
  ui_story_5004_50040701_98_dialog_content = "加上她遊刃有餘的自信眼神，必定不是泛泛之輩。",
  ui_story_5004_50040701_99_dialog_content = "而金髮女孩雖然盛氣凌人，但無法控制自己的情緒，就意味著無法控制自己的力量。",
  ui_story_5004_50040701_100_dialog_content = "想必她對光能術的掌握還欠缺火候。",
  ui_story_5004_50040701_101_dialog_content = "你的語氣突然好奇怪……在哪學會這麼多詞的？",
  ui_story_5004_50040701_102_dialog_content = "嘎喔——",
  ui_story_5004_50040701_103_dialog_content = "別礙事！",
  ui_story_5004_50040701_103X_dialog_content = "這裡怎麼也有暗鬼？！",
  ui_story_5004_50040701_103X1_dialog_content = "這個有什麼好大驚小怪的，你就當做暗鬼是這裡的特產吧。",
  ui_story_5004_50040701_104_dialog_content = "好傢伙，這個叫吉納維芙的確實有兩把刷子。",
  ui_story_5004_50040701_105_dialog_content = "喂，你背後還有暗鬼！",
  ui_story_5004_50040701_106_dialog_content = "我說啊，黑潮你不是保全嗎？就這樣看熱鬧沒關係嗎？",
  ui_story_5004_50040701_107_dialog_content = "喔，對了！我差點都忘了！",
  ui_story_5004_50040701_108_dialog_content = "好了，暗鬼雜碎們，準備好被一個個捏進沙子裡了嗎——！",
  ui_story_5004_50040701_109_dialog_content = "轉速全開！！！",
  ui_story_5004_50040701_110_dialog_content = "兩個人聯手一下就收拾掉了呢！",
  ui_story_5004_50040701_111_dialog_content = "當然了，小意思。",
  ui_story_5004_50040701_112_dialog_content = "你沒事吧。",
  ui_story_5004_50040701_113_dialog_content = "呿……誰叫你們出手搗亂的啊！",
  ui_story_5004_50040701_114_dialog_content = "就因為你這傢伙突然攪局，讓斯莫奇那傢伙趁亂跑了！",
  ui_story_5004_50040701_115_dialog_content = "對……對不起！",
  ui_story_5004_50040701_116_dialog_content = "氣死了！不要和我說話！",
  ui_story_5004_50040701_117_dialog_content = "我一定要弄清楚那傢伙在幹什麼……然後徹徹底底粉碎她的陰謀……！",
  ui_story_5004_50040701_118_dialog_content = "謝謝！告辭！",
  ui_story_5004_50040701_119_dialog_content = "走掉了……",
  ui_story_5004_50040701_120_dialog_content = "PlayerName，你看到了嗎，那就是兩個女人之間的感情，遠比任何暗鬼都可怕。",
  ui_story_5004_50040701_121_dialog_content = "我奉勸你還是不要趟這渾水。",
  ui_story_5004_50040701_122_dialog_content = "我壓根也沒想……",
  ui_story_5004_50040701_123_dialog_content = "好吃——！",
  ui_story_5004_50040701_124_dialog_content = "嘴角沾到湯汁了，我幫妳擦。",
  ui_story_5004_50040701_125_dialog_content = "唔……謝謝！",
  ui_story_5004_50040701_126_dialog_content = "畢竟啟光大食堂都沒有這麼好吃的東西，我根本控制不住！",
  ui_story_5004_50040701_127_dialog_content = "特別是打飯的大姐姐，每次勺子都抖個不停，把本就少得可憐的肉類都抖回去。",
  ui_story_5004_50040701_128_dialog_content = "我可是還在發育啊——！",
  ui_story_5004_50040701_129_dialog_content = "怪不得妳來白夜城留學之後就整天沉迷在內院餐廳裡。",
  ui_story_5004_50040701_132_dialog_content = "弗勞爾，也別一直站在這裡服侍我們了，既然是朋友就坐下來一起吃吧。",
  ui_story_5004_50040701_133_dialog_content = "這可不行。諸位現在是飯店的貴客，而我現在最主要的工作就是服侍好諸位。",
  ui_story_5004_50040701_134_dialog_content = "可是……",
  ui_story_5004_50040701_135_dialog_content = "別管他了，PlayerName。",
  ui_story_5004_50040701_136_dialog_content = "大家都知道他就是這樣的人，不如說他也樂在其中。",
  ui_story_5004_50040701_137_dialog_content = "黑潮，你想喝點什麼？",
  ui_story_5004_50040701_138_dialog_content = "超冰嗨士忌！",
  ui_story_5004_50040701_139_dialog_content = "好的，馬上就來。",
  ui_story_5004_50040701_140_dialog_content = "……",
  ui_story_5004_50040701_141_dialog_content = "PlayerName，你怎麼臉紅了？",
  ui_story_5004_50040701_142_dialog_content = "沒、沒有啊！",
  ui_story_5004_50040701_143_dialog_content = "看來你們空裔也沒辦法倖免於那傢伙的影響啊。",
  ui_story_5004_50040701_144_dialog_content = "影響……你是什麼意思？",
  ui_story_5004_50040701_145_dialog_content = "你還是當面問那傢伙比較好。",
  ui_story_5004_50040701_146_dialog_content = "話說回來，下午那兩個女人到底怎麼回事啊。",
  ui_story_5004_50040701_147_dialog_content = "我怎麼知道……我也不認識啊。",
  ui_story_5004_50040701_148_dialog_content = "真的非常可疑，那個踢了我的傢伙明顯是在四處尋找什麼。",
  ui_story_5004_50040701_149_dialog_content = "我要把車鑰匙換個地方埋。",
  ui_story_5004_50040701_150_dialog_content = "才沒人想偷你的車吧！",
  ui_story_5004_50040701_151_dialog_content = "嗯？到處找東西的人嗎？我和拜里厄下午也看到一個呢。",
  ui_story_5004_50040701_152_dialog_content = "對吧，小拜里厄。",
  ui_story_5004_50040701_153_dialog_content = "嗯……灰白色頭髮……戴著墨鏡……一副生人勿近的樣子……有點可怕……",
  ui_story_5004_50040701_154_dialog_content = "（聽起來是同一個人。）",
  ui_story_5004_50040701_155_dialog_content = "PlayerName，那傢伙真的很過分，到處探頭探腦又很冒失。",
  ui_story_5004_50040701_156_dialog_content = "還一腳踩壞了拜里厄辛辛苦苦堆出來的沙堡！",
  ui_story_5004_50040701_157_dialog_content = "那可是超過三公尺高的超——壯觀沙堡喔，有這~麼大！這~麼大！",
  ui_story_5004_50040701_158_dialog_content = "沒關係啦，那個人也認真和我道歉了。",
  ui_story_5004_50040701_159_dialog_content = "但是！那可是拜里厄堆了一下午的城堡耶！",
  ui_story_5004_50040701_160_dialog_content = "嗯……沒關係，能像這樣無拘無束地放鬆心情……我……已經很開心了。",
  ui_story_5004_50040701_161_dialog_content = "而且那個城堡……好像一直都在我的腦海裡……只要閉上眼睛就能看到它的樣子。",
  ui_story_5004_50040701_162_dialog_content = "如果拉斐爾喜歡的話……明天我也可以再堆一個……",
  ui_story_5004_50040701_163_dialog_content = "欸！真的嗎？那下次我還要跟拜里厄一起玩沙。",
  ui_story_5004_50040701_164_dialog_content = "嗯……",
  ui_story_5004_50040701_165_dialog_content = "結果還是不知道那傢伙是誰，有什麼企圖。",
  ui_story_5004_50040701_166_dialog_content = "那就算了吧，黑潮你不用那麼在意吧。",
  ui_story_5004_50040701_167_dialog_content = "我可是答應了弗勞爾那傢伙認真做好保全工作的。",
  ui_story_5004_50040701_168_dialog_content = "（明明就開小差跑來找我……）",
  ui_story_5004_50040701_169_dialog_content = "黑潮確實是接受了我的委託才來的。",
  ui_story_5004_50040701_170_dialog_content = "您的酒，加了整塊方冰，請用。",
  ui_story_5004_50040701_171_dialog_content = "我就說我可是很重視約定的……噗！！！！",
  ui_story_5004_50040701_172_dialog_content = "這東西！什麼玩意？！",
  ui_story_5004_50040701_173_dialog_content = "啊，抱歉，這邊沒有平時加的汽油，所以我就用真的酒代替了！",
  ui_story_5004_50040701_174_dialog_content = "所以黑潮平時都是喝汽油飲料的嗎？紅油扳手的人真不得了……",
  ui_story_5004_50040701_175_dialog_content = "這杯是您的，PlayerName先生。",
  ui_story_5004_50040701_176_dialog_content = "這是特調迎賓飲料。",
  ui_story_5004_50040701_177_dialog_content = "特調……這個真的沒有汽油嗎？",
  ui_story_5004_50040701_178_dialog_content = "你不用擔心，不含酒也不含汽油，無論是小孩還是老人都能夠放心享用。",
  ui_story_5004_50040701_X178_dialog_content = "你真是太貼心了！",
  ui_story_5004_50040701_179_dialog_content = "另外，如果您方便的話……我希望盡快找個時間和PlayerName單獨聊聊。",
  ui_story_5004_50040701_180_dialog_content = "倒是有時間。",
  ui_story_5004_50040701_181_dialog_content = "（奇妙的酸甜口味……還混合著柑類的芬芳，尾韻也充滿了層次。）",
  ui_story_5004_50040701_182_dialog_content = "（真是複雜的飲料……）",
  ui_story_5004_50040901_1_dialog_content = "不行，得起來了……",
  ui_story_5004_50040901_2_dialog_content = "又在零件堆裡睡著了，齒輪的尖角扎得背好痛。",
  ui_story_5004_50040901_3_dialog_content = "這張圖……是昨天晚上畫的吧。嗯……",
  ui_story_5004_50040901_4_dialog_content = "沒什麼用，扔進垃圾桶吧。",
  ui_story_5004_50040901_5_dialog_content = "果然還是需要依靠<color=#FFB400>空裔的知識</color>……",
  ui_story_5004_50040901_6_dialog_content = "光是對啟光和白夜城的機器人進行的分析，根本無法製造出我心中理想的「那個」。",
  ui_story_5004_50040901_7_dialog_content = "先洗個澡吧……等會和PlayerName還有約。",
  ui_story_5004_50040901_8_dialog_content = "如果不能順利完成潮汐祭……我就無法擺脫<color=#FFB400>特殊體質</color>的影響。",
  ui_story_5004_50040901_9_dialog_content = "（本來我應該是一介普通的啟光機械師……）",
  ui_story_5004_50040901_10_dialog_content = "（但因為這種隔代遺傳的「特殊體質」……）",
  ui_story_5004_50040901_11_dialog_content = "（在學校的時候……）",
  ui_story_5004_50040901_12_dialog_content = "弗勞爾，<size=45>弗勞爾</size>！",
  ui_story_5004_50040901_13_dialog_content = "哈哈哈，妳好，妳也好喔！",
  ui_story_5004_50040901_14_dialog_content = "弗勞爾，能教教我這道題嗎？",
  ui_story_5004_50040901_15_dialog_content = "當然了，有什麼不會的地方儘管問我吧~",
  ui_story_5004_50040901_16_dialog_content = "妳這傢伙，為什麼總是整天纏著弗勞爾。",
  ui_story_5004_50040901_17_dialog_content = "妳是不是對弗勞爾有非分之想！",
  ui_story_5004_50040901_18_dialog_content = "那又怎麼了！<size=45>弗勞爾不是妳一個人的吧！</size>",
  ui_story_5004_50040901_19_dialog_content = "喂！我說你們這群女孩子不要整天圍著弗勞爾。",
  ui_story_5004_50040901_20_dialog_content = "他對你們這些女生根本就沒興趣！對不對啊？",
  ui_story_5004_50040901_21_dialog_content = "什麼？！弗勞爾，你到底喜歡女孩子還是男孩子，到底喜歡誰？？",
  ui_story_5004_50040901_22_dialog_content = "大家我都喜歡。",
  ui_story_5004_50040901_23_dialog_content = "他很有機械天賦，而且工作認真，待人熱情……",
  ui_story_5004_50040901_24_dialog_content = "是非常優秀的啟光人。",
  ui_story_5004_50040901_25_dialog_content = "但他的特殊體質很難與他人合作……",
  ui_story_5004_50040901_26_dialog_content = "不管是男性、女性，甚至連動物都會受到他的影響。",
  ui_story_5004_50040901_27_dialog_content = "更何況因為<color=#FFB400>「那件事」</color>，導致了很多人受傷。",
  ui_story_5004_50040901_28_dialog_content = "嗯，就派他去新建的<color=#FFB400>38號地下城</color>吧，至少那邊的光靈數量比較少……",
  ui_story_5004_50040901_29_dialog_content = "應該比較不會那麼容易引起騷亂。",
  ui_story_5004_50040901_30_dialog_content = "弗勞爾，恭喜你。我們決定派遣你以指導專家的身分前往38號地下城支援建設。",
  ui_story_5004_50040901_31_dialog_content = "這是千載難逢的機會，也是啟光對你的信任。",
  ui_story_5004_50040901_32_dialog_content = "在那邊你有足夠的空間施放能力，我們相信你一定能將功贖過，大有作為！",
  ui_story_5004_50040901_33_dialog_content = "（那段時間還真是快樂……簡單，純粹又安靜。）",
  ui_story_5004_50040901_34_dialog_content = "我老婆下週就要來38號地下城了！我們都幾年沒見了！",
  ui_story_5004_50040901_35_dialog_content = "就因為那傢伙一直在這裡，我們都沒法夫妻團聚，甚至女兒都沒法過來！",
  ui_story_5004_50040901_36_dialog_content = "我們家養的寵物每天都往他那邊鑽！",
  ui_story_5004_50040901_37_dialog_content = "大家都得遠遠躲著他，才能免受影響！",
  ui_story_5004_50040901_38_dialog_content = "大家冷靜點，弗勞爾沒有你們想的那麼恐怖。",
  ui_story_5004_50040901_39_dialog_content = "少騙人了，他之前在學校裡的<color=#FFB400>「那件事」</color>，啟光可是人人都知道！",
  ui_story_5004_50040901_40_dialog_content = "就是因為他，才讓那麼多人受傷！你們為什麼還要包庇他！",
  ui_story_5004_50040901_42_dialog_content = "弗勞爾，感謝你一直以來對38號地下城的貢獻。",
  ui_story_5004_50040901_43_dialog_content = "但你該返回迦南城了，這裡的人……",
  ui_story_5004_50040901_44_dialog_content = "別說了，我清楚。",
  ui_story_5004_50040901_45_dialog_content = "但我不想。",
  ui_story_5004_50040901_46_dialog_content = "我不想離開38號地下城，我在這裡……有很多安靜又快樂的回憶。",
  ui_story_5004_50040901_47_dialog_content = "在這裡我能不被人群包圍，我能安安心心做自己喜歡的研究。",
  ui_story_5004_50040901_48_dialog_content = "你們當初也對我說，我在這裡會大有作為……",
  ui_story_5004_50040901_49_dialog_content = "……",
  ui_story_5004_50040901_50_dialog_content = "抱歉，現在情況不同了，如果你不想回去，我們只能強行遣送你。",
  ui_story_5004_50040901_51_dialog_content = "回去的話，我還能做什麼？",
  ui_story_5004_50040901_52_dialog_content = "把我隔離起來嗎？還是送到研究部門？",
  ui_story_5004_50040901_53_dialog_content = "抱歉……",
  ui_story_5004_50040901_54_dialog_content = "我們真的……盡力了。",
  ui_story_5004_50040901_55_dialog_content = "不過現在……還有機會！",
  ui_story_5004_50040901_56_dialog_content = "弗勞爾，歡迎你來白金夏潮飯店，你已經讀過信裡的內容了吧？",
  ui_story_5004_50040901_57_dialog_content = "是的，只要協助舉辦潮汐祭順利舉辦……就真的能解決我的「特殊體質」嗎？",
  ui_story_5004_50040901_58_dialog_content = "放心吧，這是我在挖掘遺跡時得到的情報。如果「那個傳說」是真的，就一定可以！",
  ui_story_5004_50040901_59_dialog_content = "嗯……這位年輕人就是弗勞爾吧？那大廳經理和籌備潮汐祭的工作就拜託你了。",
  ui_story_5004_50040901_59X1_dialog_content = "明白了，我馬上就著手準備。",
  ui_story_5004_50040901_59X2_dialog_content = "看起來很順利。對了，你剛才說的「那個傳說」是什麼？",
  ui_story_5004_50040901_59X3_dialog_content = "……隨便編的，反正人給你弄來就行了吧？",
  ui_story_5004_50040901_59X4_dialog_content = "呵呵……可以，可以。只要能把名單上的人弄來，用什麼手段都可以……",
  ui_story_5004_50040901_59X5_dialog_content = "潮汐祭……我一定會把握這次機會。",
  ui_story_5004_50040901_60_dialog_content = "準備好了……",
  ui_story_5004_50040901_61_dialog_content = "弗勞爾，加油！！",
  ui_story_5004_50040901_62_dialog_content = "弗勞爾！",
  ui_story_5004_50040901_63_dialog_content = "<size=45>弗勞爾先生！</size>",
  ui_story_5004_50040901_64_dialog_content = "大家早。",
  ui_story_5004_50040901_65_dialog_content = "弗勞爾先生身上的味道好迷人~！",
  ui_story_5004_50040901_66_dialog_content = "您剛剛是在洗澡嗎，我聽到水流的聲音！",
  ui_story_5004_50040901_67_dialog_content = "啊，這、這個。能麻煩大家稍微讓一下嗎？",
  ui_story_5004_50040901_68_dialog_content = "能讓我進您的房間裡看看嗎！",
  ui_story_5004_50040901_69_dialog_content = "把房間裡的零件弄亂的話我會很困擾的……",
  ui_story_5004_50040901_70_dialog_content = "小勞勞~我聽瑜伽大師說只要報名課程就能和小勞勞一起做瑜伽，是真的嗎~",
  ui_story_5004_50040901_71_dialog_content = "欸？有這種事？聽起來有點像騙局……",
  ui_story_5004_50040901_72_dialog_content = "大家、大家冷靜點，謝謝大家。我還有約，能麻煩大家稍微讓一下嗎？",
  ui_story_5004_50040901_73_dialog_content = "<anim type=Shake><size=45>欸——！！！</size></anim>",
  ui_story_5004_50040901_74_dialog_content = "是誰，到底是哪個偷跑的傢伙！",
  ui_story_5004_50040901_75_dialog_content = "弗勞爾先生，和我約會不是更好嗎？",
  ui_story_5004_50040901_76_dialog_content = "（啊啊，這下恐怕要讓PlayerName多等一會了。）",
  ui_story_5004_50041001_1_dialog_content = "原來如此，我明白了！",
  ui_story_5004_50041001_2_dialog_content = "多謝你的耐心講解，還很大方地原諒了我的遲到，真的非常感謝！",
  ui_story_5004_50041001_3_dialog_content = "倒是不用謝，我也沒等太久，不過弗勞爾你真的要製造自己的機器人？",
  ui_story_5004_50041001_4_dialog_content = "當然，這是我的夙願。",
  ui_story_5004_50041001_5_dialog_content = "<color=#e8d9bb>咚咚咚</color>",
  ui_story_5004_50041001_6_dialog_content = "PlayerName~我能進來嗎？",
  ui_story_5004_50041001_7_dialog_content = "請進。",
  ui_story_5004_50041001_8_dialog_content = "怎麼弗勞爾也在這裡呀。",
  ui_story_5004_50041001_9_dialog_content = "你可是潮汐祭籌劃組的組長，不能偷懶喔。",
  ui_story_5004_50041001_10_dialog_content = "不會的。我只是來請教PlayerName一些設計上的問題。",
  ui_story_5004_50041001_11_dialog_content = "那麼我馬上回去驗證一下，再見。",
  ui_story_5004_50041001_12_dialog_content = "PlayerName，考慮得如何了，決定要參加潮汐祭嗎？這次的獎品可是……",
  ui_story_5004_50041001_13_dialog_content = "我決定要參加。",
  ui_story_5004_50041001_14_dialog_content = "喔？",
  ui_story_5004_50041001_15_dialog_content = "有什麼問題嗎？我已經和同伴們商量過了。",
  ui_story_5004_50041001_16_dialog_content = "沒想到您會這麼爽快！",
  ui_story_5004_50041001_17_dialog_content = "參加個普通的節日祭典活動而已嘛，有什麼需要瞻前顧後的嗎？",
  ui_story_5004_50041001_18_dialog_content = "嗯哼哼，PlayerName就不怕會有什麼陰謀嗎？",
  ui_story_5004_50041001_19_dialog_content = "有陰謀？！那我還是不參加了！",
  ui_story_5004_50041001_20_dialog_content = "哈哈哈~您可真是可愛，就算我是真理結社的人，我也不會把陰謀直接說出來嘛。",
  ui_story_5004_50041001_21_dialog_content = "我是開玩笑的喔，是對您如此英明的決斷所表達的小小敬意啦。",
  ui_story_5004_50041001_22_dialog_content = "（真理結社怎麼都是這種奇怪的傢伙！）",
  ui_story_5004_50041001_23_dialog_content = "既然您決定參加的話，還請在這份文件上簽一下名字吧。",
  ui_story_5004_50041001_24_dialog_content = "來，請用這支筆。",
  ui_story_5004_50041001_25_dialog_content = "唔……！這支筆看起來好精緻。",
  ui_story_5004_50041001_26_dialog_content = "而且涼涼的像冰塊一樣，有點黏手……",
  ui_story_5004_50041001_27_dialog_content = "這支筆很貴喔，是用極為稀有的晶石製作的。",
  ui_story_5004_50041001_28_dialog_content = "雖然只是小小一支筆，價值卻足以買下半間飯店呢。",
  ui_story_5004_50041001_29_dialog_content = "既然PlayerName這麼感興趣，那乾脆就送給您當個小禮物吧。",
  ui_story_5004_50041001_30_dialog_content = "咦！我不能收這麼貴重的禮物。",
  ui_story_5004_50041001_31_dialog_content = "沒關係，反正是從遺跡裡挖出來的嘛。",
  ui_story_5004_50041001_32_dialog_content = "不愧是喜歡到處挖掘遺跡的真理結社！",
  ui_story_5004_50041001_33_dialog_content = "您過獎了~對了，我聽說您巨像上的操作裝置……外形似乎像是一架鋼琴？",
  ui_story_5004_50041001_34_dialog_content = "身為音樂家的我，真是非常好奇呢。如果能有幸親眼一見就好了~",
  ui_story_5004_50041001_35_dialog_content = "參觀的話沒問題，已經簽好了，筆和文件都請拿好！",
  ui_story_5004_50041001_36_dialog_content = "這樣啊……已經確認了，那麼從現在起您就是正式的參賽者喔。",
  ui_story_5004_50041001_37_dialog_content = "還請再稍作休息，下午就是第一場正式比賽。",
  ui_story_5004_50041001_38_dialog_content = "期待您的活躍表現。",
  ui_story_5004_50041001_39_dialog_content = "哈……這實在是……太順利了吧。",
  ui_story_5004_50041001_40_dialog_content = "連我都要感覺到一絲負罪感了……",
  ui_story_5004_50041001_X40_dialog_content = "才怪。",
  ui_story_5004_50041001_X40X1_dialog_content = "這樣就所有人都到齊了……包括空裔。",
  ui_story_5004_50041001_X40X2_dialog_content = "沒想到他這麼輕易就用「那傢伙」的筆簽下名字……",
  ui_story_5004_50041001_X40X3_dialog_content = "不知道「那傢伙」在打什麼算盤……算了，反正憑那麼幾隻暗鬼成不了什麼氣候。",
  ui_story_5004_50041001_41_dialog_content = "居然這麼簡單，就能拿到<color=#FFB400>「樂章」</color>的上半部分……",
  ui_story_5004_50041001_42_dialog_content = "PlayerName……真是有趣的傢伙。",
  ui_story_5004_50041101_1_dialog_content = "<color=#e8d9bb>與此同時</color>",
  ui_story_5004_50041101_2_dialog_content = "很好……鑰匙已經在妳掌握之中……",
  ui_story_5004_50041101_3_dialog_content = "利用他的力量……妳就能進一步走近神鳴。",
  ui_story_5004_50041101_4_dialog_content = "我為妳指引前路……你為我摘得「果實」……",
  ui_story_5004_50041101_5_dialog_content = "不用再迎合庸俗之人……你將走向真正音樂的極致……",
  ui_story_5004_50041101_6_dialog_content = "明白了……這就是我……這就是我一直所期望的……！",
  ui_story_5004_50041101_7_dialog_content = "嘖，妳自言自語的樣子不管看幾次都很奇怪。妳腦袋裡那個聲音又和你說什麼？",
  ui_story_5004_50041101_8_dialog_content = "我已經按照約定，在妳讓名單上的人都到齊參賽後，把樂章上半部交給妳了。",
  ui_story_5004_50041101_9_dialog_content = "那個聲音是在絮絮叨叨要妳快點找到樂章的下半部分嗎？",
  ui_story_5004_50041101_10_dialog_content = "已經派更多暗鬼去協助挖掘了，但就算拿到手了也沒用。",
  ui_story_5004_50041101_11_dialog_content = "妳還是需要空裔的力量才能喚醒它。",
  ui_story_5004_50041101_12_dialog_content = "……這和你無關。",
  ui_story_5004_50041101_13_dialog_content = "希望你記清楚了，我的目標是拿到完整的「神鳴樂章」，而非與你們這些「暗鬼」站在一起。",
  ui_story_5004_50041101_14_dialog_content = "是因為你們提供了樂章的上半部分，並許諾下半部分也會交給我。",
  ui_story_5004_50041101_15_dialog_content = "所以才達成了臨時的「互助」，而非長久的「同謀」，你能理解嗎？",
  ui_story_5004_50041101_15X_dialog_content = "順帶一提，你那些派出的暗鬼，都被PlayerName他們幹掉了。",
  ui_story_5004_50041101_16_dialog_content = "沒用的小、倉、鼠。",
  ui_story_5004_50041101_17_dialog_content = "妳這個可惡又骯髒的光靈——！！",
  ui_story_5004_50041101_18_dialog_content = "冷靜點。",
  ui_story_5004_50041101_19_dialog_content = "你也不想自己的小倉鼠窩被人發現然後掀翻吧。",
  ui_story_5004_50041101_20_dialog_content = "畢竟你不是也有一些可笑的計畫嗎？像是利用潮汐祭吸引遊客，然後發售泳裝影集籌措軍資？",
  ui_story_5004_50041101_21_dialog_content = "還有些像是開設瑜伽課之類的各種可笑手段，用來榨乾遊客的錢包……",
  ui_story_5004_50041101_22_dialog_content = "然而，大多數錢還不是要上貢給真正的那位老闆。",
  ui_story_5004_50041101_23_dialog_content = "你這個「代理」總經理，也不過是個工具人嘛~",
  ui_story_5004_50041101_24_dialog_content = "給光靈打工的暗鬼，傳出去會被你的同族狠狠恥笑吧。",
  ui_story_5004_50041101_25_dialog_content = "妳……妳知道什麼！我們……",
  ui_story_5004_50041101_26_dialog_content = "彭格格大人！",
  ui_story_5004_50041101_27_dialog_content = "可惡……我饒不了你這傢伙！",
  ui_story_5004_50041101_28_dialog_content = "塔德天大師，送客了。",
  ui_story_5004_50041101_29_dialog_content = "波娜瑟小姐，您請回吧。",
  ui_story_5004_50041101_30_dialog_content = "送您回去的路上，請允許我向您介紹一下我最新設計的瑜伽課程。",
  ui_story_5004_50041101_31_dialog_content = "「完美是一種態度、優雅是一種生活、寬容是一種心態，美麗人生從瑜伽開始。」",
  ui_story_5004_50041101_32_dialog_content = "「瑜伽，是幫您完成平凡到非凡的美麗蛻變。」",
  ui_story_5004_50041101_33_dialog_content = "「瑜伽，是超凡脫俗的心靈藝術。」",
  ui_story_5004_50041101_34_dialog_content = "……",
  ui_story_5004_50041201_1_dialog_content = "到了，這裡就是比賽場地嗎？",
  ui_story_5004_50041201_2_dialog_content = "……是裁判台跟球網，和臨空者資料庫上的很像。",
  ui_story_5004_50041201_2X1_dialog_content = "嗯？好像還有些特別的東西？",
  ui_story_5004_50041201_2X2_dialog_content = "別在意~這只是個普通的「抑制裝置」。",
  ui_story_5004_50041201_2X3_dialog_content = "是為了防止你們一會打球太激烈，損傷到旁邊的設施。",
  ui_story_5004_50041201_2X4_dialog_content = "（嗄？不是普通的排球比賽嗎……）",
  ui_story_5004_50041201_2X5_dialog_content = "呼……好了。",
  ui_story_5004_50041201_3_dialog_content = "嗯，看來裁判也走回去就位了。",
  ui_story_5004_50041201_4_dialog_content = "歡迎大家來到本次潮汐祭的第一場比賽，象徵力量與無畏的——排球比賽。",
  ui_story_5004_50041201_5_dialog_content = "站在我右手邊的是PlayerName率領的隊伍。",
  ui_story_5004_50041201_6_dialog_content = "喂，弗勞爾你是PlayerName那邊的，快點站過去。",
  ui_story_5004_50041201_7_dialog_content = "嗯？弗勞爾也來了嗎？",
  ui_story_5004_50041201_8_dialog_content = "因為很久沒和黑潮一起打球了，加上波娜瑟也一直鼓勵我參加看看。",
  ui_story_5004_50041201_9_dialog_content = "哎，這傢伙來了的話，場面可是很容易失控的啊……",
  ui_story_5004_50041201_10_dialog_content = "弗勞爾——",
  ui_story_5004_50041201_11_dialog_content = "小勞勞！！",
  ui_story_5004_50041201_12_dialog_content = "我也贊同……",
  ui_story_5004_50041201_13_dialog_content = "哎，對這種體育活動我還是沒什麼信心……",
  ui_story_5004_50041201_14_dialog_content = "放心吧PlayerName，排球我很擅長的！",
  ui_story_5004_50041201_15_dialog_content = "薇絲她在學校時體育成績非常優異。",
  ui_story_5004_50041201_16_dialog_content = "畢竟<color=#FFB400>「鋼骨鐵腕少女」</color>不是浪得虛名的。",
  ui_story_5004_50041201_17_dialog_content = "這點PlayerName你大可以放心。",
  ui_story_5004_50041201_18_dialog_content = "（白夜城學校裡幫人取外號的品味真奇怪？？）",
  ui_story_5004_50041201_19_dialog_content = "是、是嗎，那就好。看妳的了！薇絲！",
  ui_story_5004_50041201_20_dialog_content = "嘖，沒想到和你們分到了一隊。",
  ui_story_5004_50041201_21_dialog_content = "妳是昨天的那個……妳也來參加潮汐祭的比賽了？",
  ui_story_5004_50041201_22_dialog_content = "是昨天那個弄壞小拜里厄沙堡的人！",
  ui_story_5004_50041201_23_dialog_content = "怎麼了，我不能參加嗎？那個波娜瑟也邀請了我啊。",
  ui_story_5004_50041201_24_dialog_content = "另外我叫斯莫奇，沙雕的事不是已經道過歉了嗎。",
  ui_story_5004_50041201_25_dialog_content = "一碼歸一碼，總之今天分到一隊就別內訌。你們能努力點直接贏下就更好了。",
  ui_story_5004_50041201_26_dialog_content = "這個凶凶的女孩子就是你昨天提到的人嗎？看起來不太好相處……",
  ui_story_5004_50041201_27_dialog_content = "是……不過當時遇到的<color=#FFB400>另外一個</color>可是有過之而無不及。",
  ui_story_5004_50041201_28_dialog_content = "左手邊的則是吉納維芙以及她的親衛隊——",
  ui_story_5004_50041201_29_dialog_content = "哼！",
  ui_story_5004_50041201_30_dialog_content = "就是這傢伙！",
  ui_story_5004_50041201_31_dialog_content = "<anim type=Shake><size=45>喝——！喝——！喝——！</size></anim>",
  ui_story_5004_50041201_32_dialog_content = "呵呵呵……看到了嗎，斯莫奇！",
  ui_story_5004_50041201_33_dialog_content = "真正的貴族無論走到哪裡，都會自然而然地得到庶民的擁戴。",
  ui_story_5004_50041201_34_dialog_content = "這是他們對我高貴品格的認同，對我強大力量的臣服。",
  ui_story_5004_50041201_35_dialog_content = "是像妳這種傢伙永遠無法理解的！斯莫奇！！",
  ui_story_5004_50041201_36_dialog_content = "……喔是喔，知道了知道了。",
  ui_story_5004_50041201_37_dialog_content = "到底誰會想理解這個啊，妳還是喜歡做那些麻煩又無聊的事。",
  ui_story_5004_50041201_38_dialog_content = "喂，你們幾個多加把勁，快開始吧！",
  ui_story_5004_50041201_39_dialog_content = "死到臨頭還敢這麼囂張……那妳就試試這個！！",
  ui_story_5004_50041201_40_dialog_content = "等等，還沒開始比賽吧——！！",
  ui_story_5004_50041201_41_dialog_content = "嘖。",
  ui_story_5004_50041201_42_dialog_content = "好靈巧的閃避！",
  ui_story_5004_50041201_43_dialog_content = "！！！",
  ui_story_5004_50041201_44_dialog_content = "（被斯莫奇躲開的球筆直朝我射來。）",
  ui_story_5004_50041201_45_dialog_content = "（雖然是在參加排球比賽，我卻前所未有地希望自己擁有戰鬥的力量。）",
  ui_story_5004_50041201_46_dialog_content = "（殺人排球迎面而來的恐懼，遠比跟暗鬼作戰要恐怖。）",
  ui_story_5004_50041201_47_dialog_content = "（大腦如此這般跑馬燈似地胡思亂想著的同時，我閉上了眼睛。）",
  ui_story_5004_50041201_48_dialog_content = "（祈禱著被打飛進到海裡之後，薇絲能盡快把我撈上來。）",
  ui_story_5004_50041201_49_dialog_content = "海水……會是什麼味道？",
  ui_story_5004_50041201_50_dialog_content = "PlayerName！！",
  ui_story_5004_50041201_51_dialog_content = "薇絲！妳沒事吧。",
  ui_story_5004_50041201_52_dialog_content = "沒事……還好，差點被撞到場外。",
  ui_story_5004_50041201_53_dialog_content = "喂！明明還沒開始比賽吧。吉納維芙這是犯規！",
  ui_story_5004_50041201_54_dialog_content = "PlayerName，看來你沒仔細閱讀我給你的秩序冊呢。",
  ui_story_5004_50041201_55_dialog_content = "那種又厚又沉還全是贊助商廣告的東西誰看得下去！",
  ui_story_5004_50041201_56_dialog_content = "那就怪不得我了喔！",
  ui_story_5004_50041201_57_dialog_content = "來吧！盡情向神明展示各位的英姿，戰鬥到最後一刻吧——！",
  ui_story_5004_50041201_58_dialog_content = "（這時我才意識到，這不非是我認知中的排球比賽。）",
  ui_story_5004_50041201_59_dialog_content = "（而是在沙灘上以球為武器的血腥戰鬥……）",
  ui_story_5004_50041202_1_dialog_content = "呼……呼……我……我還可以……",
  ui_story_5004_50041202_2_dialog_content = "怎麼了，你們就這點本事嗎？",
  ui_story_5004_50041202_3_dialog_content = "抱歉，PlayerName，早知道就帶月之繭來了……",
  ui_story_5004_50041202_4_dialog_content = "沒事的，就算帶了月之繭也只會把球戳破……還有黑潮他們呢，妳們先保留體力。",
  ui_story_5004_50041202_5_dialog_content = "喂——你們再認真點——！",
  ui_story_5004_50041202_6_dialog_content = "那妳也別只動張嘴啊！",
  ui_story_5004_50041202_7_dialog_content = "喂！看球啊你，打過來了！",
  ui_story_5004_50041202_8_dialog_content = "謝啦！黑潮！",
  ui_story_5004_50041202_9_dialog_content = "重組陣型，再餵吉納維芙大人一球！",
  ui_story_5004_50041202_10_dialog_content = "<size=45>是——！</size>",
  ui_story_5004_50041202_11_dialog_content = "可惡……我好像直接被吉納維芙無視了，難道是看我毫無威脅嗎？",
  ui_story_5004_50041202_12_dialog_content = "局勢如此危急的話……就只能拿出<color=#FFB400>那個</color>了！",
  ui_story_5004_50041202_13_dialog_content = "等一下！你突然戴上什麼了？！",
  ui_story_5004_50041202_14_dialog_content = "這是<color=#FFB400>機械手臂</color>吧？！",
  ui_story_5004_50041202_15_dialog_content = "哈哈~沒有啦，這明明只是<color=#FFB400>我的手</color>而已。",
  ui_story_5004_50041202_16_dialog_content = "它叫厄運RX100型，是和小不點合作的聯名款式，由我特別將功率提高了三倍！",
  ui_story_5004_50041202_17_dialog_content = "你說了它叫厄運是吧！那不就是約娜的機械手臂的名字嗎！",
  ui_story_5004_50041202_18_dialog_content = "而且它看起來就是拳頭位置多了一塊塗成純紅色的凸起，憑什麼就提高了三倍出力啊！",
  ui_story_5004_50041202_19_dialog_content = "我的右手正熊熊燃燒，它在高呼著要為我奪得勝利——！",
  ui_story_5004_50041202_20_dialog_content = "別唸那種奇怪的台詞了，你這玩意犯規吧。",
  ui_story_5004_50041202_21_dialog_content = "這東西的準頭和力道不會輸給任何一個人喔。",
  ui_story_5004_50041202_22_dialog_content = "當然了，這可是機械手臂。",
  ui_story_5004_50041202_23_dialog_content = "它很厲害的，不用球也能把人轟出十幾公尺。",
  ui_story_5004_50041202_24_dialog_content = "哎，我好擔心它的力道太強……",
  ui_story_5004_50041202_25_dialog_content = "就說了是機械手臂啊，馬上給我摘下來，會被判犯規的！",
  ui_story_5004_50041202_26_dialog_content = "啊，還是不行嗎……黑潮真是不懂啊。",
  ui_story_5004_50041202_27_dialog_content = "小心！",
  ui_story_5004_50041202_28_dialog_content = "有破綻——！！",
  ui_story_5004_50041202_29_dialog_content = "<color=#e8d9bb>砰！砰！</color>",
  ui_story_5004_50041202_30_dialog_content = "嗚……呃……",
  ui_story_5004_50041202_31_dialog_content = "啊……已經，不行了嗎……多麼美麗的天空啊……",
  ui_story_5004_50041202_32_dialog_content = "怎麼直接把黑潮掀翻插進沙子裡了，這真的是在打排球嗎？！",
  ui_story_5004_50041202_33_dialog_content = "第一局結束！進入中場休息時間——",
  ui_story_5004_50041202_34_dialog_content = "比賽休息期間，請您欣賞我們的贊助商廣告——",
  ui_story_5004_50041202_X33_dialog_content = "3",
  ui_story_5004_50041202_X34_dialog_content = "2",
  ui_story_5004_50041202_X35_dialog_content = "1",
  ui_story_5004_50041202_35_dialog_content = "為您介紹的這款產品，就是本季度浮空商會最為熱門的禮包系列。",
  ui_story_5004_50041202_36_dialog_content = "現在立即點擊圖示的話，就可以獨享波娜瑟特別折扣，再附送十枚特召星標。",
  ui_story_5004_50041202_37_dialog_content = "另外還贈送超級適合在海灘上使用的充氣噴水坦克！",
  ui_story_5004_50041202_38_dialog_content = "禮包限量五千份，啊！只剩一千零一份了！",
  ui_story_5004_50041202_39_dialog_content = "現在還不搶的話，馬上就要沒有了——！",
  ui_story_5004_50041202_40_dialog_content = "短短八句話的時間！禮包居然全部賣光啦！！",
  ui_story_5004_50041202_41_dialog_content = "那麼還請您繼續關注波娜瑟的精選購物頻道，我們下次再見~",
  ui_story_5004_50041202_42_dialog_content = "現在不是插播廣告的時候啊！！！",
  ui_story_5004_50041202_43_dialog_content = "這樣不是只剩下我和瘋狂偷懶的斯莫奇能動了嗎？！",
  ui_story_5004_50041202_44_dialog_content = "喂！！妳不要一直事不關己的樣子，也想想辦法啊！",
  ui_story_5004_50041202_45_dialog_content = "嗄？真麻煩，本來還指望你們能搞定的。",
  ui_story_5004_50041202_46_dialog_content = "結果都是一群沒用的傢伙啊——",
  ui_story_5004_50041202_47_dialog_content = "但是大家剛剛也幫妳擋了很多球啊！",
  ui_story_5004_50041202_48_dialog_content = "如果不是他們捨身相助，妳也早就下場了吧！",
  ui_story_5004_50041202_49_dialog_content = "如果這樣就輸了比賽，大家的犧牲不是白費了嗎！！",
  ui_story_5004_50041202_50_dialog_content = "啊，好啦好啦。嘴上說得好聽，你不是也旁觀了一整場嗎？",
  ui_story_5004_50041202_51_dialog_content = "不過我可不想欠你們人情。",
  ui_story_5004_50041202_52_dialog_content = "你就在旁邊好好解說我的英姿，看我如何奪得勝利吧！",
  ui_story_5004_50041202_53_dialog_content = "嗄？解說……？好吧！只要妳肯碰球我什麼都答應！！",
  ui_story_5004_50041202_54_dialog_content = "好！",
  ui_story_5004_50041202_55_dialog_content = "喂——",
  ui_story_5004_50041202_56_dialog_content = "吉納維芙——",
  ui_story_5004_50041202_57_dialog_content = "嗯？妳已經害怕了嗎？想求饒了嗎？",
  ui_story_5004_50041202_58_dialog_content = "我問妳啊，妳就那麼在意被別人超過嗎！",
  ui_story_5004_50041202_59_dialog_content = "沒錯……我就是這麼在意，我的家訓和自尊不允許我輸給任何人，尤其是妳！",
  ui_story_5004_50041202_60_dialog_content = "妳這傢伙奪走了我的榮耀，這些年我一直追著妳的腳步，一直在尋找妳。",
  ui_story_5004_50041202_61_dialog_content = "就是為了有朝一日徹底打敗妳，親眼看到妳失敗痛苦和懊悔的表情！",
  ui_story_5004_50041202_62_dialog_content = "……那可真是很遺憾啊。",
  ui_story_5004_50041202_63_dialog_content = "什麼！？",
  ui_story_5004_50041202_64_dialog_content = "因為我啊……也最討厭失敗了！！",
  ui_story_5004_50041202_65_dialog_content = "那麼……就用這一球，來讓我看看！",
  ui_story_5004_50041202_66_dialog_content = "妳和妳的決心，是否能超越我吧！！",
  ui_story_5004_50041202_67_dialog_content = "<anim type=Shake><size=45>「爆☆炎SUPER扣☆殺」！！</size></anim>",
  ui_story_5004_50041202_68_dialog_content = "！！！",
  ui_story_5004_50041202_69_dialog_content = "這！彷彿以地獄烈焰包裹著球，狠狠撕裂周遭的大氣，直撲吉納維芙而去了！",
  ui_story_5004_50041202_70_dialog_content = "（居然真的要當解說……太羞恥了吧！）",
  ui_story_5004_50041202_71_dialog_content = "吉納維芙小姐！！",
  ui_story_5004_50041202_72_dialog_content = "親衛隊圍了上來，把吉納維芙保護在中間，這真的會有效果嗎！？",
  ui_story_5004_50041202_73_dialog_content = "喔，天啊，火球在人群中炸開了，簡直是燃燒的隕石直擊地面！！",
  ui_story_5004_50041202_74_dialog_content = "可憐的吉納維芙和她的親衛隊，一球就被掃出了賽場，連賽場中間都被炸出了深深的沙坑！",
  ui_story_5004_50041202_75_dialog_content = "獲勝者——PlayerName隊！",
  ui_story_5004_50041202_76_dialog_content = "射出這一球的斯莫奇伸出食指指向天空，做出了她的招牌勝利動作！這一球實在太棒了！",
  ui_story_5004_50041202_77_dialog_content = "哼，解說得不錯啊，算是展現出了我的五分風采。",
  ui_story_5004_50041202_78_dialog_content = "謝謝誇獎……不對，再怎麼說也應該找個場外的人當解說吧！！",
  ui_story_5004_50041202_79_dialog_content = "不過還是……好強！一瞬間就全部解決掉了……",
  ui_story_5004_50041202_80_dialog_content = "（要贏過這樣的怪物嗎……突然有點心疼吉納維芙……）",
  ui_story_5004_50041301_1_dialog_content = "哈——好累！",
  ui_story_5004_50041301_2_dialog_content = "雖然沒發揮什麼作用，跑來跑去躲著球還是很累……",
  ui_story_5004_50041301_3_dialog_content = "沒想到第一天的比賽就如此激烈。",
  ui_story_5004_50041301_4_dialog_content = "吉納維芙雖然很厲害，但是斯莫奇更是強得離譜……",
  ui_story_5004_50041301_5_dialog_content = "這兩個人是有什麼深仇大恨嗎？",
  ui_story_5004_50041301_6_dialog_content = "拜里厄和拉斐爾之後好像又去釣魚了……看來她們玩得應該挺開心。",
  ui_story_5004_50041301_7_dialog_content = "雖然拜里厄晚上看起來有點疲勞，但是有拉斐爾在的話應該沒太大問題。",
  ui_story_5004_50041301_8_dialog_content = "對了！得去感謝一下幫我擋球的薇絲……",
  ui_story_5004_50041301_9_dialog_content = "如果沒有她的話，我現在可能還在搶救中……",
  ui_story_5004_50041301_10_dialog_content = "<color=#e8d9bb>咚咚咚</color>",
  ui_story_5004_50041301_11_dialog_content = "PlayerName，你在休息嗎？",
  ui_story_5004_50041301_12_dialog_content = "馬上來。",
  ui_story_5004_50041301_13_dialog_content = "卡蓮？怎麼了？",
  ui_story_5004_50041301_14_dialog_content = "嗯……我來看看PlayerName休息了沒有。",
  ui_story_5004_50041301_15_dialog_content = "難得來了海邊……晚上也不想悶在房間裡。",
  ui_story_5004_50041301_16_dialog_content = "要不要去海邊散散步？",
  ui_story_5004_50041301_17_dialog_content = "當然，我很樂意！",
  ui_story_5004_50041301_19_dialog_content = "嗯，那就一起去吧。",
  ui_story_5004_50041301_20_dialog_content = "嗯……",
  ui_story_5004_50041301_21_dialog_content = "總覺得有點尷尬。",
  ui_story_5004_50041301_22_dialog_content = "PlayerName。",
  ui_story_5004_50041301_23_dialog_content = "啊，在！",
  ui_story_5004_50041301_24_dialog_content = "之前吞噬者號和舒默的事……我一直想正式地向你表達謝意。",
  ui_story_5004_50041301_25_dialog_content = "沒什麼，都是小事啦。",
  ui_story_5004_50041301_26_dialog_content = "我也承蒙卡蓮和薇絲許多幫助。",
  ui_story_5004_50041301_27_dialog_content = "嗯，那些事情在如此美麗的海灘邊回想起來……",
  ui_story_5004_50041301_28_dialog_content = "簡直就像是在做夢一樣毫無真實感，是吧。",
  ui_story_5004_50041301_29_dialog_content = "甚至讓人分不清此時此刻是否也在夢中……",
  ui_story_5004_50041301_30_dialog_content = "初次遇見你時，我還非常懷疑，不相信你居然能一個人獨自生活十多年……",
  ui_story_5004_50041301_31_dialog_content = "那個時候我還是第一次見到空裔……能觀測到光之軌跡的人，太不可思議了。",
  ui_story_5004_50041301_32_dialog_content = "你一次次用臨危不亂的出色表現證明了自己，確實有著非凡的指揮才能。",
  ui_story_5004_50041301_33_dialog_content = "雖然沒有對抗暗鬼的能力，但你每次面對暗鬼都毫不退縮。",
  ui_story_5004_50041301_34_dialog_content = "……",
  ui_story_5004_50041301_35_dialog_content = "甚至為了大家，敢於讓自己置身於險境。",
  ui_story_5004_50041301_36_dialog_content = "奉獻自己和捨己救人不是尋常的品格，更別提可能會付出自己的生命。",
  ui_story_5004_50041301_37_dialog_content = "你所展現出的勇氣，遠比一些在災難前只顧自己苟活的大貴族更值得尊敬。",
  ui_story_5004_50041301_38_dialog_content = "……",
  ui_story_5004_50041301_39_dialog_content = "PlayerName？你在聽嗎？",
  ui_story_5004_50041301_40_dialog_content = "啊，是不是我太嘮叨了……",
  ui_story_5004_50041301_41_dialog_content = "我在聽，也在思考剛剛卡蓮說的話……能吹著海風和卡蓮聊天真好。",
  ui_story_5004_50041301_42_dialog_content = "而且這裡的一切……",
  ui_story_5004_50041301_43_dialog_content = "大海很美……星空也很美……",
  ui_story_5004_50041301_44_dialog_content = "還有……",
  ui_story_5004_50041301_45_dialog_content = "……",
  ui_story_5004_50041301_46_dialog_content = "這一切都很美。",
  ui_story_5004_50041301_47_dialog_content = "……",
  ui_story_5004_50041301_48_dialog_content = "……",
  ui_story_5004_50041301_49_dialog_content = "（好像讓氣氛更微妙了……）",
  ui_story_5004_50041301_50_dialog_content = "真的是這樣！是白夜城裡絕對看不到的美景呢。",
  ui_story_5004_50041301_51_dialog_content = "習以為常的浩瀚星空，在這樣風平浪靜的海面襯托下，有著和平時截然不同的壯美。",
  ui_story_5004_50041301_52_dialog_content = "（還好卡蓮沒注意到……）",
  ui_story_5004_50041301_53_dialog_content = "這、這裡的海這麼美，應該魚也很好吃吧！",
  ui_story_5004_50041301_54_dialog_content = "要不要抓條魚烤來嚐嚐看！",
  ui_story_5004_50041301_55_dialog_content = "好主意，不過我沒學過料理相關的課程。",
  ui_story_5004_50041301_56_dialog_content = "不過我們倒是可以把捉到的魚帶回飯店，請那個長相很奇怪的廚師長幫忙烹飪。",
  ui_story_5004_50041301_57_dialog_content = "或者帶回白夜城，我也知道幾家口味和環境都不錯的安靜小店。",
  ui_story_5004_50041301_58_dialog_content = "好！那就一言為定了。",
  ui_story_5004_50041301_59_dialog_content = "不過還是別現在抓魚了吧，已經很晚了，下水感覺有點危險……",
  ui_story_5004_50041301_60_dialog_content = "而且今天的排球比賽卡蓮也很累吧？",
  ui_story_5004_50041301_61_dialog_content = "對。那就下次再來抓魚吧。",
  ui_story_5004_50041301_62_dialog_content = "嗯……？",
  ui_story_5004_50041301_63_dialog_content = "怎麼了PlayerName？",
  ui_story_5004_50041301_64_dialog_content = "剛剛，遠處那座雕像好像閃了一下？",
  ui_story_5004_50041301_65_dialog_content = "我沒看到……也許是你太累了吧？",
  ui_story_5004_50041301_66_dialog_content = "或者是斯莫奇的「爆☆炎SUPER扣☆殺」在你的腦袋裡留下的印象太深刻了？",
  ui_story_5004_50041301_67_dialog_content = "妳居然還記得那個名字……",
  ui_story_5004_50041301_68_dialog_content = "應該不會吧……算了，可能只是我眼花了……",
  ui_story_5004_50041301_69_dialog_content = "回去吧。",
  ui_story_5004_50041301_70_dialog_content = "空裔之子……晶石之力……「那個裝置」也在運作著……",
  ui_story_5004_50041301_71_dialog_content = "一群主動獻上光能的愚蠢光靈……",
  ui_story_5004_50041301_72_dialog_content = "還有……",
  ui_story_5004_50041301_73_dialog_content = "拜里厄。",
  ui_story_5004_50041301_74_dialog_content = "這局棋……現在輪到我下了。",
  ui_story_5004_50041501_1_dialog_content = "<color=#e8d9bb>幾天前。</color>",
  ui_story_5004_50041501_2_dialog_content = "可惡……！",
  ui_story_5004_50041501_3_dialog_content = "<color=#e8d9bb>斯莫奇憤怒地撕碎手中的信封，重重丟向一邊。</color>",
  ui_story_5004_50041501_4_dialog_content = "是不是被那小子給耍了……",
  ui_story_5004_50041501_5_dialog_content = "別，別打我。妳要多少錢我都給妳！",
  ui_story_5004_50041501_6_dialog_content = "嗄？你剛剛不還趾高氣揚地要勒索小女孩嗎？",
  ui_story_5004_50041501_7_dialog_content = "怎麼了？再擺出剛剛那副噁心的醜臉跟我要錢試試啊。",
  ui_story_5004_50041501_8_dialog_content = "兩天不修理你們這群小混混，就不知道這地方是誰在罩的嗎？",
  ui_story_5004_50041501_9_dialog_content = "我定下不許騷擾女性的規矩，<size=45>你們都當放屁是吧</size>？",
  ui_story_5004_50041501_10_dialog_content = "我、我不是本地人……您大人有大量，就放了我吧，我再也不敢來惹事了！",
  ui_story_5004_50041501_11_dialog_content = "嗯？不是本地人？看在你這個藉口很有創意——",
  ui_story_5004_50041501_12_dialog_content = "說出你是從哪來的、來這裡幹嘛、老大是誰。三十秒之內全說清楚。",
  ui_story_5004_50041501_13_dialog_content = "答得我滿意了，就放你走。",
  ui_story_5004_50041501_14_dialog_content = "但如果我不滿意的話……",
  ui_story_5004_50041501_15_dialog_content = "每過三十秒我就折斷你一根手指，聽懂了嗎？",
  ui_story_5004_50041501_16_dialog_content = "第一根手指，現在開始，三十、二九……",
  ui_story_5004_50041501_17_dialog_content = "饒、饒了我吧！我就是替人跑腿辦事，送點東西而已！",
  ui_story_5004_50041501_18_dialog_content = "我真的沒有打歪主意啊！都因為那個小妞大半夜穿那麼少！！怎麼能怪我！！",
  ui_story_5004_50041501_19_dialog_content = "我就是個跑腿送貨的，沒什麼老大啊！！",
  ui_story_5004_50041501_20_dialog_content = "十，九，八……",
  ui_story_5004_50041501_21_dialog_content = "能說的都說了，你還想聽什麼啊！！",
  ui_story_5004_50041501_22_dialog_content = "啪喀、啪喀",
  ui_story_5004_50041501_23_dialog_content = "<size=45><anim type=Shake>啊！！！我的手指！！我的手指！！</anim></size>",
  ui_story_5004_50041501_24_dialog_content = "妳他媽的！！為什麼掰我兩根手指！？什麼毛病啊！！",
  ui_story_5004_50041501_25_dialog_content = "瘋子！瘋子！！妳腦子有病吧！！！",
  ui_story_5004_50041501_26_dialog_content = "一根是時間到了，另外一根是你態度不夠誠懇。",
  ui_story_5004_50041501_27_dialog_content = "我……我真的……就只是個送貨的……",
  ui_story_5004_50041501_28_dialog_content = "拿出來。",
  ui_story_5004_50041501_29_dialog_content = "不行！！！",
  ui_story_5004_50041501_30_dialog_content = "喔？第三根的時間也快到了呢，五、四……",
  ui_story_5004_50041501_31_dialog_content = "真的不行！！他們會殺了我的！！！",
  ui_story_5004_50041501_32_dialog_content = "零。",
  ui_story_5004_50041501_33_dialog_content = "<size=45><anim type=Shake>啊！！！</anim></size>嘶、呼……",
  ui_story_5004_50041501_34_dialog_content = "難道你是覺得我就不會殺你嗎？",
  ui_story_5004_50041501_35_dialog_content = "是要現在死還是晚點死，你想清楚吧。",
  ui_story_5004_50041501_36_dialog_content = "知道了！我知道了！！放開我！！",
  ui_story_5004_50041501_37_dialog_content = "給妳，都給妳！你這個瘋子！",
  ui_story_5004_50041501_38_dialog_content = "嗄？就這一封信？裡面寫什麼？",
  ui_story_5004_50041501_39_dialog_content = "我、我勸你馬上還我……這是交給大人物的，妳拿在手上我們兩個都要吃不了兜著走！！",
  ui_story_5004_50041501_40_dialog_content = "晚了。",
  ui_story_5004_50041501_41_dialog_content = "我倒要看看是什麼大人物的好東西。",
  ui_story_5004_50041501_42_dialog_content = "這啥……「天堂階梯海岸」……？",
  ui_story_5004_50041501_43_dialog_content = "這畫的是什麼藏寶圖嗎？",
  ui_story_5004_50041501_44_dialog_content = "誰叫你拆開的！！這下死定了！！",
  ui_story_5004_50041501_45_dialog_content = "<size=45>我問你話呢——</size>",
  ui_story_5004_50041501_46_dialog_content = "我、我也不知道啊，我只知道那群人非常危險！",
  ui_story_5004_50041501_47_dialog_content = "好像還在準備舉行什麼儀式之類的，要召喚什麼毀滅世界的災禍！",
  ui_story_5004_50041501_48_dialog_content = "快點把東西還給我，我不想捲進這些事！！",
  ui_story_5004_50041501_49_dialog_content = "嗄？我剛剛也沒打到你的頭吧？",
  ui_story_5004_50041501_50_dialog_content = "怎麼胡言亂語起來沒完了。",
  ui_story_5004_50041501_51_dialog_content = "你這麼說的話，我就偏偏不信邪。",
  ui_story_5004_50041501_52_dialog_content = "我非要去看看不可！",
  ui_story_5004_50041501_53_dialog_content = "<color=#e8d9bb>正如信中所寫——</color>",
  ui_story_5004_50041501_54_dialog_content = "<color=#e8d9bb>我所追求的，是三座嘆息之高牆</color>",
  ui_story_5004_50041501_55_dialog_content = "<color=#e8d9bb>我所尋覓的，是於灰燼中復甦</color>",
  ui_story_5004_50041501_56_dialog_content = "<color=#e8d9bb>在晨曦中降下血雨</color>",
  ui_story_5004_50041501_57_dialog_content = "<color=#e8d9bb>為夕陽染上哭嚎</color>",
  ui_story_5004_50041501_58_dialog_content = "<color=#e8d9bb>直到審判與終焉的盡頭</color>",
  ui_story_5004_50041501_59_dialog_content = "<color=#e8d9bb>此刻，君王應當醒悟</color>",
  ui_story_5004_50041501_60_dialog_content = "什麼狗屁玩意……跟謎語似的……",
  ui_story_5004_50041501_61_dialog_content = "難道真的白來一趟……",
  ui_story_5004_50041501_62_dialog_content = "<color=#e8d9bb>咚咚咚</color>",
  ui_story_5004_50041501_63_dialog_content = "進來吧。",
  ui_story_5004_50041501_64_dialog_content = "您好，請問閣下就是影鎮的斯莫奇·曼提柯爾小姐吧？",
  ui_story_5004_50041501_65_dialog_content = "……妳知道我？",
  ui_story_5004_50041501_66_dialog_content = "當然，還包括您來這裡的原因，以及還有您拿到了一封不屬於您的信件。",
  ui_story_5004_50041501_67_dialog_content = "說吧，妳有什麼企圖。",
  ui_story_5004_50041501_68_dialog_content = "噗……噗哈哈哈。",
  ui_story_5004_50041501_69_dialog_content = "……？",
  ui_story_5004_50041501_70_dialog_content = "抱、抱歉……但是您的問題，真的很讓人想笑啊。",
  ui_story_5004_50041501_71_dialog_content = "怎麼會有企圖呢，我只是以主持人的身分，來邀請您參加這次的「潮汐祭」而已。",
  ui_story_5004_50041501_72_dialog_content = "就這麼簡單？",
  ui_story_5004_50041501_73_dialog_content = "就是這麼簡單喔。",
  ui_story_5004_50041501_74_dialog_content = "妳是真理結社的人吧，我對妳們缺乏信任。",
  ui_story_5004_50041501_75_dialog_content = "就算是真理結社的人，也可以有兼職司儀或者主持人的小小愛好吧。",
  ui_story_5004_50041501_76_dialog_content = "此外，在追尋真正的真理時也需要物質作為基礎，而這份工作能讓我得到很豐厚的報酬。",
  ui_story_5004_50041501_77_dialog_content = "那麼您想要參加嗎……也許您所追尋的東西就在勝利者的獎賞之中喔。",
  ui_story_5004_50041501_78_dialog_content = "即使輸了也……",
  ui_story_5004_50041501_79_dialog_content = "不用說了，我不會輸，對輸了會怎麼樣也沒興趣。",
  ui_story_5004_50041501_80_dialog_content = "那個跑腿的，是不是妳們的人？",
  ui_story_5004_50041501_81_dialog_content = "哎呀，那種事人家怎麼知道嘛~",
  ui_story_5004_50041501_82_dialog_content = "呵，既然來都來了，也沒必要逃避。",
  ui_story_5004_50041501_83_dialog_content = "我倒是要看看，妳這傢伙能在我眼皮底下打什麼鬼主意。",
  ui_story_5004_50041601_1_dialog_content = "妳的意思是說……拜里厄的病症是因為她體內的光能力量不穩定？",
  ui_story_5004_50041601_2_dialog_content = "嗯，我這幾天和我的助手小貝爾塔聯絡，她查到了類似的症狀喔。",
  ui_story_5004_50041601_3_dialog_content = "另外還有一份關於「戈蒂埃」家族的捲宗……",
  ui_story_5004_50041601_4_dialog_content = "但是被祕典庭嚴密監管著，只有城主和少數人能查閱。",
  ui_story_5004_50041601_5_dialog_content = "「戈蒂埃」……是拜里厄的姓氏吧？",
  ui_story_5004_50041601_6_dialog_content = "沒錯！我們晚上在聊天時她講過一些自己家族的事，還提到過另一個什麼家族來著……",
  ui_story_5004_50041601_7_dialog_content = "唔……皮洛斯什麼的……人家一下想不起來啦。",
  ui_story_5004_50041601_8_dialog_content = "嗯……想不起來也不用勉強，不過妳們關係感覺很不錯嘛。",
  ui_story_5004_50041601_9_dialog_content = "當然啦，女孩子之間就是很容易無話不談的嘛~更何況拜里厄其實比你想像中更健談喔。",
  ui_story_5004_50041601_10_dialog_content = "原來如此……總之拜里厄的事就要多辛苦妳啦。",
  ui_story_5004_50041601_11_dialog_content = "就交給我吧~我會找卡蓮姐姐再想想辦法的，有新的情報再告訴你喔~！",
  ui_story_5004_50041601_12_dialog_content = "那我先回去陪小拜里厄啦！等會賽場上見！",
  ui_story_5004_50041601_13_dialog_content = "好，路上小心點。",
  ui_story_5004_50041601_14_dialog_content = "嗚——！",
  ui_story_5004_50041601_15_dialog_content = "嗯？你沒事吧。",
  ui_story_5004_50041601_16_dialog_content = "沒、沒事，抱歉！",
  ui_story_5004_50041601_17_dialog_content = "欸？斯莫奇妳怎麼來了。",
  ui_story_5004_50041601_18_dialog_content = "你叫PlayerName是吧？我想和你正式認識一下。",
  ui_story_5004_50041601_19_dialog_content = "我叫斯莫奇，是影鎮來的。",
  ui_story_5004_50041601_20_dialog_content = "……",
  ui_story_5004_50041601_21_dialog_content = "……",
  ui_story_5004_50041601_22_dialog_content = "沒了？",
  ui_story_5004_50041601_23_dialog_content = "沒了。",
  ui_story_5004_50041601_24_dialog_content = "呃……那麼斯莫奇，妳來是有什麼事嗎？",
  ui_story_5004_50041601_25_dialog_content = "既然是同隊的隊友，我就想和你打個招呼。",
  ui_story_5004_50041601_26_dialog_content = "從上次的賽況看，只靠我一個人也許會遇到難以應付的情況。",
  ui_story_5004_50041601_27_dialog_content = "（真的會有那種情況嗎……）",
  ui_story_5004_50041601_28_dialog_content = "所以想和你們打好關係。",
  ui_story_5004_50041601_29_dialog_content = "總之一起加油囉，回頭見。",
  ui_story_5004_50041601_30_dialog_content = "等一下。",
  ui_story_5004_50041601_31_dialog_content = "嗯？還有事嗎？",
  ui_story_5004_50041601_32_dialog_content = "我想冒昧問一下……妳和吉納維芙是怎麼回事？",
  ui_story_5004_50041601_33_dialog_content = "好吧……我就知道你要問。",
  ui_story_5004_50041601_34_dialog_content = "不過我的回答大概也很難讓你滿意。",
  ui_story_5004_50041601_35_dialog_content = "我們兩個都出生在佩德羅堡，我是曼提柯爾家族，她是渥倫斯奇家族。",
  ui_story_5004_50041601_36_dialog_content = "該怎麼說，兩個家族一直很不對盤吧。不過我們兩個小時候感情還滿好的。",
  ui_story_5004_50041601_37_dialog_content = "她那個時候還挺可愛的，喜歡粘著我，比現在討人喜歡多了。",
  ui_story_5004_50041601_38_dialog_content = "後來可能是因為我那個時候還很年輕，叛逆又喜歡追求刺激。",
  ui_story_5004_50041601_39_dialog_content = "在吉納維芙參加的一次考核中小小露了一手。",
  ui_story_5004_50041601_X39_dialog_content = "結果就被考官看上了，讓她錯失了成為白夜城大貴族的機會。",
  ui_story_5004_50041601_40_dialog_content = "這件事讓她和她的家族都感到恥辱吧。",
  ui_story_5004_50041601_41_dialog_content = "不過我只是想搞點刺激的玩玩而已，誰知道他們那麼脆弱。",
  ui_story_5004_50041601_42_dialog_content = "所以說啊，這些貴族什麼的就是這麼麻煩。之後我就離家出走了。",
  ui_story_5004_50041601_43_dialog_content = "原來如此……",
  ui_story_5004_50041601_44_dialog_content = "沒事了吧，那我走了。下午的比賽多加油。",
  ui_story_5004_50041701_1_dialog_content = "呼……",
  ui_story_5004_50041701_2_dialog_content = "PlayerName，很緊張嗎？",
  ui_story_5004_50041701_3_dialog_content = "有點……",
  ui_story_5004_50041701_4_dialog_content = "也不用太緊張啦，緋長官教過我一句話，叫<color=#FFB400>「車來將擋水來土埋」</color>。",
  ui_story_5004_50041701_5_dialog_content = "應該是<color=#FFB400>「兵來將擋水來土掩」</color>吧。",
  ui_story_5004_50041701_6_dialog_content = "對對，我還一直納悶這句話是指緋長官掀翻過紅油扳手的車嗎。",
  ui_story_5004_50041701_7_dialog_content = "（被緋聽到的話，一定要罰抄這句一百遍的！）",
  ui_story_5004_50041701_8_dialog_content = "今天我帶著月之繭，衝鋒陷陣的事就儘管交給我。",
  ui_story_5004_50041701_9_dialog_content = "那我也從場外發射導彈幫助大家吧！",
  ui_story_5004_50041701_10_dialog_content = "不行不行！雖然說是戰鬥為主的比賽，還是要遵守一下基礎規則啦。",
  ui_story_5004_50041701_11_dialog_content = "拉斐爾的導彈……果然還是留著用來對付暗鬼比較好吧。",
  ui_story_5004_50041701_12_dialog_content = "畢竟妳可是白夜城的……天使呢。",
  ui_story_5004_50041701_13_dialog_content = "嗯~也對呢，也要留著保護小拜里厄才行。",
  ui_story_5004_50041701_14_dialog_content = "那我和小拜里厄就幫你們加油打氣吧！",
  ui_story_5004_50041701_15_dialog_content = "對了薇絲，妳是擔任近衛的位置，應該不能用弓箭吧。",
  ui_story_5004_50041701_16_dialog_content = "沒錯，我為了應對這種情況，讓拜里厄幫我製作了可以加裝在弓上的結晶雙刀呢。",
  ui_story_5004_50041701_17_dialog_content = "我嘗試了很久，直到今天凌晨才製作出比較滿意的成品……",
  ui_story_5004_50041701_18_dialog_content = "如果能幫上忙就太好了……",
  ui_story_5004_50041701_19_dialog_content = "看起來就很結實又鋒利，能感覺到拜里厄非常用心呢。",
  ui_story_5004_50041701_20_dialog_content = "（拜里厄真是好孩子……）",
  ui_story_5004_50041701_21_dialog_content = "謝謝你，接下來就看著我們奪得勝利吧！",
  ui_story_5004_50041701_22_dialog_content = "嗯，薇絲現在看起來非常可靠！非常有精神！",
  ui_story_5004_50041701_23_dialog_content = "（不過明明是弓兵卻要用雙刀……真的沒問題嗎？）",
  ui_story_5004_50041701_24_dialog_content = "也許不會演變成很激烈的戰鬥吧，畢竟只是下棋。",
  ui_story_5004_50041701_25_dialog_content = "……如果只是下棋還好，但是斯莫奇和吉納維芙都不是會輕易服輸的類型。",
  ui_story_5004_50041701_26_dialog_content = "必須要做好萬全的準備。",
  ui_story_5004_50041701_27_dialog_content = "咳咳，看來大家都就位了嘛。",
  ui_story_5004_50041701_28_dialog_content = "請各位稍安勿躁——",
  ui_story_5004_50041701_29_dialog_content = "相傳，在大陸上廣受好評的軍棋，最初就是源自於這裡。",
  ui_story_5004_50041701_30_dialog_content = "曾經的此處，有一位英明而慈愛的君主，他希望自己的子民能英勇與聰慧並重。",
  ui_story_5004_50041701_31_dialog_content = "因此他發明了這種遊戲來鍛鍊自己臣民的思辨能力與戰術意識。",
  ui_story_5004_50041701_32_dialog_content = "得益於此，國王擁有了一支讓暗鬼聞風喪膽的鐵衛，保護王國能夠免受侵擾，人人安居樂業。",
  ui_story_5004_50041701_33_dialog_content = "不過，那些都是舊日往事了。",
  ui_story_5004_50041701_34_dialog_content = "今天為了紀念這位君主，就以真人軍棋的方式進行第二次比賽！",
  ui_story_5004_50041701_35_dialog_content = "我在此宣布——象徵智慧與決心的軍棋比賽，現在開始！",
  ui_story_5004_50041701_36_dialog_content = "PlayerName！",
  ui_story_5004_50041701_37_dialog_content = "啊，我在！",
  ui_story_5004_50041701_38_dialog_content = "打起精神來，指揮就拜託你了。我們會全力為你奪得勝利。",
  ui_story_5004_50041701_39_dialog_content = "（打起精神，打起精神，我沒問題的，我多少也和巴頓下過棋。）",
  ui_story_5004_50041701_40_dialog_content = "（讓我回憶一下……當初和巴頓……）",
  ui_story_5004_50041701_41_dialog_content = "我們勝利的原因是<color=#FFB400>「曾經，主將們為我們開拓了路線」</color>。",
  ui_story_5004_50041701_42_dialog_content = "我知道了……！！",
  ui_story_5004_50041701_43_dialog_content = "看我的吧，巴頓……就由主將，就由我身先士卒！",
  ui_story_5004_50041701_44_dialog_content = "輪到我了！",
  ui_story_5004_50041701_45_dialog_content = "王進一！",
  ui_story_5004_50041701_46_dialog_content = "……",
  ui_story_5004_50041701_47_dialog_content = "PlayerName啊……雖然我不會玩什麼狗屁軍棋。",
  ui_story_5004_50041701_48_dialog_content = "但我認為你不能讓自己進一，除非你是想衝過來騎在我身上。",
  ui_story_5004_50041701_49_dialog_content = "呵呵呵——",
  ui_story_5004_50041701_50_dialog_content = "那邊的空裔，我知道你的族人和你對戰術指揮的確有一套。",
  ui_story_5004_50041701_51_dialog_content = "但是看來你完全不懂軍棋這種高雅的比賽吧！",
  ui_story_5004_50041701_52_dialog_content = "為了戰力上能夠不遜於你身邊的光靈，我可是特地招募了更為強大的<color=#FFB400>勇士</color>——！",
  ui_story_5004_50041701_53_dialog_content = "嘖，這女人廢話好多。說好了不透露真實身分的吧。",
  ui_story_5004_50041701_54_dialog_content = "老闆老闆，您這樣可是違反合約內容的，就在第三條第九款。",
  ui_story_5004_50041701_55_dialog_content = "按照合約可是要額外賠付僱傭費用的百分之一百三十五喔。",
  ui_story_5004_50041701_56_dialog_content = "別廢話了，錢一定會如數結給你們……給我上！",
  ui_story_5004_50041701_57_dialog_content = "PlayerName！和我建立感應，我來幫你指揮棋局！",
  ui_story_5004_50041701_58_dialog_content = "好，拜託了！",
  ui_story_5004_50041701_59_dialog_content = "哈——！",
  ui_story_5004_50041701_60_dialog_content = "唔！！這傢伙的刀法好厲害……幾乎和緋長官一樣強……",
  ui_story_5004_50041701_61_dialog_content = "而且招式也……難道你是……！？",
  ui_story_5004_50041701_62_dialog_content = "呵呵……既然被發現了，那我也無需繼續隱藏身分。",
  ui_story_5004_50041701_63_dialog_content = "瀧先生！！",
  ui_story_5004_50041701_64_dialog_content = "瀧？！",
  ui_story_5004_50041701_65_dialog_content = "你怎麼會在這裡？？",
  ui_story_5004_50041701_66_dialog_content = "抱歉啦小子……所謂萬事屋啊，就是只要給錢且不違反道義的委託全都會接！",
  ui_story_5004_50041701_67_dialog_content = "何況只是參加個比賽，我是不會手下留情的！",
  ui_story_5004_50041701_68_dialog_content = "PlayerName，我勸你快點投降，我可不想讓手無寸鐵的你受傷！",
  ui_story_5004_50041701_69_dialog_content = "瀧、瀧先生，如果現在被發現了，以後我的生意會很難做呀！",
  ui_story_5004_50041701_70_dialog_content = "有破綻！",
  ui_story_5004_50041701_71_dialog_content = "哎唷！",
  ui_story_5004_50041701_72_dialog_content = "卡蓮輕點！椰汁快要灑出來了！",
  ui_story_5004_50041701_72X1_dialog_content = "你在幻想什麼呢，那只是頭套，又不是真的椰子。",
  ui_story_5004_50041701_72X2_dialog_content = "對……對啊，可惡，也太像真椰子了吧！",
  ui_story_5004_50041701_73_dialog_content = "狡木……我就知道是你。",
  ui_story_5004_50041701_74_dialog_content = "老闆，你聽我解釋……我可是<color=#FFB400>為了您</color>才接下這份委託的。",
  ui_story_5004_50041701_75_dialog_content = "什麼？為了我？",
  ui_story_5004_50041701_76_dialog_content = "沒錯！只要從吉納維芙老闆那裡拿到獎金的話，我就能擴大經營規模。",
  ui_story_5004_50041701_77_dialog_content = "以後<color=#FFB400>耀晶</color>之類的東西，說不定也能從我這裡用白夜幣買到呢。",
  ui_story_5004_50041701_78_dialog_content = "到時候我可以給您打九……九五折，再送您一個當月限量款的<color=#FFB400>可愛小盒子</color>。",
  ui_story_5004_50041701_79_dialog_content = "PlayerName，其他那些帶著<color=#FFFFFF>頭套</color>的傢伙也很可疑……！",
  ui_story_5004_50041701_80_dialog_content = "先去把那些傢伙的頭套扯下來啦~！",
  ui_story_5004_50041701_81_dialog_content = "知道了！薇絲，卡蓮，拜託了！",
  ui_story_5004_50041701_82_dialog_content = "什、什麼！！鋸子沒油了！我走了！",
  ui_story_5004_50041701_83_dialog_content = "我、我不玩了，告辭！",
  ui_story_5004_50041701_84_dialog_content = "唧唧！",
  ui_story_5004_50041701_85_dialog_content = "嘖，果然都是些靠不住的傢伙。",
  ui_story_5004_50041701_86_dialog_content = "哎呀呀，看來戰況陷入膠著了呢。",
  ui_story_5004_50041701_87_dialog_content = "一方是棋子紛紛逃跑，而另一方是馬上要被將軍的狀況呀。",
  ui_story_5004_50041701_88_dialog_content = "喂，快點讓我行動！",
  ui_story_5004_50041701_89_dialog_content = "不管是過去升變，還是直接一路殺過去將軍，只要我能靠近吉納維芙，就可以把那傢伙打趴！",
  ui_story_5004_50041701_90_dialog_content = "喂，不行吧？這種情況一定是要讓卡蓮回防薇絲，再重整陣勢進攻吧！",
  ui_story_5004_50041701_91_dialog_content = "沒那個時間了，現在對面軍心不穩正是機會。沒時間讓你悠哉地回去救小女友了。",
  ui_story_5004_50041701_92_dialog_content = "啊？我們不是……",
  ui_story_5004_50041701_93_dialog_content = "聽我的就能贏，明白了嗎！",
  ui_story_5004_50041701_94_dialog_content = "好、好的！",
  ui_story_5004_50041701_95_dialog_content = "吉納維芙！",
  ui_story_5004_50041701_96_dialog_content = "過來吧！斯莫奇！",
  ui_story_5004_50041701_97_dialog_content = "哈！",
  ui_story_5004_50041701_98_dialog_content = "一上來就用最強的招式嗎！",
  ui_story_5004_50041701_99_dialog_content = "呵——",
  ui_story_5004_50041701_100_dialog_content = "被接下了！？那個吉納維芙的格鬥技巧也如此純熟！？",
  ui_story_5004_50041701_101_dialog_content = "上次只是我一時大意，別以為你每次都能贏過我！",
  ui_story_5004_50041701_102_dialog_content = "確實是比以前厲害了，不過想超過我還早得很！！",
  ui_story_5004_50041701_103_dialog_content = "不行……兩個人根本不分高下，再打一下去，場地都要被迸濺出來的火焰燒到了！",
  ui_story_5004_50041701_104_dialog_content = "妳們再這樣打個沒完馬上就要超時啦。",
  ui_story_5004_50041701_105_dialog_content = "沒辦法了——既然這樣，就只能動用附加規則了。",
  ui_story_5004_50041701_106_dialog_content = "我們就換備用的比賽方式吧！",
  ui_story_5004_50041701_107_dialog_content = "我事前在場地的中央埋了一顆「水晶國王」棋子。",
  ui_story_5004_50041701_108_dialog_content = "雙方之中的「王」，誰能首先拿到埋藏的「王」就算勝利！",
  ui_story_5004_50041701_109_dialog_content = "果然還是到了這一步嗎……！親衛隊，給我上！",
  ui_story_5004_50041701_110_dialog_content = "給我上！攻擊！",
  ui_story_5004_50041701_111_dialog_content = "為了吉納維芙大人——！",
  ui_story_5004_50041701_112_dialog_content = "嘖，我還在想這群傢伙上哪去了，妳居然還留了一手。",
  ui_story_5004_50041701_113_dialog_content = "等、等一下，到底怎麼回事。水槍是幹嘛的？那些親衛隊又為什麼突然參戰了？！",
  ui_story_5004_50041701_114_dialog_content = "看來你又沒讀我新送過去的手冊吧——",
  ui_story_5004_50041701_115_dialog_content = "新送來的那本廣告又多了一倍吧！！",
  ui_story_5004_50041701_116_dialog_content = "上次的比賽場面非常轟動，所以又多了很多廣告商嘛。",
  ui_story_5004_50041701_117_dialog_content = "剛剛的棋局因為吉納維芙長時間未移動，被認定為平局了。",
  ui_story_5004_50041701_118_dialog_content = "現在進入追加的水槍亂鬥時間，只能用水槍比賽喔！",
  ui_story_5004_50041701_119_dialog_content = "總而言之PlayerName，只靠開始之前讓別人唸「戰鬥手冊」可是永遠沒法成長的——",
  ui_story_5004_50041701_120_dialog_content = "突然從那麼正式的比賽變成超級具有夏日氛圍的比賽，我的適應力可沒那麼強啊！",
  ui_story_5004_50041701_121_dialog_content = "而且我們也沒準備水槍……",
  ui_story_5004_50041701_122_dialog_content = "欸？妳們手裡是什麼？！",
  ui_story_5004_50041701_123_dialog_content = "薇絲，找掩護反擊！",
  ui_story_5004_50041701_124_dialog_content = "明白！PlayerName你也快躲起來！",
  ui_story_5004_50041701_125_dialog_content = "我……我沒有武器呀！",
  ui_story_5004_50041701_126_dialog_content = "PlayerName！接著！",
  ui_story_5004_50041701_127_dialog_content = "拜里厄！太好了！！",
  ui_story_5004_50041701_128_dialog_content = "想得美！！",
  ui_story_5004_50041701_129_dialog_content = "唔！！",
  ui_story_5004_50041701_130_dialog_content = "幹、幹得好啊妳們！不對，斯莫奇妳想想辦——",
  ui_story_5004_50041701_131_dialog_content = "看來也得讓你們見識見識我的手段……！",
  ui_story_5004_50041701_132_dialog_content = "妳這兩把<color=#FFB400>超重型水槍</color>是哪裡來的？！！",
  ui_story_5004_50041701_133_dialog_content = "別以為人多就能贏了，你們這群雜魚！！",
  ui_story_5004_50041701_134_dialog_content = "可惡！保護吉納維芙大人！",
  ui_story_5004_50041701_135_dialog_content = "我、我不行了，隊長——",
  ui_story_5004_50041701_136_dialog_content = "啊——！！！",
  ui_story_5004_50041701_136X1_dialog_content = "好大的膽子，居然敢對我的手下出手。",
  ui_story_5004_50041701_136X2_dialog_content = "那也別怪我無情了！",
  ui_story_5004_50041701_136X3_dialog_content = "嗚！眼睛睜不開了！",
  ui_story_5004_50041701_136X4_dialog_content = "薇絲快撤退，我來掩護妳。",
  ui_story_5004_50041701_136X5_dialog_content = "讓妳也嚐嚐我手裡這把「玫瑰狩獵者」的厲害。",
  ui_story_5004_50041701_136X6_dialog_content = "嘿——！！",
  ui_story_5004_50041701_136X7_dialog_content = "唔！我、我也……看不見了。",
  ui_story_5004_50041701_136X8_dialog_content = "現在又不是在海底，卡蓮妳可以的！",
  ui_story_5004_50041701_136X9_dialog_content = "而且妳們兩個都是擅長水屬性光能術的人，為什麼輕易就被水槍壓制了？！",
  ui_story_5004_50041701_136X10_dialog_content = "哈——哈——哈——不想變成落湯雞就給我馬上投降吧！",
  ui_story_5004_50041701_136X11_dialog_content = "妳笑得太大聲了！",
  ui_story_5004_50041701_136X12_dialog_content = "斯莫奇！？果然區區幾個親衛隊阻攔不了妳嗎……",
  ui_story_5004_50041701_136X13_dialog_content = "大家，都給我集中壓制斯莫奇！讓我先收拾這兩個傢伙！",
  ui_story_5004_50041701_138_dialog_content = "是！集中火力！",
  ui_story_5004_50041701_139_dialog_content = "喝——！喝——！喝——！！",
  ui_story_5004_50041701_140_dialog_content = "嘖！攻擊密集到不能瞄準了！！",
  ui_story_5004_50041701_141_dialog_content = "斯莫奇被壓制住了！喂，黑潮你們也想想辦法！",
  ui_story_5004_50041701_142_dialog_content = "可惡，能有什麼辦法？你都沒看說明了，我怎麼可能看！",
  ui_story_5004_50041701_143_dialog_content = "完全沒任何準備啊！不如直接用拳頭打過去吧！",
  ui_story_5004_50041701_144_dialog_content = "黑潮，PlayerName，你們看我從口袋裡發現了什麼！",
  ui_story_5004_50041701_145_dialog_content = "是防水防塵又保暖的<color=#FFB400>露營帳篷</color>，大家要不要躲進來休息一下。",
  ui_story_5004_50041701_146_dialog_content = "誰想和你莫名其妙地一起搭帳篷！",
  ui_story_5004_50041701_147_dialog_content = "水槍打在帳篷上聽起來就像是雨聲一樣，不是很愉快的體驗嗎？",
  ui_story_5004_50041701_148_dialog_content = "那還有把<color=#FFB400>露營椅</color>，你不如坐下來休息一下——",
  ui_story_5004_50041701_149_dialog_content = "不要！！",
  ui_story_5004_50041701_150_dialog_content = "喂！你們幾個別在那裡露營了！",
  ui_story_5004_50041701_151_dialog_content = "你叫黑潮是吧！",
  ui_story_5004_50041701_152_dialog_content = "沒錯，幹嘛！",
  ui_story_5004_50041701_153_dialog_content = "我來製造機會，你趁機把PlayerName給我丟到中間，直接把棋子剷出來！",
  ui_story_5004_50041701_154_dialog_content = "？？？",
  ui_story_5004_50041701_155_dialog_content = "嗄？我為什麼要聽妳的？",
  ui_story_5004_50041701_156_dialog_content = "如果這都做不到，就滾進帳篷裡「聽雨」吧！",
  ui_story_5004_50041701_157_dialog_content = "我！！PlayerName，你忍耐一下！",
  ui_story_5004_50041701_158_dialog_content = "別、別這樣！還有其他辦法吧！",
  ui_story_5004_50041701_159_dialog_content = "三、二——",
  ui_story_5004_50041701_160_dialog_content = "黑潮你冷靜點，你先把我放下好嗎！",
  ui_story_5004_50041701_161_dialog_content = "一！",
  ui_story_5004_50041701_162_dialog_content = "求求你瞄準一點——！！",
  ui_story_5004_50041701_163_dialog_content = "……",
  ui_story_5004_50041701_164_dialog_content = "……",
  ui_story_5004_50041701_165_dialog_content = "PlayerName……",
  ui_story_5004_50041701_166_dialog_content = "快醒醒……",
  ui_story_5004_50041701_167_dialog_content = "媽媽……？",
  ui_story_5004_50041701_168_dialog_content = "PlayerName，醒醒。",
  ui_story_5004_50041701_169_dialog_content = "……黑潮？！",
  ui_story_5004_50041701_170_dialog_content = "我們贏了……你剛剛被黑潮拋出去，衝破了親衛隊射擊組成的水幕，用頭剷出了棋子……",
  ui_story_5004_50041701_171_dialog_content = "那些親衛隊員氣急敗壞地對著暈過去的你射擊，還好吉納維芙馬上喝止了他們。",
  ui_story_5004_50041701_172_dialog_content = "抱歉……只有擔任保全的黑潮受過溺水搶救的訓練。",
  ui_story_5004_50041701_173_dialog_content = "這樣嗎……那讓我再休息一會吧……",
  ui_story_5004_50041901_1_dialog_content = "……",
  ui_story_5004_50041901_2_dialog_content = "吉納維芙。",
  ui_story_5004_50041901_3_dialog_content = "妳的未來，肩負著振興沃倫斯奇家族的重任。",
  ui_story_5004_50041901_4_dialog_content = "……",
  ui_story_5004_50041901_5_dialog_content = "而現在的妳，雖然還是個小孩子，仍然必須接受嚴苛的鍛鍊。",
  ui_story_5004_50041901_6_dialog_content = "這也是為了妳好。",
  ui_story_5004_50041901_7_dialog_content = "是的……我明白，父親、母親。",
  ui_story_5004_50041901_8_dialog_content = "這位是妳的光能術老師，也是妳的禮儀老師。她曾經是白夜城的大貴族。",
  ui_story_5004_50041901_9_dialog_content = "為了渥倫斯奇家族，一定要遵從老師的教導刻苦練習。",
  ui_story_5004_50041901_10_dialog_content = "我清楚了。",
  ui_story_5004_50041901_11_dialog_content = "這樣一定能超過曼提柯爾家族的女孩吧。",
  ui_story_5004_50041901_12_dialog_content = "吉納維芙，吉納維芙？",
  ui_story_5004_50041901_13_dialog_content = "嗯？抱歉，老師。",
  ui_story_5004_50041901_14_dialog_content = "妳居然分心了，這可不像妳。",
  ui_story_5004_50041901_15_dialog_content = "想快點完成您指派的功課，所以昨天有點晚睡。",
  ui_story_5004_50041901_16_dialog_content = "那是一週的量，妳不用這麼拼命。",
  ui_story_5004_50041901_17_dialog_content = "……",
  ui_story_5004_50041901_18_dialog_content = "吉納維芙，妳長大之後想做什麼？",
  ui_story_5004_50041901_19_dialog_content = "為家族贏得榮耀……？",
  ui_story_5004_50041901_20_dialog_content = "我在問妳想做的事。",
  ui_story_5004_50041901_21_dialog_content = "不知道……我真的不知道……或許我沒什麼想做的。",
  ui_story_5004_50041901_22_dialog_content = "唉，不說這個了。",
  ui_story_5004_50041901_23_dialog_content = "吉納維芙，妳上週又去見那個曼提柯爾家族的女孩了吧？",
  ui_story_5004_50041901_24_dialog_content = "啊！老師您怎麼知道！",
  ui_story_5004_50041901_25_dialog_content = "噓，這件事只有我知道。放心吧，我不會告訴任何人的。",
  ui_story_5004_50041901_26_dialog_content = "謝謝您。",
  ui_story_5004_50041901_27_dialog_content = "但是你為什麼……",
  ui_story_5004_50041901_28_dialog_content = "算了，我不該問這種問題。",
  ui_story_5004_50041901_29_dialog_content = "……",
  ui_story_5004_50041901_30_dialog_content = "不過吉納維芙，妳也許不該這麼執著於為家族贏得榮耀。",
  ui_story_5004_50041901_31_dialog_content = "為什麼？！",
  ui_story_5004_50041901_32_dialog_content = "妳知道為什麼我是「曾經」的大貴族嗎？",
  ui_story_5004_50041901_33_dialog_content = "感謝您這些年的辛勤教導。",
  ui_story_5004_50041901_34_dialog_content = "就不必多禮了，吉納維芙她很有天賦，也很刻苦。",
  ui_story_5004_50041901_35_dialog_content = "她對儀式魔法的造詣已經遠超大多數貴族。",
  ui_story_5004_50041901_36_dialog_content = "正因如此，我也沒什麼能再教給她的東西了。",
  ui_story_5004_50041901_37_dialog_content = "老師，您要去哪裡？",
  ui_story_5004_50041901_38_dialog_content = "用妳的話說：不知道。也許是去追尋某些事，或者是某個人。",
  ui_story_5004_50041901_39_dialog_content = "而且，追尋的本身可能也是一種意義。",
  ui_story_5004_50041901_40_dialog_content = "吉納維芙，保重。",
  ui_story_5004_50041901_41_dialog_content = "什麼！那些暗鬼真的已經逼近了嗎？！",
  ui_story_5004_50041901_42_dialog_content = "光靠我們是無力保護佩德羅堡的，必須向白夜城求助。",
  ui_story_5004_50041901_43_dialog_content = "白夜城的薩拉爾家族已經答應派遣援軍……但他們有個條件。",
  ui_story_5004_50041901_44_dialog_content = "他們要檢驗我們家族嫡子所掌握的儀式魔法力量，並想將其吸納進自己的旁系家族。",
  ui_story_5004_50041901_45_dialog_content = "如果我們能和這樣的大家族締結關係，也不是什麼壞事，對渥倫斯奇家族也大有益處。",
  ui_story_5004_50041901_46_dialog_content = "吉納維芙。",
  ui_story_5004_50041901_47_dialog_content = "我明白了，父親。",
  ui_story_5004_50041901_48_dialog_content = "吉納維芙·渥倫斯奇小姐，您果然不同凡響。",
  ui_story_5004_50041901_49_dialog_content = "這項測試結束後，您就可以面見長老了。",
  ui_story_5004_50041901_50_dialog_content = "謝謝。",
  ui_story_5004_50041901_51_dialog_content = "唷！",
  ui_story_5004_50041901_52_dialog_content = "斯莫奇！？妳怎麼在這裡？",
  ui_story_5004_50041901_53_dialog_content = "就是聽說有個什麼比賽，想來試試嘛。",
  ui_story_5004_50041901_54_dialog_content = "對著這個靶子攻擊一下，展示光能術就行了？",
  ui_story_5004_50041901_55_dialog_content = "啊、啊！這是……！",
  ui_story_5004_50041901_56_dialog_content = "多麼強大的力量！一個小女孩怎麼可能！",
  ui_story_5004_50041901_57_dialog_content = "妳、妳叫什麼名字！妳是哪個家族的？",
  ui_story_5004_50041901_58_dialog_content = "嗯？要給我獎品嗎？一般的東西我可看不上。",
  ui_story_5004_50041901_59_dialog_content = "記好了！我是曼提柯爾家族的斯莫奇——！",
  ui_story_5004_50041901_60_dialog_content = "曼提柯爾的……斯莫奇……",
  ui_story_5004_50041901_61_dialog_content = "沒有其他挑戰了嗎？就這一個？",
  ui_story_5004_50041901_62_dialog_content = "是的！請您稍等一下！我們長老有話要對您……",
  ui_story_5004_50041901_63_dialog_content = "稍等？等不了等不了，我還要去買衣服呢。",
  ui_story_5004_50041901_64_dialog_content = "小吉，走嗎？一起逛街去吧！",
  ui_story_5004_50041901_65_dialog_content = "妳……",
  ui_story_5004_50041901_66_dialog_content = "唉，吉納維芙。",
  ui_story_5004_50041901_67_dialog_content = "妳錯過了一生難得的機會。",
  ui_story_5004_50041901_68_dialog_content = "不過還好，薩拉爾家族還是願意出兵保護佩德羅堡。",
  ui_story_5004_50041901_69_dialog_content = "但我們沒有機會與他們締結聯盟了。",
  ui_story_5004_50041901_70_dialog_content = "妳先退下吧。",
  ui_story_5004_50041901_71_dialog_content = "對不起……父親……",
  ui_story_5004_50041901_72_dialog_content = "（斯莫奇……妳為什麼要出現在那裡……）",
  ui_story_5004_50041901_73_dialog_content = "（妳真的只是單純想要比賽……想贏過我嗎？……還是……）",
  ui_story_5004_50041901_74_dialog_content = "吉納維芙！",
  ui_story_5004_50041901_75_dialog_content = "怎麼了，母親？慌慌張張的，請先喘口氣……",
  ui_story_5004_50041901_76_dialog_content = "妳聽說了嗎？",
  ui_story_5004_50041901_77_dialog_content = "薩拉爾家族，去曼提柯爾那邊，要求他們履行約定了……",
  ui_story_5004_50041901_78_dialog_content = "已經去了嗎……我知道，是關於聯姻的事吧。",
  ui_story_5004_50041901_79_dialog_content = "但是那個叫斯莫奇的傢伙，不見了！",
  ui_story_5004_50041901_80_dialog_content = "什……",
  ui_story_5004_50041901_81_dialog_content = "斯莫奇她居然跑了？！",
  ui_story_5004_50041901_82_dialog_content = "可惡！這些佩德羅堡的鄉巴佬！就不該給他們機會高攀！",
  ui_story_5004_50041901_83_dialog_content = "白跑一趟。不過也好，這下不用到那種窮鄉僻壤去了。",
  ui_story_5004_50041901_84_dialog_content = "聽令！長老有令，佩德羅堡「不需要白夜城的保護」了！掉頭，回城！",
  ui_story_5004_50041901_85_dialog_content = "原本就已日薄西山的佩德羅堡陷入衰落。",
  ui_story_5004_50041901_86_dialog_content = "母親在一次意外中喪生，而父親也倒在了病榻上。",
  ui_story_5004_50041901_87_dialog_content = "吉納維芙……",
  ui_story_5004_50041901_88_dialog_content = "我在，父親。",
  ui_story_5004_50041901_89_dialog_content = "妳要守護的家族，已經快凋亡了……",
  ui_story_5004_50041901_90_dialog_content = "妳……痛苦嗎……還是感到解脫？妳……找到之後該追尋的目標了嗎……？",
  ui_story_5004_50041901_91_dialog_content = "我……我不知道，父親……這一切都太突然了，我還沒想過這些問題。",
  ui_story_5004_50041901_92_dialog_content = "可憐的孩子……",
  ui_story_5004_50041901_93_dialog_content = "……",
  ui_story_5004_50041901_94_dialog_content = "安娜，想不到最後妳也要離開我了。",
  ui_story_5004_50041901_95_dialog_content = "嘶……嘶……",
  ui_story_5004_50041901_96_dialog_content = "小姑娘，這匹馬是妳的朋友嗎？",
  ui_story_5004_50041901_97_dialog_content = "嗯……",
  ui_story_5004_50041901_98_dialog_content = "我可以幫助妳拯救她，但妳也要付出……",
  ui_story_5004_50041901_99_dialog_content = "可以！我願意！我需要安娜！我需要她陪著我找到那個人！",
  ui_story_5004_50041901_100_dialog_content = "斯莫奇……",
  ui_story_5004_50041901_100X1_dialog_content = "閣下就是吉納維芙小姐吧？",
  ui_story_5004_50041901_100X2_dialog_content = "妳知道我？那就直說有什麼委託，我對閒聊之類的沒興趣。",
  ui_story_5004_50041901_100X3_dialog_content = "這次的閒聊妳一定很有興趣喔，是關於斯莫奇……",
  ui_story_5004_50041901_100X4_dialog_content = "！！",
  ui_story_5004_50041901_100X5_dialog_content = "妳知道斯莫奇？",
  ui_story_5004_50041901_100X6_dialog_content = "當然，我還知道她正在天堂階梯……",
  ui_story_5004_50041901_100X7_dialog_content = "欸？！等等，先別走呀，我還沒說完吧！",
  ui_story_5004_50041901_102_dialog_content = "吉納維芙小姐。",
  ui_story_5004_50041901_103_dialog_content = "吉納維芙小姐！",
  ui_story_5004_50041901_104_dialog_content = "嗯。",
  ui_story_5004_50041901_105_dialog_content = "親衛隊已經按照您的指示，做好炒熱氣氛的準備工作了。",
  ui_story_5004_50041901_106_dialog_content = "好……接下來就讓我直接面對妳。",
  ui_story_5004_50041901_107_dialog_content = "用我的歌聲戰勝……不，征服妳！",
  ui_story_5004_50042001_1_dialog_content = "好漂亮的舞台，這是弗勞爾設計的嗎？",
  ui_story_5004_50042001_2_dialog_content = "看那邊紅油扳手風格的裝飾，八成是吧~",
  ui_story_5004_50042001_3_dialog_content = "想不到他還真是多才多藝。",
  ui_story_5004_50042001_4_dialog_content = "PlayerName你們真的不一起參加嗎？",
  ui_story_5004_50042001_5_dialog_content = "我的話就算了吧！唱歌我不是很擅長……",
  ui_story_5004_50042001_6_dialog_content = "我……我也……人多的話，不行……",
  ui_story_5004_50042001_7_dialog_content = "人家要陪著小拜里厄，所以也算啦~",
  ui_story_5004_50042001_8_dialog_content = "嗯……！我會和拉斐爾一起……拼命幫大家加油的……！",
  ui_story_5004_50042001_9_dialog_content = "加油就交給我們吧，我會在演出高潮時用飛彈掩護大家的！",
  ui_story_5004_50042001_10_dialog_content = "千萬不要！！",
  ui_story_5004_50042001_11_dialog_content = "好的！那就交給妳們了！",
  ui_story_5004_50042001_12_dialog_content = "準備盡情欣賞我們的表演，為我們加油吶喊吧！",
  ui_story_5004_50042001_13_dialog_content = "不知不覺間已經到了潮汐祭的最後一場了，象徵智慧與美麗的——沙灘live競賽——",
  ui_story_5004_50042001_14_dialog_content = "由於廣告商不斷增加，本場比賽也特地請來了兩位重量級評審嘉賓——",
  ui_story_5004_50042001_15_dialog_content = "來自白夜城的，不願意透露姓名的S先生！",
  ui_story_5004_50042001_16_dialog_content = "咳咳。",
  ui_story_5004_50042001_17_dialog_content = "和來自影鎮的，不願意透露姓名的Y先生！",
  ui_story_5004_50042001_18_dialog_content = "大家好。",
  ui_story_5004_50042001_19_dialog_content = "波娜瑟居然還請了評審了。嗯？怎麼這兩個人看起來好眼熟？",
  ui_story_5004_50042001_20_dialog_content = "比賽的獲勝者，就會由評審和現場的各位觀眾來選出！",
  ui_story_5004_50042001_21_dialog_content = "那麼第一位——",
  ui_story_5004_50042001_22_dialog_content = "有請來自地獄的蒙面金屬歌手——",
  ui_story_5004_50042001_23_dialog_content = "吾名為塞溜溜溜溜，來自影鎮，是從不透露真容與真名的迷之歌手！",
  ui_story_5004_50042001_24_dialog_content = "這個，這不就是塞留古嗎……名字和頭盔都很好猜啊！",
  ui_story_5004_50042001_25_dialog_content = "就讓我為大家獻上來自我靈魂最深處的咆哮——",
  ui_story_5004_50042001_26_dialog_content = "用這充滿野性的嗓音為大家帶來最重金屬味道的演出！！",
  ui_story_5004_50042001_27_dialog_content = "下去！！",
  ui_story_5004_50042001_28_dialog_content = "下去下去！！",
  ui_story_5004_50042001_29_dialog_content = "這可是泳裝LIVE！",
  ui_story_5004_50042001_30_dialog_content = "你連個泳裝都沒有，湊什麼熱鬧！！",
  ui_story_5004_50042001_31_dialog_content = "和廣告說的不一樣啊！！",
  ui_story_5004_50042001_32_dialog_content = "我是來看女孩子穿泳裝的！退票退票！！",
  ui_story_5004_50042001_33_dialog_content = "噢噢噢噢，這是何等的恥辱，還好沒暴露真名。",
  ui_story_5004_50042001_34_dialog_content = "那麼大家，在未來的某一天再會吧！",
  ui_story_5004_50042001_35_dialog_content = "嗯？怎麼這樣就結束了一個，太快了吧~",
  ui_story_5004_50042001_36_dialog_content = "真可惜……這個貓頭人看起來唱歌會很好聽的樣子呢……",
  ui_story_5004_50042001_37_dialog_content = "不要被他的外表迷惑了，拜里厄！",
  ui_story_5004_50042001_38_dialog_content = "不過做得好啊塞留古，你做得太好了！",
  ui_story_5004_50042001_39_dialog_content = "所有人的期待都被完美拉低了，這樣她們一定能拿到更高的分數！",
  ui_story_5004_50042001_40_dialog_content = "接下來的好像是……弗勞爾和黑潮？",
  ui_story_5004_50042001_41_dialog_content = "<color=#e8d9bb>黑潮上台對眾人鞠了一躬，隨後對身後一伸手……</color>",
  ui_story_5004_50042001_42_dialog_content = "嗨——",
  ui_story_5004_50042001_43_dialog_content = "呀——！！！",
  ui_story_5004_50042001_44_dialog_content = "弗勞爾他對我笑了，你看到了嗎！",
  ui_story_5004_50042001_45_dialog_content = "小勞勞，你眨眼的閃光直接射穿了我的胸大肌，命中了我熾熱的心！",
  ui_story_5004_50042001_46_dialog_content = "歐——歐——",
  ui_story_5004_50042001_47_dialog_content = "怎麼連海鷗都來了！你們不該去捕魚嗎？！",
  ui_story_5004_50042001_48_dialog_content = "真的要表演那個嗎？",
  ui_story_5004_50042001_49_dialog_content = "當然！我的摯友！",
  ui_story_5004_50042001_50_dialog_content = "黑潮怎麼抽出一條鋼筋？！",
  ui_story_5004_50042001_51_dialog_content = "等等！該不會要表演那種魔術！",
  ui_story_5004_50042001_52_dialog_content = "那個紅油扳手最笨的黑潮能完成這麼複雜魔術嗎？！",
  ui_story_5004_50042001_53_dialog_content = "呀——！！！",
  ui_story_5004_50042001_54_dialog_content = "<color=#e8d9bb>突然間鋼筋已經劃破白布穿入櫃體，再從另一端刺出。</color>",
  ui_story_5004_50042001_55_dialog_content = "弗勞爾先生——！！！",
  ui_story_5004_50042001_56_dialog_content = "那個櫃子看起來搖個不停啊……",
  ui_story_5004_50042001_57_dialog_content = "弗勞爾先生沒事吧……看起來很不妙的樣子……",
  ui_story_5004_50042001_58_dialog_content = "放心啦~我已經做好搶救的準備了~",
  ui_story_5004_50042001_59_dialog_content = "應該不會鬧出人命吧？……",
  ui_story_5004_50042001_60_dialog_content = "（黑潮是不是在唸唸有詞地說著什麼，莫非是在祈禱嗎……？）",
  ui_story_5004_50042001_61_dialog_content = "箱子不動了……拉斐爾！",
  ui_story_5004_50042001_62_dialog_content = "好！準備發射！",
  ui_story_5004_50042001_63_dialog_content = "等一下！",
  ui_story_5004_50042001_64_dialog_content = "開——！",
  ui_story_5004_50042001_65_dialog_content = "天啊！實在是太神奇了！",
  ui_story_5004_50042001_66_dialog_content = "太好了……",
  ui_story_5004_50042001_67_dialog_content = "啊~沒用到呢。這樣太浪費能源啦。導彈解除鎖定！",
  ui_story_5004_50042001_68_dialog_content = "導彈！？什麼時候！？要這樣搶救嗎！？",
  ui_story_5004_50042001_69_dialog_content = "不過看起來大家都很喜歡這場表演，都在激烈地鼓掌歡呼著。",
  ui_story_5004_50042001_70_dialog_content = "我倒是因為弗勞爾先生還活著……才鼓掌的……",
  ui_story_5004_50042001_71_dialog_content = "等一下，等一下。我應該說過這場比賽只有唱歌表演吧！",
  ui_story_5004_50042001_72_dialog_content = "弗勞爾和黑潮，你們應該很清楚比賽規則。明知故犯可不好喔。",
  ui_story_5004_50042001_73_dialog_content = "哈哈，抱歉抱歉，但我真的很想為大家帶來歡樂，烘托一下比賽氣氛。",
  ui_story_5004_50042001_74_dialog_content = "可是我又不會唱歌，就只想到了這個辦法。",
  ui_story_5004_50042001_75_dialog_content = "那個女人是誰呀，對著弗勞爾指手畫腳的！",
  ui_story_5004_50042001_76_dialog_content = "弗勞爾先生，我現在就需要你帶來的快樂！",
  ui_story_5004_50042001_77_dialog_content = "（演變成才藝展示之類的節目其實也不錯吧？）",
  ui_story_5004_50042001_78_dialog_content = "（那塞留古早早退場還有點可惜。）",
  ui_story_5004_50042001_79_dialog_content = "（不對，他沒有泳裝只有貓頭。還是參加蒙面唱歌比賽比較適合。）",
  ui_story_5004_50042001_80_dialog_content = "不行就是不行，我宣布弗勞爾取消參賽資格。",
  ui_story_5004_50042001_81_dialog_content = "為什麼非得是唱歌表演啊！",
  ui_story_5004_50042001_82_dialog_content = "真是的，弗勞爾先生，回飯店的房間裡繼續給我們表演吧！",
  ui_story_5004_50042001_83_dialog_content = "汪汪！汪汪汪！",
  ui_story_5004_50042001_84_dialog_content = "喵——！",
  ui_story_5004_50042001_85_dialog_content = "怎麼還有其他動物……弗勞爾的「特殊體質」真是可怕。",
  ui_story_5004_50042001_86_dialog_content = "第八位參賽者——",
  ui_story_5004_50042001_87_dialog_content = "吉納維芙·渥倫斯奇！",
  ui_story_5004_50042001_88_dialog_content = "呵呵呵，沒想到都是這種對手。",
  ui_story_5004_50042001_89_dialog_content = "就趁現在把所有評審觀眾的目光都吸引過來，一舉拿下最高的分數！",
  ui_story_5004_50042001_90_dialog_content = "（又都是些奇怪的傢伙……）",
  ui_story_5004_50042001_91_dialog_content = "（還沒到薇絲他們嗎？）",
  ui_story_5004_50042001_92_dialog_content = "PlayerName，輪到吉納維芙了。",
  ui_story_5004_50042001_93_dialog_content = "嗯，看來最強的對手可能依舊是她——",
  ui_story_5004_50042001_94_dialog_content = "自雷雨中降下的♪",
  ui_story_5004_50042001_95_dialog_content = "——！！",
  ui_story_5004_50042001_96_dialog_content = "是無情的天譴，還是救贖的顯現♪",
  ui_story_5004_50042001_97_dialog_content = "在遙遠的地平線彼端♪",
  ui_story_5004_50042001_98_dialog_content = "是你的身影不斷變幻♪",
  ui_story_5004_50042001_99_dialog_content = "不捨的思戀喚來了暴風驟雨♪",
  ui_story_5004_50042001_100_dialog_content = "不甘庸俗地大膽邁步♪",
  ui_story_5004_50042001_101_dialog_content = "用熱情與衝動撕開前路♪",
  ui_story_5004_50042001_102_dialog_content = "將無謂的爭鬥視若靄霧♪",
  ui_story_5004_50042001_103_dialog_content = "好……好厲害。",
  ui_story_5004_50042001_104_dialog_content = "……",
  ui_story_5004_50042001_105_dialog_content = "喔喔喔喔喔喔！！吉納維芙小姐！！！！",
  ui_story_5004_50042001_106_dialog_content = "嗯，包含著深情的演唱。這份心意確確實實傳達給眾人了。",
  ui_story_5004_50042001_107_dialog_content = "吉納維芙小姐的歌聲直穿我的內心，有機會希望能來影鎮舉行個人演唱會。",
  ui_story_5004_50042001_108_dialog_content = "統計結果已經出來了。吉納維芙小姐的最終投票分數為——九點六分！",
  ui_story_5004_50042001_109_dialog_content = "可喜可賀，很高的分數呢。",
  ui_story_5004_50042001_110_dialog_content = "那麼就請吉納維芙小姐先到後台休息一下——",
  ui_story_5004_50042001_111_dialog_content = "怎麼樣，斯莫奇……妳看到我的實力了嗎！",
  ui_story_5004_50042001_112_dialog_content = "好厲害……",
  ui_story_5004_50042001_113_dialog_content = "是啊……感覺真的是飽含了心意的歌聲。",
  ui_story_5004_50042001_114_dialog_content = "（吉納維芙的演唱出乎預料地精彩，即使不算那些親衛隊員，也奪走了許多人的心。）",
  ui_story_5004_50042001_115_dialog_content = "（有點開始擔心薇絲她們了……）",
  ui_story_5004_50042001_116_dialog_content = "接下來的是三位少女的組合——蠍尾獅之吻！",
  ui_story_5004_50042001_117_dialog_content = "到薇絲她們了！",
  ui_story_5004_50042001_118_dialog_content = "終於到了嗎，啊啊……總感覺自己都跟著緊張起來了。",
  ui_story_5004_50042001_119_dialog_content = "我、我也是……！",
  ui_story_5004_50042001_120_dialog_content = "♪——",
  ui_story_5004_50042001_121_dialog_content = "♪ ♩ ♫ ♬",
  ui_story_5004_50042001_122_dialog_content = "隻身流浪的少女，今日又將往天涯何方♪",
  ui_story_5004_50042001_123_dialog_content = "點亮黑夜的燈塔，與海岸線相連於點點火光♪",
  ui_story_5004_50042001_124_dialog_content = "噢噢噢噢！！！！",
  ui_story_5004_50042001_125_dialog_content = "喝——喝——喝——！！",
  ui_story_5004_50042001_126_dialog_content = "（好厲害……就連親衛隊那些傢伙的掌聲和歡呼聲都像海嘯一樣。）",
  ui_story_5004_50042001_127_dialog_content = "浪潮的氣味，穿越撒滿海面的星屑襲來♪",
  ui_story_5004_50042001_128_dialog_content = "沉默無聲地貫徹，氣魄和果敢的鮮花盛開♪",
  ui_story_5004_50042001_129_dialog_content = "俐落地決出勝負，斬斷巨浪後的未來精彩登台♪",
  ui_story_5004_50042001_130_dialog_content = "卡蓮姐姐~！小薇絲~小斯莫奇~好棒~！！",
  ui_story_5004_50042001_131_dialog_content = "來，拜里厄也握著我的手，一起朝她們揮手吧！！",
  ui_story_5004_50042001_132_dialog_content = "嗯……！",
  ui_story_5004_50042001_133_dialog_content = "憑著永不退縮的自尊心，毫不猶豫地抓住那道光芒♪",
  ui_story_5004_50042001_134_dialog_content = "感受著內心的轟鳴，那內心深處宛如即將爆裂的激盪♪",
  ui_story_5004_50042001_135_dialog_content = "激烈地躍動♪",
  ui_story_5004_50042001_136_dialog_content = "用超越想像的衝動，追逐那頂點的夢♪",
  ui_story_5004_50042001_137_dialog_content = "來吧！衝上——♪",
  ui_story_5004_50042001_138_dialog_content = "世界的頂端——♪",
  ui_story_5004_50042001_139_dialog_content = "<color=#e8d9bb>斯莫奇一手拿著麥克風，一手朝吉納維芙方向做出手槍射擊姿勢輕輕眨眨眼，結束了這完美的一曲。</color>",
  ui_story_5004_50042001_140_dialog_content = "<color=#e8d9bb>蠍尾獅之吻的表演，完美落幕。</color>",
  ui_story_5004_50042001_141_dialog_content = "……",
  ui_story_5004_50042001_142_dialog_content = "（嗯？她什麼時候過來的？）",
  ui_story_5004_50042001_143_dialog_content = "演出不錯，不過這個組合本來是兩個人的。",
  ui_story_5004_50042001_144_dialog_content = "嗄？？",
  ui_story_5004_50042001_145_dialog_content = "（走掉了？她剛剛是在笑嗎？什麼意思？你是在講謎語嗎？）",
  ui_story_5004_50042001_146_dialog_content = "蠍尾獅之吻！蠍尾獅之吻！蠍尾獅之吻！！",
  ui_story_5004_50042001_147_dialog_content = "蠍尾獅之吻！太棒了！",
  ui_story_5004_50042001_148_dialog_content = "太好了，看來大家對演出非常滿意，就連拜里厄都很受感動的樣子。",
  ui_story_5004_50042001_149_dialog_content = "喂！都錄下來了嗎！",
  ui_story_5004_50042001_150_dialog_content = "是，是的，索……大人！",
  ui_story_5004_50042001_151_dialog_content = "這種組合……還滿有意思的。",
  ui_story_5004_50042001_154_dialog_content = "蠍尾獅之吻——",
  ui_story_5004_50042001_155_dialog_content = "毫無疑問地——十分——！",
  ui_story_5004_50042201_1_dialog_content = "乾杯——",
  ui_story_5004_50042201_2_dialog_content = "哈——",
  ui_story_5004_50042201_3_dialog_content = "什麼嘛，用飲料乾杯，簡直和小孩子一樣！",
  ui_story_5004_50042201_4_dialog_content = "但是黑潮平時喝的酒裡也都是汽油而沒有酒精吧？",
  ui_story_5004_50042201_5_dialog_content = "還不是你的錯！",
  ui_story_5004_50042201_6_dialog_content = "哈哈哈哈——",
  ui_story_5004_50042201_7_dialog_content = "卡蓮姐姐、小薇絲和小斯莫奇在剛剛的演出時都好厲害~！",
  ui_story_5004_50042201_8_dialog_content = "舞台上像是星空般閃耀的身姿讓人家完全入迷了。",
  ui_story_5004_50042201_9_dialog_content = "就連小拜里厄都感動得哭出來了對吧——！",
  ui_story_5004_50042201_10_dialog_content = "啊……我……的確是非常震撼人心的演出……",
  ui_story_5004_50042201_11_dialog_content = "大家舞台上的歌聲和身姿……讓人非常憧憬呢……",
  ui_story_5004_50042201_12_dialog_content = "既然連拜里厄都這樣說了，那演出就是無可辯駁地出色啦~",
  ui_story_5004_50042201_13_dialog_content = "也不知道那個未公開的獎品到底是什麼呢！",
  ui_story_5004_50042201_14_dialog_content = "說到那個獎品，我也很好奇。",
  ui_story_5004_50042201_15_dialog_content = "就算問了波娜瑟，她也只會一臉神祕地微笑，叫我等著明天領獎。",
  ui_story_5004_50042201_16_dialog_content = "到底是什麼呢，連我也有點期待了。",
  ui_story_5004_50042201_17_dialog_content = "希望是能讓刨冰小攤更吸引人的美味醬料。",
  ui_story_5004_50042201_18_dialog_content = "這樣就能把連鎖店鋪開到白夜城啦！",
  ui_story_5004_50042201_19_dialog_content = "恐怕……會被拉斐爾她們當做無照攤販追著跑……",
  ui_story_5004_50042201_20_dialog_content = "嗯~小薇絲的話，可以讓她先跑一分鐘再追~",
  ui_story_5004_50042201_21_dialog_content = "喂，恭喜妳們啦。",
  ui_story_5004_50042201_22_dialog_content = "吉納維芙，謝謝妳。妳是……特地來祝賀我們的嗎？",
  ui_story_5004_50042201_23_dialog_content = "哼，當然了，我可是貴族。",
  ui_story_5004_50042201_24_dialog_content = "你們該不會以為我會像個小女孩，輸了就哭哭啼啼個不停吧。",
  ui_story_5004_50042201_25_dialog_content = "沒有哭嗎？小吉真是成熟了很多呢，以前明明很容易哭的~",
  ui_story_5004_50042201_26_dialog_content = "嗯！？我現在就殺了妳！",
  ui_story_5004_50042201_27_dialog_content = "好了好了，來坐下一起喝一杯吧。過去那些恩怨什麼的，就用這杯酒來化解如何？",
  ui_story_5004_50042201_28_dialog_content = "斯莫奇順勢抓住吉納維芙，一把按在自己身邊的椅子上。",
  ui_story_5004_50042201_29X1_dialog_content = "來嚐嚐！",
  ui_story_5004_50042201_29X2_dialog_content = "嘖……真是個煩人的傢伙。",
  ui_story_5004_50042201_29X3_dialog_content = "……這酒。",
  ui_story_5004_50042201_29X4_dialog_content = "沒錯，是不是和佩德羅堡那家店裡的藏酒很像，就是我們以前經常去喝的那家。",
  ui_story_5004_50042201_29X5_dialog_content = "這個……大概有點像吧，我早就不記得了！",
  ui_story_5004_50042201_29X6_dialog_content = "蠍尾獅之吻……妳用這個名字是什麼意思？",
  ui_story_5004_50042201_29X7_dialog_content = "就和這杯酒一樣，妳應該能理解的。我想妳不會忘記那些事。",
  ui_story_5004_50042201_29X8_dialog_content = "……",
  ui_story_5004_50042201_30_dialog_content = "（這兩個人的關係真是複雜……）",
  ui_story_5004_50042201_31_dialog_content = "弗勞爾先生的魔術……有機會的話也想再看看。",
  ui_story_5004_50042201_32_dialog_content = "我一直想不透是怎麼變出來的……",
  ui_story_5004_50042201_33_dialog_content = "當然可以！我很樂意再為大家表演一次。",
  ui_story_5004_50042201_34_dialog_content = "那拜託你找個人少的地方吧！",
  ui_story_5004_50042201_35_dialog_content = "剛剛為了掩護你逃離現場，不光要被人群推擠，還要被貓貓狗狗追著咬。",
  ui_story_5004_50042201_36_dialog_content = "多虧你了，等會我來幫你消毒傷口吧。",
  ui_story_5004_50042201_37_dialog_content = "而且機器人的製作也進入尾聲了，需要你來幫忙。",
  ui_story_5004_50042201_38_dialog_content = "好，但現在先別吵我喝酒。",
  ui_story_5004_50042201_39_dialog_content = "機器人……這麼快已經要完成了嗎？",
  ui_story_5004_50042201_40_dialog_content = "即使是啟光的科研部門，也需要幾個月才能完成一台呢。",
  ui_story_5004_50042201_41_dialog_content = "這個要多虧波娜瑟小姐。我替她工作的時候，蒐集到了不少非常有用的設備和資料。",
  ui_story_5004_50042201_42_dialog_content = "我心中最完美的存在，紅油扳手的天字第一號戰術機器人！",
  ui_story_5004_50042201_43_dialog_content = "就要在今晚誕生了！！",
  ui_story_5004_50042201_44_dialog_content = "（第一次見弗勞爾這麼認真的樣子……）",
  ui_story_5004_50042201_45_dialog_content = "（看起來弗勞爾是真的很熱愛機械和機器人之類的東西……）",
  ui_story_5004_50042201_46_dialog_content = "剛剛那是……？",
  ui_story_5004_50042201_47_dialog_content = "嗚……",
  ui_story_5004_50042201_48_dialog_content = "小拜里厄？妳怎麼流汗了？",
  ui_story_5004_50042201_49_dialog_content = "拉斐爾，能麻煩妳扶我回房間嗎……？",
  ui_story_5004_50042201_50_dialog_content = "PlayerName，小拜里厄看起來不太舒服，我們先回去啦。",
  ui_story_5004_50042201_51_dialog_content = "拜里厄的身體還沒恢復嗎？雖說上次使用了很強的力量，但是已經這麼多天了。",
  ui_story_5004_50042201_52_dialog_content = "她的身體狀況似乎還是沒有好轉。",
  ui_story_5004_50042201_53_dialog_content = "可能沒那麼簡單……對了，皮洛斯家族檔案的事，拉斐爾應該和妳說過了吧。",
  ui_story_5004_50042201_54_dialog_content = "嗯，我已經申請為貝爾塔開放所有查閱的權限。",
  ui_story_5004_50042201_55_dialog_content = "至於能查到什麼有用的訊息，就只能看她們了。",
  ui_story_5004_50042301_1_dialog_content = "儀式即將成功……",
  ui_story_5004_50042301_2_dialog_content = "務必要解除「樂章」上的空裔封印……並演奏它。",
  ui_story_5004_50042301_3_dialog_content = "王的榮光會重新照耀這片海灘……給予那些傲慢的光靈制裁……",
  ui_story_5004_50042301_4_dialog_content = "我明白了……！請您放心，屬下必定拼盡全力。",
  ui_story_5004_50042301_5_dialog_content = "我來了。",
  ui_story_5004_50042301_6_dialog_content = "波娜瑟！！妳這個光靈就不能敲一下門嗎？",
  ui_story_5004_50042301_7_dialog_content = "別說那些廢話了，找我又想幹嘛？",
  ui_story_5004_50042301_8_dialog_content = "樂章即將被挖掘出來了，上面的封印……",
  ui_story_5004_50042301_9_dialog_content = "我知道我知道，需要空裔來解開嘛。",
  ui_story_5004_50042301_10_dialog_content = "我會讓PlayerName幫我搞定的。",
  ui_story_5004_50042301_11_dialog_content = "……妳就不好奇我們有什麼陰謀嗎？",
  ui_story_5004_50042301_12_dialog_content = "不好奇，就算有什麼陰謀我也要得到樂章。",
  ui_story_5004_50042301_13_dialog_content = "而且就憑你們……那些人之中隨便一個光靈就能把你們打得滿地找牙了。",
  ui_story_5004_50042301_14_dialog_content = "你們如果真的有什麼陰謀的話……我會幫你們祈禱能留個全屍的。",
  ui_story_5004_50042301_15_dialog_content = "不過那些騙錢的陰謀我只會覺得好笑。",
  ui_story_5004_50042301_16_dialog_content = "唔……！！妳這個光靈果然還是讓人火大！！",
  ui_story_5004_50042301_17_dialog_content = "等之後我一定要收拾……",
  ui_story_5004_50042301_18_dialog_content = "彭格格大人！請息怒！",
  ui_story_5004_50042301_19_dialog_content = "嗯？你也在啊，沒去繼續賣瑜伽課嗎？",
  ui_story_5004_50042301_20_dialog_content = "算了，我還要去找PlayerName他們，你們自己玩吧。",
  ui_story_5004_50042301_21_dialog_content = "等等，等等，波娜瑟小姐！",
  ui_story_5004_50042301_22_dialog_content = "我新編的宣傳標語，還請妳聽一下！",
  ui_story_5004_50042301_23_dialog_content = "……",
  ui_story_5004_50042301_24_dialog_content = "明明是我在利用那個光靈，為什麼卻惹了一肚子氣。",
  ui_story_5004_50042301_25_dialog_content = "還有這群沒用的手下……賣課就那麼重要嗎！",
  ui_story_5004_50042301_26_dialog_content = "嘖……",
  ui_story_5004_50042301_35_dialog_content = "嘿~咻，小拜里厄，妳先在床上躺一下吧~",
  ui_story_5004_50042301_36_dialog_content = "唔……額頭和身體都很燙……還在不停流汗……很難受嗎？",
  ui_story_5004_50042301_37_dialog_content = "我……我還好……",
  ui_story_5004_50042301_38_dialog_content = "那我先去拿條毛巾幫妳擦擦汗~！",
  ui_story_5004_50042301_39_dialog_content = "不用啦……那個。",
  ui_story_5004_50042301_40_dialog_content = "能稍微陪我躺一下嗎……？",
  ui_story_5004_50042301_41_dialog_content = "沒問題~",
  ui_story_5004_50042301_42_dialog_content = "小拜里厄的額頭還是好燙啊……真的不用拿條毛巾冷敷一下嗎？",
  ui_story_5004_50042301_43_dialog_content = "嗯……這樣就好……",
  ui_story_5004_50042301_44_dialog_content = "那明天參加完頒獎儀式之後，就拜託PlayerName用臨空者號載我們去白夜城吧。",
  ui_story_5004_50042301_45_dialog_content = "那邊的醫院也比較好照顧妳的病情。",
  ui_story_5004_50042301_46_dialog_content = "而且白夜城也有很多有趣的人喔，我可以把其他的天使介紹給小拜里厄。",
  ui_story_5004_50042301_47_dialog_content = "大家一定會很喜歡妳的。",
  ui_story_5004_50042301_48_dialog_content = "對了，還有一位叫烏列爾的天使，她也經常像是小拜里厄一樣沒什麼精神的樣子~",
  ui_story_5004_50042301_49_dialog_content = "但她也和你一樣，是非常可靠值得信賴的夥伴喔~",
  ui_story_5004_50042301_50_dialog_content = "我也是值得信賴的夥伴嗎……？",
  ui_story_5004_50042301_51_dialog_content = "沒錯沒錯~那邊還有很多漂亮精緻的商店，還有各種餐館。",
  ui_story_5004_50042301_52_dialog_content = "我可以帶妳去好好逛一下我平時喜歡去的店~",
  ui_story_5004_50042301_53_dialog_content = "如果妳喜歡烘焙的話，我們可以去我認識的一家麵包店~",
  ui_story_5004_50042301_54_dialog_content = "那家店老闆人很好，之前就教過我很多麵包點心的做法呢！",
  ui_story_5004_50042301_55_dialog_content = "對了還有白夜城的音樂廳，那邊經常會有很厲害的人表演。不過票有點難買啦~",
  ui_story_5004_50042301_56_dialog_content = "嗯……",
  ui_story_5004_50042301_57_dialog_content = "小拜里厄……？",
  ui_story_5004_50042301_58_dialog_content = "我有件事……一直猶豫著該不該告訴妳……",
  ui_story_5004_50042301_59_dialog_content = "告訴我嘛~告訴我嘛~",
  ui_story_5004_50042301_60_dialog_content = "我……我很害怕……",
  ui_story_5004_50042301_61_dialog_content = "我害怕自己……沒辦法離開這裡……",
  ui_story_5004_50042301_62_dialog_content = "嗄？為什麼？",
  ui_story_5004_50042301_63_dialog_content = "這段時間……我每天都在做夢……",
  ui_story_5004_50042301_64_dialog_content = "一個不斷重複……卻又愈來愈可怕的噩夢……",
  ui_story_5004_50042301_65_dialog_content = "一開始我只是在夢裡朦朧地聽到一個聲音……",
  ui_story_5004_50042301_66_dialog_content = "那個聲音不停地對我說話……讓我回想起很多自己都遺忘了的往事……",
  ui_story_5004_50042301_67_dialog_content = "（小拜里厄的往事……難道是戈蒂埃和皮洛斯家族的那些事……？）",
  ui_story_5004_50042301_68_dialog_content = "她說出了很多我不記得和不願意想起的事……讓我感到非常恐懼。",
  ui_story_5004_50042301_69_dialog_content = "最後那個聲音不斷和我說……",
  ui_story_5004_50042301_70_dialog_content = "我的身體將會崩壞並失控，在殺死所有人後，精神也將墜入無底的深淵。",
  ui_story_5004_50042301_71_dialog_content = "！！",
  ui_story_5004_50042301_72_dialog_content = "我很想努力忘掉那些夢……但它們一直縈繞在我腦海中……",
  ui_story_5004_50042301_73_dialog_content = "而且我確實感覺到……身體也在每況愈下……",
  ui_story_5004_50042301_74_dialog_content = "小拜里厄……",
  ui_story_5004_50042301_75_dialog_content = "那種夢裡的東西怎麼能相信啦！",
  ui_story_5004_50042301_76_dialog_content = "嘖……",
  ui_story_5004_50042301_77_dialog_content = "真是的，做夢就是做夢，怎麼可能代表什麼嘛。",
  ui_story_5004_50042301_78_dialog_content = "妳感覺身體不適也只是這兩天幫大家做各種事情，而且還有玩過頭了的原因吧！",
  ui_story_5004_50042301_79_dialog_content = "夢的話……我去找PlayerName，他的精神感應能力說不定會有幫助呢。",
  ui_story_5004_50042301_80_dialog_content = "妳先好好休息，我去找他！",
  ui_story_5004_50042301_81_dialog_content = "聽我的話，在這裡好好休息。明天我們就回白夜城~",
  ui_story_5004_50042301_82_dialog_content = "……嗯。",
  ui_story_5004_50042301_83_dialog_content = "我會馬上回來的，等我喔！",
  ui_story_5004_50042301_84_dialog_content = "好險……",
  ui_story_5004_50042301_85_dialog_content = "馬上回去……這可不行。",
  ui_story_5004_50042301_86_dialog_content = "什麼！是真的嗎？！",
  ui_story_5004_50042301_87_dialog_content = "當然，我還差點被她撞了一下。",
  ui_story_5004_50042301_88_dialog_content = "如果真是如此……我必須馬上告知「王后」。",
  ui_story_5004_50042301_89_dialog_content = "我貢獻了這麼重要的情報……這個月的業績是不是……？",
  ui_story_5004_50042301_90_dialog_content = "……你先回去。",
  ui_story_5004_50042301_91_dialog_content = "廢物！",
  ui_story_5004_50042301_92_dialog_content = "還、還請您息怒。",
  ui_story_5004_50042301_93_dialog_content = "我大費周章把所有的棋子擺入了棋盤，卻要因為你們這些傢伙的無能……",
  ui_story_5004_50042301_94_dialog_content = "就讓他們逃了嗎！！",
  ui_story_5004_50042301_95_dialog_content = "實在是非常抱歉！",
  ui_story_5004_50042301_96_dialog_content = "沒用的東西，看來還是需要我親自動手……",
  ui_story_5004_50042301_97_dialog_content = "可惜……這枚棋子，可是我最珍愛的一枚呀……",
  ui_story_5004_50042301_98_dialog_content = "咿嘻嘻嘻……",
  ui_story_5004_50042401_1_dialog_content = "PlayerName！跟我來一下。",
  ui_story_5004_50042401_2_dialog_content = "不要拉我，我正在和薇絲研究怎麼拓展刨冰攤的業務。",
  ui_story_5004_50042401_3_dialog_content = "明天就可以用獎金升級一下小攤，然後大展拳腳啦！",
  ui_story_5004_50042401_4_dialog_content = "別管那種事啦，小拜里厄的狀況現在很不妙！",
  ui_story_5004_50042401_5_dialog_content = "拜里厄她怎麼了？",
  ui_story_5004_50042401_6_dialog_content = "我感覺她的狀態，需要馬上回白夜城接受治療。",
  ui_story_5004_50042401_7_dialog_content = "PlayerName，我們的確該回去了。",
  ui_story_5004_50042401_8_dialog_content = "不能忘記來這裡的目的是為了讓拜里厄緩解心情。",
  ui_story_5004_50042401_9_dialog_content = "如果留在這裡反而讓拜里厄的狀態更差，那樣就本末倒置了。",
  ui_story_5004_50042401_10_dialog_content = "說的對！我們先去看看拜里厄的狀況怎麼辦吧！",
  ui_story_5004_50042401_11_dialog_content = "嗚！好痛……眼前一片漆黑……",
  ui_story_5004_50042401_12_dialog_content = "抱歉！波娜瑟妳沒事吧？",
  ui_story_5004_50042401_13_dialog_content = "對了，我們有事要馬上回白夜城，就先不領獎了！",
  ui_story_5004_50042401_14_dialog_content = "嗄？不領獎是什麼意思，等等呀！",
  ui_story_5004_50042401_15_dialog_content = "啊啊氣死了！怎麼在這種時候節外生枝嘛！",
  ui_story_5004_50042401_16_dialog_content = "我帶著大家來……",
  ui_story_5004_50042401_17_dialog_content = "啦……小拜里厄……？",
  ui_story_5004_50042401_18_dialog_content = "小拜里厄呢？跑哪去了？！",
  ui_story_5004_50042401_19_dialog_content = "不要再搖我了，又不是我把她偷走的。",
  ui_story_5004_50042401_20_dialog_content = "我明明告訴過她要乖乖休息！",
  ui_story_5004_50042401_21_dialog_content = "快想想辦法，她還在生病，到處亂跑很危險的！",
  ui_story_5004_50042401_22_dialog_content = "PlayerName！PlayerName！",
  ui_story_5004_50042401_23_dialog_content = "PlayerName，試著用感應能力幫拉斐爾試試吧。",
  ui_story_5004_50042401_24_dialog_content = "好啦好啦！這樣一直搖我會沒法認真感應啦！",
  ui_story_5004_50042401_25_dialog_content = "拉斐爾，先冷靜點，放開PlayerName吧。",
  ui_story_5004_50042401_26_dialog_content = "呼……",
  ui_story_5004_50042401_27_dialog_content = "不在飯店裡。",
  ui_story_5004_50042401_28_dialog_content = "不過還能捕捉到她的痕跡……",
  ui_story_5004_50042401_29_dialog_content = "好像是向著那座石雕所在的懸崖去了。",
  ui_story_5004_50042401_30_dialog_content = "PlayerName，快叫其他人也一起去幫忙找找拜里厄吧。",
  ui_story_5004_50042401_31_dialog_content = "要叫大家都一起來嗎？會不會太勞師動眾了？",
  ui_story_5004_50042401_32_dialog_content = "PlayerName看起來一副度假度傻了的樣子。",
  ui_story_5004_50042401_33_dialog_content = "飯店周邊是因為有安保措施才比較安全。",
  ui_story_5004_50042401_34_dialog_content = "你還記得來的路上遇到的大群暗鬼嗎？",
  ui_story_5004_50042401_35_dialog_content = "如果拜里厄再次不小心闖入類似的暗鬼聚集地怎麼辦？",
  ui_story_5004_50042401_36_dialog_content = "的確是這樣……",
  ui_story_5004_50042401_37_dialog_content = "好！那快去叫大家一起來幫忙找吧！",
  ui_story_5004_50042401_38_dialog_content = "謝謝妳們來幫忙，沒想到吉納維芙也會來。",
  ui_story_5004_50042401_39_dialog_content = "別這麼說，既然是朋友了，互相幫助就是應該的！",
  ui_story_5004_50042401_40_dialog_content = "這傢伙雖然性格有點惡劣，但其實也是個很熱心的人。",
  ui_story_5004_50042401_41_dialog_content = "嗄？什麼啊，我只是不想放過任何妳會出醜的機會才過來的！",
  ui_story_5004_50042401_42_dialog_content = "啊哈哈……總之希望沒打擾到妳們兩個敘舊，我們還是先趕快找拜里厄吧！",
  ui_story_5004_50042401_43_dialog_content = "PlayerName，是往這個方向走嗎？這座森林給人的感覺怪怪的……",
  ui_story_5004_50042401_44_dialog_content = "沒錯，拜里厄的確是走了這條路。",
  ui_story_5004_50042401_45_dialog_content = "但是……總覺得一直在這裡繞來繞去，而且氣氛也和白天時完全不同了。",
  ui_story_5004_50042401_46_dialog_content = "（這些路就像是看不到盡頭，四周還有不知道什麼動物的恐怖叫聲，有點嚇人……）",
  ui_story_5004_50042401_47_dialog_content = "等一下，好像有什麼聲音……",
  ui_story_5004_50042401_48_dialog_content = "嘎喔——",
  ui_story_5004_50042401_49_dialog_content = "哇！！",
  ui_story_5004_50042401_50_dialog_content = "波娜瑟？妳怎麼會在這裡？",
  ui_story_5004_50042401_51_dialog_content = "還不是你們突然說要走，我想盡快把<color=#FFB400>「終極大獎」</color>拿給諸位呀！",
  ui_story_5004_50042401_52_dialog_content = "倒是你們為什麼在這裡呢？",
  ui_story_5004_50042401_53_dialog_content = "難道是……回去之前還想來一場心跳撲通撲通的試膽大會~？",
  ui_story_5004_50042401_54_dialog_content = "那可不可以也讓我參加呀。",
  ui_story_5004_50042401_55_dialog_content = "才不是試膽大會啦！",
  ui_story_5004_50042401_56_dialog_content = "其實是拜里厄不見了。我們要回去的原因也是她的身體狀況在不斷惡化。",
  ui_story_5004_50042401_57_dialog_content = "拉斐爾很擔心她的病情繼續惡化，或者遇到暗鬼之類的。",
  ui_story_5004_50042401_58_dialog_content = "嗯……既然是拜里厄的事，那同為真理結社的人就更不能放著不管啦。",
  ui_story_5004_50042401_59_dialog_content = "不過這裡的確很危險，除了暗鬼之外還有更加恐怖、更加邪惡的存在喔！",
  ui_story_5004_50042401_60_dialog_content = "都說不是試膽了！就別繼續講這些奇奇怪怪的事情了！",
  ui_story_5004_50042401_61_dialog_content = "我能感應到拜里厄大概在山崖上面……而且已經停止移動了。",
  ui_story_5004_50042401_62_dialog_content = "但這個森林怎麼繞都走不出去……",
  ui_story_5004_50042401_63_dialog_content = "真沒辦法，既然是為了拜里厄就幫你指指路吧，大家跟上我。",
  ui_story_5004_50042401_64_dialog_content = "小拜里厄！！",
  ui_story_5004_50042401_65_dialog_content = "別過來……！",
  ui_story_5004_50042401_66_dialog_content = "那邊很危險！別再向前走了！",
  ui_story_5004_50042401_67_dialog_content = "我知道很危險……所以別過來……",
  ui_story_5004_50042401_68_dialog_content = "先冷靜點……拜里厄，妳為什麼要來這裡？",
  ui_story_5004_50042401_69_dialog_content = "我……我也不知道……",
  ui_story_5004_50042401_70_dialog_content = "拉斐爾離開之後……我依舊渾身沒力氣躺在床上……",
  ui_story_5004_50042401_71_dialog_content = "但是突然我發現自己動不了了……",
  ui_story_5004_50042401_72_dialog_content = "然後有一隻黑色的手……一圈一圈纏緊我的脖子，然後矇住了我的眼睛。",
  ui_story_5004_50042401_73_dialog_content = "接著我耳邊響起恐怖的狂笑……然後我就失去意識了……",
  ui_story_5004_50042401_74_dialog_content = "那個笑聲是妳之前說的，夢裡的那個人的聲音嗎？",
  ui_story_5004_50042401_75_dialog_content = "是……",
  ui_story_5004_50042401_76_dialog_content = "我不知道自己為什麼會在這裡……",
  ui_story_5004_50042401_77_dialog_content = "我也不知道自己會變成什麼樣子……",
  ui_story_5004_50042401_78_dialog_content = "如果真的像那個聲音所說的一樣……我會殺死重要的人……",
  ui_story_5004_50042401_79_dialog_content = "但那是噩夢吧！",
  ui_story_5004_50042401_80_dialog_content = "就算是噩夢！但我現在也被噩夢控制著來到這裡了呀！",
  ui_story_5004_50042401_81_dialog_content = "我不想再有任何重要的人死在我面前了！！",
  ui_story_5004_50042401_82_dialog_content = "別再說傻話了！",
  ui_story_5004_50042401_83_dialog_content = "……",
  ui_story_5004_50042401_84_dialog_content = "妳一定沒問題的！妳不是已經和大家一起成為沙灘勇者了嗎！",
  ui_story_5004_50042401_85_dialog_content = "（說、說這種話有用嗎……）",
  ui_story_5004_50042401_86_dialog_content = "拉斐爾……",
  ui_story_5004_50042401_87_dialog_content = "我們不是說好還要一起去白夜城嗎……",
  ui_story_5004_50042401_88_dialog_content = "等等……",
  ui_story_5004_50042401_89_dialog_content = "回來吧，那邊很危險的。",
  ui_story_5004_50042401_90_dialog_content = "喂喂，那些晶石閃個不停，看起來很不妙。",
  ui_story_5004_50042401_91_dialog_content = "小心！那些晶石要爆炸了！",
  ui_story_5004_50042401_92_dialog_content = "PlayerName，危險！",
  ui_story_5004_50042401_93_dialog_content = "小拜里厄！！",
  ui_story_5004_50042401_95_dialog_content = "……！！",
  ui_story_5004_50042401_96_dialog_content = "小拜里厄！！",
  ui_story_5004_50042401_97_dialog_content = "拉斐爾？！",
  ui_story_5004_50042401_98_dialog_content = "快抓住我的手！",
  ui_story_5004_50042401_99_dialog_content = "嗯……！",
  ui_story_5004_50042401_100_dialog_content = "抱歉……都是我的關係才……",
  ui_story_5004_50042401_101_dialog_content = "即使拉斐爾是衛隊的天使……從這種高度墜下也很難安然無恙吧。",
  ui_story_5004_50042401_102_dialog_content = "想和妳一起……去白夜城……",
  ui_story_5004_50042401_103_dialog_content = "<size=45>妳——說——什——麼——</size>",
  ui_story_5004_50042401_104_dialog_content = "一……一起逛街？",
  ui_story_5004_50042401_105_dialog_content = "<size=45>前——面——那——句——</size>",
  ui_story_5004_50042401_106_dialog_content = "拉斐爾這樣的天使也……？",
  ui_story_5004_50042401_107_dialog_content = "全彈發射……解除負載……力主祝福之架就緒……最大出力！！",
  ui_story_5004_50042401_108_dialog_content = "<size=45>小拜里厄——天使啊——可是會飛的喔——！</size>",
  ui_story_5004_50042401_109_dialog_content = "小拜里厄……！再抓緊一點，能量快要耗盡啦！",
  ui_story_5004_50042401_110_dialog_content = "放開我吧！拉斐爾！它根本沒辦法承受兩個人的重量，這樣下去我們兩個都會……",
  ui_story_5004_50042401_111_dialog_content = "不准再繼續說蠢話！",
  ui_story_5004_50042401_112_dialog_content = "我絕對、絕對不會放開的！",
  ui_story_5004_50042401_113_dialog_content = "<color=#e8d9bb>嘎吱嘎吱——</color>",
  ui_story_5004_50042401_114_dialog_content = "（快到極限了嗎？）",
  ui_story_5004_50042401_115_dialog_content = "<size=50><color=#e8d9bb>砰——</color></size>",
  ui_story_5004_50042401_116_dialog_content = "拉斐爾……拉斐爾快醒醒……",
  ui_story_5004_50042401_117_dialog_content = "小拜里厄……",
  ui_story_5004_50042401_118_dialog_content = "小拜里厄，妳沒事吧！",
  ui_story_5004_50042401_119_dialog_content = "我、我沒事……",
  ui_story_5004_50042401_120_dialog_content = "謝謝妳……",
  ui_story_5004_50042401_121_dialog_content = "沒事就好沒事就好，妳也辛苦啦。",
  ui_story_5004_50042401_123_dialog_content = "接下來只要在這裡等著PlayerName他們來接我們就好啦。",
  ui_story_5004_50042401_124_dialog_content = "等等……拉斐爾，那邊的是……？！",
  ui_story_5004_50042401_125_dialog_content = "吼！",
  ui_story_5004_50042401_126_dialog_content = "嘎……嘎……！！",
  ui_story_5004_50042401_127_dialog_content = "暗鬼……怎麼這麼多……",
  ui_story_5004_50042401_128_dialog_content = "小拜里厄！妳還能戰鬥嗎？",
  ui_story_5004_50042401_129_dialog_content = "嗯！",
  ui_story_5004_50042401_130_dialog_content = "（PlayerName……快點過來啊！）",
  ui_story_5004_50042501_1_dialog_content = "波娜瑟，帶我們走去崖底最近的路！",
  ui_story_5004_50042501_2_dialog_content = "知道啦，這邊這邊，跟緊一點，小心別被妖怪抓走喔。",
  ui_story_5004_50042501_2X1_dialog_content = "我們趕快把樂章弄到手，然後送到波娜瑟手上。",
  ui_story_5004_50042501_2X2_dialog_content = "必須由她把樂章交給空裔解除封印，再進行演奏，才能喚醒「寂靜君王」。",
  ui_story_5004_50042501_2X3_dialog_content = "哎，彭格格大人，我們大費周章潛入飯店，舉行潮汐祭並吸收那些光靈的能量。",
  ui_story_5004_50042501_2X4_dialog_content = "現在又要費盡心機讓空裔解除封印，再讓那個波娜瑟演奏樂章……",
  ui_story_5004_50042501_2X5_dialog_content = "這樣真的能喚醒那個什麼君王嗎？這樣對我們有什麼好處嗎？",
  ui_story_5004_50042501_2X6_dialog_content = "這是八罪靈中那位大人的命令……我聽說這位君王是實力非常強大的暗鬼。",
  ui_story_5004_50042501_2X7_dialog_content = "如果它能甦醒的話，我們一定能一舉收拾那些冥頑不靈的光靈。",
  ui_story_5004_50042501_2X8_dialog_content = "希望如此……這裡也太黑了，哎唷！你怎麼突然停下來了？",
  ui_story_5004_50042501_2X9_dialog_content = "外面有戰鬥的聲音……先躲起來！",
  ui_story_5004_50042501_3_dialog_content = "躲進這裡的話暫時應該不會被發現吧。",
  ui_story_5004_50042501_4_dialog_content = "沒想到能找到這樣一個山洞，不過好黑呀……",
  ui_story_5004_50042501_5_dialog_content = "嗷！！",
  ui_story_5004_50042501_6_dialog_content = "嗚！這些討厭的暗鬼怎麼沒完沒了的！",
  ui_story_5004_50042501_7_dialog_content = "小拜里厄，妳還可以嗎？",
  ui_story_5004_50042501_8_dialog_content = "呼……呼……我、我沒事……還能戰鬥……",
  ui_story_5004_50042501_10_dialog_content = "嘎嘎！！！",
  ui_story_5004_50042501_11_dialog_content = "吼！！！",
  ui_story_5004_50042501_12_dialog_content = "可惡，進來的路被堵住了！",
  ui_story_5004_50042501_13_dialog_content = "一群討厭的傢伙！！",
  ui_story_5004_50042501_14_dialog_content = "拉斐爾，拜里厄！",
  ui_story_5004_50042501_15_dialog_content = "妳們沒事吧！",
  ui_story_5004_50042501_16_dialog_content = "PlayerName，太慢啦！",
  ui_story_5004_50042501_17_dialog_content = "怎麼能讓淑女等這麼久！",
  ui_story_5004_50042501_18_dialog_content = "抱歉啦，一起給這群暗鬼一點顏色瞧瞧吧！！",
  ui_story_5004_50042601_1_dialog_content = "呼，總算結束了。",
  ui_story_5004_50042601_2_dialog_content = "拉斐爾和拜里厄還好吧，受傷嚴重嗎？",
  ui_story_5004_50042601_3_dialog_content = "當然沒事喔，有我在小拜里厄身邊，不會讓她受傷的！",
  ui_story_5004_50042601_4_dialog_content = "嗯……有拉斐爾保護我……",
  ui_story_5004_50042601_5_dialog_content = "既然大家都沒事，那我們就先回飯店吧。",
  ui_story_5004_50042601_6_dialog_content = "拜里厄夢裡的事，我、拉斐爾，還有巨像上的其他光靈，大家一定會幫忙想辦法解決的。",
  ui_story_5004_50042601_7_dialog_content = "沒錯沒錯，妳的吉納維芙姐姐很有門路的，她一定能幫妳。",
  ui_story_5004_50042601_8_dialog_content = "嗄？幹嘛突然就推給我了，我只是看在大家相識一場，幫忙打個架。",
  ui_story_5004_50042601_9_dialog_content = "嘖，好吧，我認識個對各類礦物很有研究的傢伙，回去問問他。",
  ui_story_5004_50042601_10_dialog_content = "那我們就快回飯店吧，然後馬上回白夜城。",
  ui_story_5004_50042601_11_dialog_content = "波娜瑟，麻煩妳再帶一下路。",
  ui_story_5004_50042601_12_dialog_content = "波娜瑟？",
  ui_story_5004_50042601_13_dialog_content = "稍等一下，我找到一個可以按的東西。",
  ui_story_5004_50042601_14_dialog_content = "嘿。",
  ui_story_5004_50042601_15_dialog_content = "好刺眼……這是哪裡？",
  ui_story_5004_50042601_16_dialog_content = "（這周圍的一切為什麼看起來這麼熟悉，是我的錯覺嗎？）",
  ui_story_5004_50042601_17_dialog_content = "PlayerName，不好了，我們進來時候的路被封死了。",
  ui_story_5004_50042601_18_dialog_content = "什麼？",
  ui_story_5004_50042601_19_dialog_content = "不行，推不開。",
  ui_story_5004_50042601_20_dialog_content = "設施……封鎖……<size=35>請重新……</size><size=33>系統……</size>",
  ui_story_5004_50042601_21_dialog_content = "……？",
  ui_story_5004_50042601_22_dialog_content = "大家幫忙試試，看能不能弄開這扇門！",
  ui_story_5004_50042601_23_dialog_content = "還是不行，完全紋絲不動，攻擊也無效。",
  ui_story_5004_50042601_24_dialog_content = "PlayerName，你有沒有感覺這裡很像是巨像的內部……？",
  ui_story_5004_50042601_25_dialog_content = "確實有一點，但怎麼可能呢……對了，波娜瑟呢？她哪去了？",
  ui_story_5004_50042601_26_dialog_content = "哪去了~哪去了哪去了~",
  ui_story_5004_50042601_27_dialog_content = "我的心~我的愛~我的一切和夢~",
  ui_story_5004_50042601_28_dialog_content = "究竟被這些討厭的暗鬼藏到哪去了~",
  ui_story_5004_50042601_29_dialog_content = "啊！<size=45>找到寶物了！</size>",
  ui_story_5004_50042601_29X1_dialog_content = "嗯？你們兩個怎麼在這裡？",
  ui_story_5004_50042601_29X2_dialog_content = "噓……！別被外面的光靈聽到了",
  ui_story_5004_50042601_29X3_dialog_content = "我們是準備直接取走樂章送到妳手上。",
  ui_story_5004_50042601_29X4_dialog_content = "喔？這麼說來，這個裡面就是樂章嗎？",
  ui_story_5004_50042601_29X5_dialog_content = "是的，妳記得一定要讓空裔……",
  ui_story_5004_50042601_29X6_dialog_content = "知道知道，讓空裔解除封印，我記得很清楚。",
  ui_story_5004_50042601_29X7_dialog_content = "那樂章的下半部也到手了……你們兩個，就先休息一會吧……",
  ui_story_5004_50042601_29X8_dialog_content = "！小心！彭格格大人！！",
  ui_story_5004_50042601_29X9_dialog_content = "<color=#e8d9bb>轟——轟——</color>",
  ui_story_5004_50042601_29X10_dialog_content = "再拖到看不見的角落……嘿……！完美！",
  ui_story_5004_50042601_30_dialog_content = "<size=45>PlayerName~你們還在嗎？</size>",
  ui_story_5004_50042601_31_dialog_content = "門都鎖死了能去哪啊！妳跑哪去了？",
  ui_story_5004_50042601_32_dialog_content = "你先來我這邊看看，這有個<color=#FFB400>有趣的東西</color>——",
  ui_story_5004_50042601_33_dialog_content = "這是什麼？",
  ui_story_5004_50042601_34_dialog_content = "這個感覺……是<color=#FFB400>空裔的造物</color>？",
  ui_story_5004_50042601_35_dialog_content = "果然是吧，我就猜你會認得這個東西。",
  ui_story_5004_50042601_36_dialog_content = "既然這裡有空裔的造物，這地方又這麼像巨像內部……所以我們難道是在某個巨像裡？",
  ui_story_5004_50042601_37_dialog_content = "哎~這種事人家哪裡知道呀，我只是個普通的音樂家兼主持人嘛。",
  ui_story_5004_50042601_38_dialog_content = "我等……子嗣……",
  ui_story_5004_50042601_39_dialog_content = "（又來了……）",
  ui_story_5004_50042601_40_dialog_content = "PlayerName~要不要試著來感應看看？",
  ui_story_5004_50042601_41_dialog_content = "PlayerName，我有不太好的預感。",
  ui_story_5004_50042601_42_dialog_content = "但我們已經被困在這裡了……除了試試看也沒其他辦法了吧？",
  ui_story_5004_50042601_43_dialog_content = "嗯……那你小心點。",
  ui_story_5004_50042601_44_dialog_content = "我等的……子嗣啊……",
  ui_story_5004_50042601_45_dialog_content = "執意拿走<color=#FFB400>「樂章」</color>……就必須……它……",
  ui_story_5004_50042601_46_dialog_content = "不可讓其喚回……",
  ui_story_5004_50042601_47_dialog_content = "不可再讓……淹沒大地……",
  ui_story_5004_50042601_48_dialog_content = "喂！門開了！",
  ui_story_5004_50042701_49_dialog_content = "多虧你們找到開關，那道破門踢得我腿都酸了。",
  ui_story_5004_50042701_50_dialog_content = "波娜瑟，妳從箱子裡拿了個什麼出來？",
  ui_story_5004_50042701_51_dialog_content = "妳手裡那東西，是某種「樂章」嗎？",
  ui_story_5004_50042701_52_dialog_content = "嗯？PlayerName居然認識嗎？這個就是我一直在追尋的「神鳴樂章」之一喔。",
  ui_story_5004_50042701_53_dialog_content = "（果然剛剛聽到的聲音……就是在指這個東西。）",
  ui_story_5004_50042701_54_dialog_content = "為什麼妳知道「樂章」在那裡，還有那些暗鬼是哪來的？",
  ui_story_5004_50042701_55_dialog_content = "他們很明顯就是在保護那個「樂章」吧。",
  ui_story_5004_50042701_56_dialog_content = "哎，真是的，空裔也太敏銳了吧。",
  ui_story_5004_50042701_57_dialog_content = "沒錯，我是和暗鬼做了點小小的交易啦。",
  ui_story_5004_50042701_58_dialog_content = "妳居然和暗鬼做交易？！",
  ui_story_5004_50042701_59_dialog_content = "那又怎麼樣，又不是合作，我也沒幫他們做什麼壞事。",
  ui_story_5004_50042701_60_dialog_content = "他們把我需要的樂譜給我，我幫忙主持完成潮汐祭的比賽。",
  ui_story_5004_50042701_61_dialog_content = "主持潮汐祭……所以潮汐祭裡也有暗鬼的陰謀？",
  ui_story_5004_50042701_62_dialog_content = "那我就不知道了，對我來說聽從腦海裡的囈語和拿到樂章，比什麼都重要啦。",
  ui_story_5004_50042701_63_dialog_content = "……妳簡直就像是什麼瘋狂音樂……不對，妳就是！",
  ui_story_5004_50042701_64_dialog_content = "那既然拿到了，接下來妳有什麼打算？還要和暗鬼合作嗎？",
  ui_story_5004_50042701_65_dialog_content = "都說不是合作了！只是利用一下，我還準備把它送給PlayerName呢。",
  ui_story_5004_50042701_66_dialog_content = "送給我？妳這麼大費周章拿到的東西，就直接給我嗎？",
  ui_story_5004_50042701_67_dialog_content = "這個本來就是潮汐祭的<color=#FFB400>「終極大獎」</color>啦。",
  ui_story_5004_50042701_68_dialog_content = "而且我確實對你們有所隱瞞，所以這就當做是我的補償啦，不過我要先演奏過才能給你。",
  ui_story_5004_50042701_69_dialog_content = "聽起來就像是……大家大費周折摘得的美味果實卻先要給妳品嚐。",
  ui_story_5004_50042701_70_dialog_content = "嘿嘿，大家不都是夥伴嘛，來看著——",
  ui_story_5004_50042701_71_dialog_content = "嗯？居然還有完全相同的另一個嗎！",
  ui_story_5004_50042701_72_dialog_content = "當然啦，這兩個要結合在一起才是完整的樂章。",
  ui_story_5004_50042701_73_dialog_content = "嗯……？",
  ui_story_5004_50042701_74_dialog_content = "……這樣就結束了嗎？就這樣閃一下嗎？",
  ui_story_5004_50042701_75_dialog_content = "怎麼回事……？",
  ui_story_5004_50042701_76_dialog_content = "能感覺到裡面蘊含著某種能量……但是被限制住了。",
  ui_story_5004_50042701_77_dialog_content = "（果然還是不行嗎……就只能照<color=#FFB400>那個倉鼠</color>說的試試了。 ）",
  ui_story_5004_50042701_78_dialog_content = "PlayerName你來試試嘛！對著它感應一下就好！",
  ui_story_5004_50042701_79_option_content = "不行。",
  ui_story_5004_50042701_80_dialog_content = "我不想碰和暗鬼交易得來的東西！",
  ui_story_5004_50042701_81_dialog_content = "好啦好啦我發誓，就這一次！再也不會和暗鬼做交易了！",
  ui_story_5004_50042701_82_option_content = "既然交給我的話……",
  ui_story_5004_50042701_83_dialog_content = "還是不行！",
  ui_story_5004_50042701_84_dialog_content = "我的直覺告訴我這個東西很危險！",
  ui_story_5004_50042701_85_dialog_content = "大家都在這裡會有什麼危險嘛，拜託啦！",
  ui_story_5004_50042701_86_option_content = "好吧，那我試試看。",
  ui_story_5004_50042701_87_dialog_content = "但是我剛剛聽到，有個聲音要我不要隨便解開封印。",
  ui_story_5004_50042701_88_dialog_content = "你一定是聽錯啦，求求你！",
  ui_story_5004_50042701_89_dialog_content = "那妳發誓以後再也不和暗鬼做交易。",
  ui_story_5004_50042701_90_dialog_content = "好啦好啦我發誓，再也不會了！",
  ui_story_5004_50042701_91_dialog_content = "……",
  ui_story_5004_50042701_92_option_content = "（嘗試感應）",
  ui_story_5004_50042701_93_dialog_content = "成功了嗎……？",
  ui_story_5004_50042701_94_dialog_content = "……太棒了。",
  ui_story_5004_50042701_95_dialog_content = "謝謝你……PlayerName……",
  ui_story_5004_50042701_96_dialog_content = "波娜瑟……！妳要做什麼？！",
  ui_story_5004_50042701_97_dialog_content = "啊啊……這是多麼美妙的……光是解除封印，我就能感覺到它的呼喚……",
  ui_story_5004_50042701_98_dialog_content = "抱歉了……PlayerName……",
  ui_story_5004_50042701_99_dialog_content = "我在這裡的意義……我存在的意義……就是為了在這一刻奏響神鳴之樂！",
  ui_story_5004_50042701_100_dialog_content = "這是什麼……這種不祥的力量氣息！",
  ui_story_5004_50042701_101_dialog_content = "波娜瑟！！",
  ui_story_5004_50042701_102_dialog_content = "哈哈哈哈哈！",
  ui_story_5004_50042701_103_dialog_content = "如此！如此美妙的旋律，簡直太美好了！",
  ui_story_5004_50042701_104_dialog_content = "不行……使不出力氣……",
  ui_story_5004_50042701_105_dialog_content = "大家不要聽演奏的聲音！",
  ui_story_5004_50042701_106_dialog_content = "快點住手！波娜瑟！",
  ui_story_5004_50042701_107_dialog_content = "蒐集虛空樂章是囈語賦予我最崇高的使命。",
  ui_story_5004_50042701_108_dialog_content = "居然在這種時候叫人家放棄，也太離譜了吧~",
  ui_story_5004_50042701_112_dialog_content = "這是波娜瑟的力量嗎……不對，是她面前的樂章不斷湧出的力量！",
  ui_story_5004_50042701_113_dialog_content = "喂……！你們看那邊！！",
  ui_story_5004_50042701_114_dialog_content = "那是什麼……海中升起了……一座城堡！？",
  ui_story_5004_50042701_115_dialog_content = "那個城堡……怎麼可能……",
  ui_story_5004_50042701_116_dialog_content = "妳聽到了嗎，PlayerName，這空靈震神的旋律。",
  ui_story_5004_50042701_117_dialog_content = "果然空裔還是很有品味嘛，知道要把如此美妙動人的聲音據為己有，而不是留給庸俗的世間。",
  ui_story_5004_50042701_118_dialog_content = "做得非常好啊！我愈來愈欣賞你們空裔了——",
  ui_story_5004_50042701_119_dialog_content = "這就是真理的聲音，這就是神鳴的聲音。",
  ui_story_5004_50042701_120_dialog_content = "PlayerName，它們一直在我腦海裡轟響著呀！",
  ui_story_5004_50042701_121_dialog_content = "小拜里厄，PlayerName，別發呆了。波娜瑟頭上好像還有些什麼閃光的東西！",
  ui_story_5004_50042701_122_dialog_content = "是隕石！在快速地朝我們衝過來！",
  ui_story_5004_50042701_123_dialog_content = "隕石？為什麼會有隕石啊？！",
  ui_story_5004_50042701_124_dialog_content = "馬上要砸過來了，大家小心！",
  ui_story_5004_50042701_125_dialog_content = "血晶！！",
  ui_story_5004_50042701_126_dialog_content = "唔！",
  ui_story_5004_50042701_127_dialog_content = "沒事吧！",
  ui_story_5004_50042701_128_dialog_content = "還好，只是被激起的海浪沖倒了，多虧有拜里厄……",
  ui_story_5004_50042701_129_dialog_content = "更大顆的隕石過來了！",
  ui_story_5004_50042701_130_dialog_content = "我……我會拼盡全力的。",
  ui_story_5004_50042701_131_dialog_content = "（可惡……就算我們聯手，那種尺寸的隕石也根本不是我們能對付的……）",
  ui_story_5004_50042701_132_dialog_content = "難道真的要……",
  ui_story_5004_50042701_133_dialog_content = "不可以放棄這麼早啊，PlayerName先生——",
  ui_story_5004_50042701_134_dialog_content = "這個聲音！",
  ui_story_5004_50042701_135_dialog_content = "沒錯！就是您忠誠的機械之友，和他的摯友黑潮回來了！",
  ui_story_5004_50042701_136_dialog_content = "PlayerName，來好好欣賞「紅油動力-激鋼ν零號機」的威力吧！！",
  ui_story_5004_50042701_137_dialog_content = "喔喔喔喔喔喔！",
  ui_story_5004_50042701_138_dialog_content = "別喊了，好吵！你比平時擺弄機械時瘋了一百倍！！",
  ui_story_5004_50042701_139_dialog_content = "出力再拉高一點，再高一點它也行的！！",
  ui_story_5004_50042701_140_dialog_content = "嗄？？你說拉高是拉哪個啊？不管了，我全都拉下去！！",
  ui_story_5004_50042701_141_dialog_content = "沒錯就是這樣！點燃我的生命吧！！",
  ui_story_5004_50042701_142_dialog_content = "喂喂，你這個燈一直亮個不停是什麼意思？",
  ui_story_5004_50042701_143_dialog_content = "那個是超負荷警報！",
  ui_story_5004_50042701_144_dialog_content = "會怎麼樣啊？！",
  ui_story_5004_50042701_145_dialog_content = "還有不到三十秒就會爆炸了！",
  ui_story_5004_50042701_146_dialog_content = "紅油動力-激鋼ν，和我一起燃燒到最後吧！！！",
  ui_story_5004_50042701_147_dialog_content = "把隕石推離軌道！",
  ui_story_5004_50042701_148_dialog_content = "不用硬推回天上！！",
  ui_story_5004_50042701_149_dialog_content = "弗勞爾！",
  ui_story_5004_50042701_150_dialog_content = "明白了！！",
  ui_story_5004_50042701_151_dialog_content = "你這個破隕石——\n給我從這裡<size=45>滾出去！！！</size>",
  ui_story_5004_50042701_152_dialog_content = "（推進器的火光好刺眼！）",
  ui_story_5004_50042701_153_dialog_content = "成功了PlayerName！隕石已經在偏離墜下的軌道了！",
  ui_story_5004_50042701_154_dialog_content = "真的沒問題嗎！從我對機器人的瞭解來說，它好像快過載解體了的樣子！",
  ui_story_5004_50042701_157_dialog_content = "PlayerName，別愣著了，快點遠離海邊！",
  ui_story_5004_50042701_158_dialog_content = "浪馬上就要打過來了！！",
  ui_story_5004_50042701_159_dialog_content = "可惡！被波娜瑟弄得腿還在發軟！",
  ui_story_5004_50042701_160_dialog_content = "PlayerName，來抓著我的手！",
  ui_story_5004_50042701_161_dialog_content = "不行——趕不上了！",
  ui_story_5004_50042701_162_dialog_content = "PlayerName！你們沒事吧。",
  ui_story_5004_50042701_163_dialog_content = "這……這就是你說結合了空裔技術的……？",
  ui_story_5004_50042701_164_dialog_content = "沒錯！這就是結合了空裔技術所打造的最強機器人！",
  ui_story_5004_50042701_165_dialog_content = "不過可惜的是，空裔技術的部分已經在剛剛推開隕石的過程中嚴重損耗了。",
  ui_story_5004_50042701_166_dialog_content = "看來就是那幾具非常不合理的推進器吧……",
  ui_story_5004_50042701_167_dialog_content = "看來不管是啟光還是白夜城的人，今天都欠了黑潮大人一個人情啊！",
  ui_story_5004_50042701_168_dialog_content = "下次紅油扳手選老大的時候記得來投我一票，聽到了沒！哈哈哈哈哈！",
  ui_story_5004_50042701_169_dialog_content = "黑潮這傢伙……算了，波娜瑟人呢？",
  ui_story_5004_50042701_170_dialog_content = "哈~神清氣爽！感覺太棒了！",
  ui_story_5004_50042701_171_dialog_content = "哇！妳又是從哪冒出來的！",
  ui_story_5004_50042701_172_dialog_content = "我一直在旁邊呢，剛剛巨浪來襲的時候我還跟著你們一起跑了半天。只是你們沒注意而已吧。",
  ui_story_5004_50042701_173_dialog_content = "來，樂章接好。",
  ui_story_5004_50042701_174_dialog_content = "嗄？就這麼簡單交給我了？妳又有什麼陰謀……",
  ui_story_5004_50042701_175_dialog_content = "沒有什麼陰謀啦，畢竟我的目的也只是想演奏樂章而已。",
  ui_story_5004_50042701_176_dialog_content = "而且演奏過一次就已經刻在我的靈魂裡了，留著這個容器對我也沒什麼用。",
  ui_story_5004_50042701_177_dialog_content = "既然是空裔的東西，也理應交給你保管呀。",
  ui_story_5004_50042701_178_dialog_content = "放心吧~我不會再演奏的，所以就原諒我吧，嘿嘿~",
  ui_story_5004_50042701_179_dialog_content = "（這傢伙就打算這麼蒙混過關嗎……？）",
  ui_story_5004_50042701_180_dialog_content = "這麼危險的東西我們必須妥善保存起來。",
  ui_story_5004_50042701_181_dialog_content = "如果放任不管的話，一定會被別有用心人利用。",
  ui_story_5004_50042701_182_dialog_content = "有道理……那我就收下了，但這不代表妳欺騙我們的事就算了！",
  ui_story_5004_50042701_183_dialog_content = "妳要一五一十把和暗鬼的交易給我說清楚！",
  ui_story_5004_50042801_E1_dialog_content = "事情就是那樣啦，我發誓已經把自己知道的全部告訴你了！",
  ui_story_5004_50042801_E2_dialog_content = "嗯……所以妳就真的只是為了得到樂章，協助它們舉辦潮汐祭而已？",
  ui_story_5004_50042801_E3_dialog_content = "真的！真的是真的！",
  ui_story_5004_50042801_E4_dialog_content = "好吧……",
  ui_story_5004_50042801_E5_dialog_content = "終於……我的王，您開始甦醒了……",
  ui_story_5004_50042801_E6_dialog_content = "……什麼？您想親自見一見那些喚醒您的「勇士」嗎？",
  ui_story_5004_50042801_E7_dialog_content = "等等，你們有聽到什麼聲音嗎……？好像在耳邊若有似無的……",
  ui_story_5004_50042801_E8_dialog_content = "好的……好的……嘻嘻嘻……我想他們一定也迫不及待的想見到您了呢……",
  ui_story_5004_50042801_E9_dialog_content = "不過您的力量還沒完全恢復……請讓我助您一臂之力……",
  ui_story_5004_50042801_E10_dialog_content = "聲音？好像腦袋裡還是轟隆隆演奏聲……暗能好像突然變得更濃了？",
  ui_story_5004_50042801_E11_dialog_content = "突然如此濃厚的暗能……是從哪裡來的？剛剛居然完全沒察覺？！",
  ui_story_5004_50042801_E12_dialog_content = "<color=#e8d9bb>「樂章奏響，尋覓的終點已至，王亦甦醒，只為點燃繁星，賜予眾生災厄和憤怒。」</color>",
  ui_story_5004_50042801_E13_dialog_content = "……",
  ui_story_5004_50042801_184_dialog_content = "吼——！",
  ui_story_5004_50042801_185_dialog_content = "是剛剛戰鬥中逃掉的暗鬼嗎！",
  ui_story_5004_50042801_186_dialog_content = "不對……這些傢伙是……！",
  ui_story_5004_50042802_1_dialog_content = "好強……它們和普通的暗鬼不一樣。",
  ui_story_5004_50042802_2_dialog_content = "它們是從哪裡來的？以前從來沒見過這種傢伙。",
  ui_story_5004_50042802_3_dialog_content = "不過好在已經擊敗了，它們也沒辦法為非作歹啦。",
  ui_story_5004_50042802_4_dialog_content = "……不，應該只是分身。",
  ui_story_5004_50042802_5_dialog_content = "在剛剛的戰鬥中我感覺到了，有一股更強大的力量在控制著這些分身。",
  ui_story_5004_50042802_6_dialog_content = "那個力量的來源……就在那座「城堡」。",
  ui_story_5004_50042802_7_dialog_content = "（剛剛被一連串的事件吸引了注意力，差點忘了那座造型誇張的城堡。）",
  ui_story_5004_50042802_8_dialog_content = "（但現在我能明顯感覺到……它正在釋出愈來愈多恐怖的龐大暗能。）",
  ui_story_5004_50042802_9_dialog_content = "嘖……是那群暗鬼搞的鬼嗎？被那些傢伙給耍了……",
  ui_story_5004_50042802_10_dialog_content = "怪不得輕易就把樂章給我……是想利用我和PlayerName的力量召喚出那種東西嗎？",
  ui_story_5004_50042802_11_dialog_content = "那個小倉鼠的目的不只是開展潮汐祭來斂財，沒想到居然還有這種陰謀！",
  ui_story_5004_50042802_12_dialog_content = "果然應該直接把它們揍趴搶走樂章就好了。",
  ui_story_5004_50042802_13_dialog_content = "還有斂財這種設定嗎！暗鬼要錢做什麼用？！",
  ui_story_5004_50042802_14_dialog_content = "說是要把光靈的錢都賺走讓他們變成窮人，從而被工作支配，變得再也無法反抗什麼的……",
  ui_story_5004_50042802_15_dialog_content = "我的注意力都在樂章上，其他的事沒有很在意啦。",
  ui_story_5004_50042802_16_dialog_content = "PlayerName，我們應該去那座城堡裡弄清楚敵人的情況。",
  ui_story_5004_50042802_17_dialog_content = "卡蓮說的對。如果放任不管的話，海灘的大家都可能會遇到危險。甚至會釀成更大的危機。",
  ui_story_5004_50042802_18_dialog_content = "來都來了，怎麼能被那些暗鬼嚇跑。",
  ui_story_5004_50042802_19_dialog_content = "不過就只是區區暗鬼，逐個綁起來丟去換賞金就行了。",
  ui_story_5004_50042802_20_dialog_content = "嗯……我想和大家一起……那座城堡讓我非常在意……",
  ui_story_5004_50042802_21_dialog_content = "既然小拜里厄去的話，我也一起去~",
  ui_story_5004_50042802_22_dialog_content = "看我幹嘛，保護海灘的安全本來就是保全的職責吧。",
  ui_story_5004_50042802_23_dialog_content = "那就用紅油動力激鋼ν零號機送大家過去吧！",
  ui_story_5004_50042802_24_dialog_content = "真沒辦法，那我也負起責任，用珍藏的零件和能源幫你的機器人補給一下吧。",
  ui_story_5004_50042802_25_dialog_content = "然後大家一起過去狠狠收拾一下這群膽敢利用我的暗鬼！",
  ui_story_5004_50042802_26_dialog_content = "好，那我們準備出發！",
  ui_story_5004_50042901_1_dialog_content = "弗勞爾，你的ν機鋼還撐得住嗎？",
  ui_story_5004_50042901_2_dialog_content = "是「紅油動力激鋼ν零號機」！",
  ui_story_5004_50042901_3_dialog_content = "它可是借用了巨像的噴射科技，剛剛還用波娜瑟小姐提供的能源補給過了！",
  ui_story_5004_50042901_4_dialog_content = "（看來她鐵了心要找利用她的暗鬼算帳啊……）",
  ui_story_5004_50042901_5_dialog_content = "等等！巨像的技術……那會不會和臨空者一樣突然失去動力？！",
  ui_story_5004_50042901_6_dialog_content = "弗勞爾！小心點，別飛太高了！",
  ui_story_5004_50042901_7_dialog_content = "欸？為什麼！",
  ui_story_5004_50042901_8_dialog_content = "嗯？！",
  ui_story_5004_50042901_9_dialog_content = "喂喂！這怎麼回事？儀表板上的數值都在上限和下限之間跳個不停？！",
  ui_story_5004_50042901_10_dialog_content = "怎麼了弗勞爾！",
  ui_story_5004_50042901_11_dialog_content = "沒、沒事啦，啊哈哈……只不過是儀表板上的數值好像出了點問題？",
  ui_story_5004_50042901_12_dialog_content = "真的只是儀表板嗎？！",
  ui_story_5004_50042901_13_dialog_content = "好像在下墜吧！這個破銅爛鐵果然不可靠！",
  ui_story_5004_50042901_14_dialog_content = "我的紅油動力激鋼ν零號機永不墜落！",
  ui_story_5004_50042901_15_dialog_content = "真的在墜落了！真的啊！快想想辦法！！",
  ui_story_5004_50042901_16_dialog_content = "我們垂直滑翔到城堡上！大家抓緊！",
  ui_story_5004_50042901_17_dialog_content = "垂直滑翔個屁，明明就是墜……",
  ui_story_5004_50042901_18_dialog_content = "冷靜！絕對沒問題的！以我們紅油扳手的科學技術！",
  ui_story_5004_50042901_19_dialog_content = "<color=#e8d9bb>……</color>",
  ui_story_5004_50042901_20_dialog_content = "PlayerName。",
  ui_story_5004_50042901_21_dialog_content = "快醒醒，PlayerName。",
  ui_story_5004_50042901_22_dialog_content = "唔，頭好痛。",
  ui_story_5004_50042901_23_dialog_content = "薇絲？",
  ui_story_5004_50042901_24_dialog_content = "你終於醒啦，也暈過去太久了吧。",
  ui_story_5004_50042901_25_dialog_content = "這是哪……我們不是墜落到城堡裡了嗎？",
  ui_story_5004_50042901_26_dialog_content = "我們也不知道，但是這裡看起來非常……不正常，暗能濃到讓人喘不過氣。",
  ui_story_5004_50042901_27_dialog_content = "而且你看那些到處漂浮著的馬賽克，它們好像有生命一樣，每一幅都有不同的運動……",
  ui_story_5004_50042901_28_dialog_content = "你們看那個眼球的馬賽克。",
  ui_story_5004_50042901_29_dialog_content = "眼球好像轉了一圈又死死地盯住我們……真讓人不舒服……",
  ui_story_5004_50042901_30_dialog_content = "小拜里厄，妳看那邊的馬賽克。那兩隻手臂是在用檸檬做拋接遊戲嗎？",
  ui_story_5004_50042901_31_dialog_content = "好像真的是……",
  ui_story_5004_50042901_32_dialog_content = "PlayerName，看遠處的那個！",
  ui_story_5004_50042901_33_dialog_content = "是臨空者？！為什麼會出現在這裡？",
  ui_story_5004_50042901_34_dialog_content = "我要過去看看。",
  ui_story_5004_50042901_35_dialog_content = "這是？石板怎麼會自動出現在腳下？",
  ui_story_5004_50042901_36_dialog_content = "臨空者？是你嗎？",
  ui_story_5004_50042901_37_dialog_content = "可惡，怎麼走都接近不了。",
  ui_story_5004_50042901_38_dialog_content = "PlayerName，別走那麼快。",
  ui_story_5004_50042901_39_dialog_content = "在這種地方貿然行動很危險。",
  ui_story_5004_50042901_40_dialog_content = "好吧……妳們有什麼頭緒嗎？",
  ui_story_5004_50042901_41_dialog_content = "回想一下，我們墜落到了「城堡」裡，接著就暈過去了。",
  ui_story_5004_50042901_42_dialog_content = "醒來的時候就在這裡，這一定不是城堡內部……應該是什麼特殊的空間。",
  ui_story_5004_50042901_43_dialog_content = "嘖，真麻煩。本來以為打一架就能回去的。",
  ui_story_5004_50042901_44_dialog_content = "結果現在被困在這裡，連怎麼出去都不知道。",
  ui_story_5004_50042901_45_dialog_content = "看起來也不像有其他樂章。",
  ui_story_5004_50042901_46_dialog_content = "……",
  ui_story_5004_50042901_47_dialog_content = "小拜里厄……妳還可以嗎？來搭著我的肩膀吧。",
  ui_story_5004_50042901_48_dialog_content = "嗯……我沒關係，謝謝妳……",
  ui_story_5004_50042901_49_dialog_content = "其實我有件事要坦白……",
  ui_story_5004_50042901_50_dialog_content = "還記得嗎？我之前用沙子堆成的城堡……",
  ui_story_5004_50042901_51_dialog_content = "對了！那個城堡，和這裡非常相似呢！",
  ui_story_5004_50042901_52_dialog_content = "難道小拜里厄知道些什麼嗎？",
  ui_story_5004_50042901_53_dialog_content = "不知道……但這座建築也一直印在我的腦海裡。",
  ui_story_5004_50042901_54_dialog_content = "所以我猜測那個同樣在我腦海裡的聲音……可能和這裡有關。",
  ui_story_5004_50042901_55_dialog_content = "大家一定要小心……這裡不只有暗能……還存在著某種讓我感覺十分熟悉的力量……",
  ui_story_5004_50042901_56_dialog_content = "放心吧小姑娘，有我們在沒人能傷到妳。",
  ui_story_5004_50042901_57_dialog_content = "聘請我當貼身護衛的費用可以之後再算，可以給妳打個折扣。",
  ui_story_5004_50042901_58_dialog_content = "欸，張嘴閉嘴都是生意，小吉妳這樣可不像是個貴族。",
  ui_story_5004_50042901_59_dialog_content = "妳閉嘴，我這是在紓緩氣氛。",
  ui_story_5004_50042901_60_dialog_content = "只有團結一致才能打敗暗鬼，妳這種孤僻的傢伙才不懂。",
  ui_story_5004_50042901_61_dialog_content = "沒錯，我們大家一起來到這裡，就是為了戰勝那些暗鬼。",
  ui_story_5004_50042901_62_dialog_content = "雖然暫時被困在這個奇怪的空間裡了，但不能在這個時候退縮！",
  ui_story_5004_50042901_63_dialog_content = "嗯……！",
  ui_story_5004_50042901_64_dialog_content = "總之再試著探索一下這附近吧……雖然什麼都看不清楚。",
  ui_story_5004_50042901_65_dialog_content = "我們先嘗試著朝一個方向走走看。",
  ui_story_5004_50042901_66_dialog_content = "嗯，小心點。",
  ui_story_5004_50042901_67_dialog_content = "四周的景色看不出什麼變化……",
  ui_story_5004_50042901_68_dialog_content = "而且不光是臨空者，這裡的其他馬賽克看起來都有點熟悉。",
  ui_story_5004_50042901_69_dialog_content = "那好像是白夜城的尖碑……",
  ui_story_5004_50042901_70_dialog_content = "還有那位女性的馬賽克……難道是！",
  ui_story_5004_50042901_71_dialog_content = "這些可惡的暗鬼！居然敢變出母親的樣子來動搖我的心！",
  ui_story_5004_50042901_72_dialog_content = "冷靜點卡蓮，不要讓暗鬼的陰謀得逞了。",
  ui_story_5004_50042901_73_dialog_content = "這裡難道能讀出我們的內心世界嗎……？",
  ui_story_5004_50042901_74_dialog_content = "這個小女孩的馬賽克是……",
  ui_story_5004_50042901_75_dialog_content = "（腦海中怎麼突然產生了一股想要觸碰它的衝動。）",
  ui_story_5004_50042901_76_option_content = "觸碰馬賽克",
  ui_story_5004_50042901_77_dialog_content = "…………！！",
  ui_story_5004_50042901_78_dialog_content = "（好濃烈的煙霧，還有這個熟悉的哭喊聲……是之前觸碰拜里厄時看到的畫面？！）",
  ui_story_5004_50042901_79_dialog_content = "對不起……",
  ui_story_5004_50042901_80_dialog_content = "爸爸，媽媽……對不起……",
  ui_story_5004_50042901_81_dialog_content = "PlayerName，PlayerName？",
  ui_story_5004_50042901_82_dialog_content = "薇絲……",
  ui_story_5004_50042901_83_dialog_content = "你怎麼流眼淚了……又感應到了什麼嗎？",
  ui_story_5004_50042901_84_dialog_content = "（剛剛難道是拜里厄的記憶嗎？我為什麼會突然看到她的記憶？）",
  ui_story_5004_50042901_85_dialog_content = "（那幅小女孩的馬賽克和拜里厄有什麼關係嗎？她的父母……）",
  ui_story_5004_50042901_86_dialog_content = "（不對……那也可能是暗鬼為了蠱惑我，故意讓我看到的。弄清楚之前還是先別說。）",
  ui_story_5004_50042901_87_dialog_content = "我沒事……好像看到了一些幻象……也可能是暗鬼搞的鬼。",
  ui_story_5004_50042901_88_dialog_content = "讓大家都小心這些像馬賽克的東西，它們可能會影響到人的心智。",
  ui_story_5004_50042901_89_dialog_content = "這都是些什麼……怎、怎麼會！",
  ui_story_5004_50042901_90_dialog_content = "嗯？在那邊偷偷摸摸做什麼呢？",
  ui_story_5004_50042901_91_dialog_content = "妳旁邊那兩幅馬賽克好像是我們小時候的樣子吧，它們在做什麼？",
  ui_story_5004_50042901_92_dialog_content = "妳別過來！",
  ui_story_5004_50042901_93_dialog_content = "喂~幹嘛燒掉，我還沒看呢。",
  ui_story_5004_50042901_94_dialog_content = "看什麼看！不准看！",
  ui_story_5004_50042901_95_dialog_content = "吼！",
  ui_story_5004_50042901_96_dialog_content = "喂，有暗鬼！小心！",
  ui_story_5004_50042901_97_dialog_content = "吼！吼！",
  ui_story_5004_50042901_98_dialog_content = "這些傢伙好像可以直接從那些馬賽克裡出現！大家準備戰鬥！",
  ui_story_5004_50043001_1_dialog_content = "幹掉了……這些傢伙是不是比之前海灘上遇到的更強了？",
  ui_story_5004_50043001_2_dialog_content = "嗯，對付起來明顯要比海灘上遇到的困難許多。",
  ui_story_5004_50043001_3_dialog_content = "而且應該還只是分身……這裡籠罩的暗能絲毫沒有減弱。",
  ui_story_5004_50043001_4_dialog_content = "我們現在甚至找不到敵人本體的位置，這下有點棘手了。",
  ui_story_5004_50043001_5_dialog_content = "這個空間真是太古怪了。我還是第一次遇到這種事。",
  ui_story_5004_50043001_6_dialog_content = "吉納維芙，帽子上的頭飾借我用一下。",
  ui_story_5004_50043001_7_dialog_content = "妳想幹嘛，弄壞弄丟了我可饒不了妳。",
  ui_story_5004_50043001_8_dialog_content = "嘿——！",
  ui_story_5004_50043001_9_dialog_content = "妳丟出去幹嘛？！",
  ui_story_5004_50043001_10_dialog_content = "唔！好痛，為什麼會從上面掉下來打在我臉上？！",
  ui_story_5004_50043001_11_dialog_content = "連空間方向都是混亂的嗎？",
  ui_story_5004_50043001_12_dialog_content = "卡蓮，要不要把月之繭投擲出去試試？",
  ui_story_5004_50043001_13_dialog_content = "……比起把我的月之繭投出去，妳直接射一箭出去應該更好些。",
  ui_story_5004_50043001_14_dialog_content = "對喔……",
  ui_story_5004_50043001_15_dialog_content = "等等！萬一又從上面飛過來射中我的臉怎麼辦！",
  ui_story_5004_50043001_16_dialog_content = "沒關係啦~有我在呢！讓導彈跟在箭後面飛就可以啦~",
  ui_story_5004_50043001_17_dialog_content = "妳們還是饒了我吧！再想想其他辦法！",
  ui_story_5004_50043001_18_dialog_content = "要不要試試和那幅嘴巴的馬賽克說話看看？",
  ui_story_5004_50043001_19_dialog_content = "才不要，那幅馬賽克好噁心。",
  ui_story_5004_50043001_20_dialog_content = "感覺像是什麼異世界的東西。",
  ui_story_5004_50043001_21_dialog_content = "那個……",
  ui_story_5004_50043001_22_dialog_content = "要不要……試試那個？",
  ui_story_5004_50043001_23_dialog_content = "又是剛剛那幅小女孩馬賽克嗎？好像在指著自己身後的門？",
  ui_story_5004_50043001_24_dialog_content = "是要我們進去嗎？",
  ui_story_5004_50043001_25_dialog_content = "也只能試試看了吧，它看起來沒什麼敵意。",
  ui_story_5004_50043001_26_dialog_content = "不過這麼小……要怎麼過去？",
  ui_story_5004_50043001_27_option_content = "試著伸進手指",
  ui_story_5004_50043001_28_dialog_content = "<color=#e8d9bb>喀噠</color>",
  ui_story_5004_50043001_29_dialog_content = "好像按到什麼開關了？等等，怎麼回事？",
  ui_story_5004_50043001_30_dialog_content = "腳下的地板在縮小……要掉下去了！！",
  ui_story_5004_50043001_31_dialog_content = "——！！",
  ui_story_5004_50043001_32_dialog_content = "她暈過去了，要怎麼處理？想不到那些粉末居然能製造出這樣恐怖的「怪物」……",
  ui_story_5004_50043001_33_dialog_content = "已經蒐集到足夠的實驗資料了，就把她丟在這裡吧。",
  ui_story_5004_50043001_34_dialog_content = "我很好奇她醒過來之後，看到這些屍體會是怎麼樣的表情。",
  ui_story_5004_50043001_35_dialog_content = "這就是背叛者的代價。",
  ui_story_5004_50043001_36_dialog_content = "……妳的殘忍真是不輸於那些暗鬼。",
  ui_story_5004_50043001_37_dialog_content = "嗚！！",
  ui_story_5004_50043001_38_dialog_content = "好痛……",
  ui_story_5004_50043001_39_dialog_content = "拜、拜託妳們快下去！",
  ui_story_5004_50043001_40_dialog_content = "我快不能呼吸了……",
  ui_story_5004_50043001_41_dialog_content = "呼——！差點窒息，因為我第一個觸摸就被壓在最下面，也太悲慘了吧！",
  ui_story_5004_50043001_42_dialog_content = "啊哈哈，謝謝你救了大家，PlayerName。",
  ui_story_5004_50043001_43_dialog_content = "話說，如果是貢露前輩玩的遊戲的話，現在已經算是第二關了吧？",
  ui_story_5004_50043001_44_dialog_content = "什麼意思？妳是想說會有新的敵人……",
  ui_story_5004_50043001_45_dialog_content = "歡迎光臨，遠道而來的客人！",
  ui_story_5004_50043001_46_dialog_content = "出現了！",
  ui_story_5004_50043001_47_dialog_content = "歡迎各位來到我的城堡和花園——「迷夢虛域」。",
  ui_story_5004_50043001_48_dialog_content = "「迷夢虛域」？妳是這裡的主人？",
  ui_story_5004_50043001_49_dialog_content = "你可以把我當成這裡的女主人，畢竟我在這裡也和那些小玩具生活了十年有餘。",
  ui_story_5004_50043001_50_dialog_content = "就是那些盛情款待你們的「棋子」。它們沒有怠慢客人吧？",
  ui_story_5004_50043001_51_dialog_content = "這個聲音……！",
  ui_story_5004_50043001_52_dialog_content = "就是夢裡那個聲音……",
  ui_story_5004_50043001_53_dialog_content = "這麼說那些棋子形狀的暗鬼是妳製造的？那妳為什麼會是這副樣子？",
  ui_story_5004_50043001_54_dialog_content = "別急。看來空裔果然如傳言所說，好奇心非常強呢。",
  ui_story_5004_50043001_55_dialog_content = "已經有很多年沒有光靈來過這裡了，妳們最好多陪我聊聊天，別輕易死了喔。",
  ui_story_5004_50043001_56_dialog_content = "讓我翻翻在這裡生活第一年寫下的日記，說不定能給你解答……",
  ui_story_5004_50043001_57_dialog_content = "咦？咦？咦咦？沒了？我的第一本日記怎麼沒了呀，是不是你們把它偷走了？",
  ui_story_5004_50043001_58_dialog_content = "怎麼辦，怎麼辦。沒有日記就沒辦法為客人呈上我特別準備的茶點了！",
  ui_story_5004_50043001_59_dialog_content = "或者……讓我掰開你們的腦袋看看，我的日記有沒有藏在裡面？",
  ui_story_5004_50043001_60_dialog_content = "PlayerName，這傢伙太不正常了。",
  ui_story_5004_50043001_61_dialog_content = "喂！別裝瘋賣傻了，就是妳這傢伙指使的那隻倉鼠騙了我吧！",
  ui_story_5004_50043001_62_dialog_content = "先別貿然出手，現在我們對這裡的瞭解還太少了，總之先試著溝通看看。",
  ui_story_5004_50043001_63_option_content = "妳是誰？",
  ui_story_5004_50043001_64_dialog_content = "我是……我是……我想想，第二本日記的封面上寫著……",
  ui_story_5004_50043001_65_dialog_content = "我是「偉大的學者！也是殘忍的行刑人！」。",
  ui_story_5004_50043001_66_dialog_content = "啊，我居然這麼厲害嗎！",
  ui_story_5004_50043001_67_dialog_content = "（這傢伙還在裝瘋賣傻……）",
  ui_story_5004_50043001_68_option_content = "「迷夢虛域」？這是什麼地方？",
  ui_story_5004_50043001_69_dialog_content = "就是這裡呀！我看看……這裡是「進入者內心的痛苦，也是以瘋狂點綴的棋局」。",
  ui_story_5004_50043001_70_dialog_content = "我第六本日記上是這麼說的。",
  ui_story_5004_50043001_71_dialog_content = "而且還是「王」沉睡的地方，也是我答應那位大人將喚醒「王」的地方。",
  ui_story_5004_50043001_72_dialog_content = "（從這裡的暗能來看，的確還潛藏著極為強大的暗鬼，莫非就是它口中的「王」？）",
  ui_story_5004_50043001_73_option_content = "為什麼這裡會從海中浮出來？",
  ui_story_5004_50043001_74_dialog_content = "好問題。",
  ui_story_5004_50043001_75_dialog_content = "「這本是一座偉大的城市，卻被邪惡的空裔所封印。」",
  ui_story_5004_50043001_76_dialog_content = "「邪惡的空裔自食惡果，最終被屠殺殆盡。」",
  ui_story_5004_50043001_77_dialog_content = "哎呀~這本「空裔烹調指南」上記錄的東西還蠻多呢。",
  ui_story_5004_50043001_78_dialog_content = "這位空裔你喜歡什麼點心呀？我可以把你做成你喜歡的樣子喔。",
  ui_story_5004_50043001_79_dialog_content = "（被空裔封印？！是這傢伙利用波娜瑟對樂章的執著，導演了這場陰謀嗎？）",
  ui_story_5004_50043001_80_dialog_content = "PlayerName，還是別聽這傢伙胡言亂語了。",
  ui_story_5004_50043001_81_option_content = "再等等……",
  ui_story_5004_50043001_82_dialog_content = "我剛剛又去拿了幾本書和日記，讓我們再多聊一會吧。",
  ui_story_5004_50043001_83_option_content = "嗯，這傢伙完全像是瘋了……",
  ui_story_5004_50043001_84_dialog_content = "PlayerName，攻擊它吧，不要被這些邪門歪道的東西擾亂心緒。",
  ui_story_5004_50043001_85_dialog_content = "欸？！不要啊，請不要攻擊我！",
  ui_story_5004_50043001_86_dialog_content = "如果你們攻擊我的話……我會……我會忍不住殺了你們的！",
  ui_story_5004_50043001_87_dialog_content = "你們不可以就這麼快死了啊，好不容易跑到這裡了，你們不想知道更多真相嗎？",
  ui_story_5004_50043001_88_dialog_content = "你們不想再陪我聊聊嗎？求求你們別動手好嗎？我馬上幫你們準備茶點！",
  ui_story_5004_50043001_89_dialog_content = "…三、四、五、六…總共七位對吧，我馬上就弄好——！",
  ui_story_5004_50043001_90_dialog_content = "怎麼無預警飛走了…慢著！ 我們不是八個人嗎？",
  ui_story_5004_50043001_91_dialog_content = "波娜瑟不見了？！",
  ui_story_5004_50043001_92_dialog_content = "站住！妳把波娜瑟弄到哪去了！",
  ui_story_5004_50043001_93_dialog_content = "真粗魯……我只是把她送進了某個更適合茶會的地方呀。",
  ui_story_5004_50043001_94_dialog_content = "馬上把她放回來。",
  ui_story_5004_50043001_95_dialog_content = "妳在……妳在命令我嗎？哈哈哈哈！！我可愛的客人居然在命令我！",
  ui_story_5004_50043001_96_dialog_content = "擾亂茶會的無禮之徒，不，不行。我不想殺妳……我要忍耐，忍耐！！",
  ui_story_5004_50043001_97_dialog_content = "喔等等……妳是白夜城的人吧？我從妳身上聞出那股味道了。",
  ui_story_5004_50043001_98_dialog_content = "傲慢、自以為是，又目中無人。",
  ui_story_5004_50043001_99_dialog_content = "這些話原封不動還給妳，身為白夜城的衛隊長——",
  ui_story_5004_50043001_100_dialog_content = "任何威脅到光靈生存的暗鬼，我都會給予制裁！",
  ui_story_5004_50043001_101_dialog_content = "呵呵……",
  ui_story_5004_50043001_102_dialog_content = "呵呵呵呵呵……",
  ui_story_5004_50043001_103_dialog_content = "哈哈哈哈哈哈哈哈哈——！！！",
  ui_story_5004_50043001_104_dialog_content = "說得很好！說得太好了！",
  ui_story_5004_50043001_105_dialog_content = "可愛的衛隊長大人，我忍不住了，我實在忍不住了！",
  ui_story_5004_50043001_106_dialog_content = "妳那麼喜歡玩的話，就讓我的玩具繼續陪妳玩吧！",
  ui_story_5004_50043001_107_dialog_content = "吼——！！",
  ui_story_5004_50043001_108_dialog_content = "敵人過來了，大家小心！",
  ui_story_5004_50043101_1_dialog_content = "很精彩，小衛隊長。",
  ui_story_5004_50043101_2_dialog_content = "在看著你們戰鬥時我又喝了兩杯茶，現在心情好多了。",
  ui_story_5004_50043101_3_dialog_content = "不過看起來你們身上又多了幾道傷痕，揮動武器的速度也愈來愈慢了吧。",
  ui_story_5004_50043101_4_dialog_content = "嘻嘻……看來光靈的極限不過如此啦，對付我製作的玩具都如此吃力。",
  ui_story_5004_50043101_5_dialog_content = "我奉勸你們不要激怒我，或是衝過來找死。再多陪我聊一會，或者多掙扎一下嘛。",
  ui_story_5004_50043101_6_dialog_content = "我寫了十幾年日記……已經很久沒有遇到過這麼棒的素材了……",
  ui_story_5004_50043101_7_dialog_content = "再多……再多陪陪我！！",
  ui_story_5004_50043101_8_dialog_content = "妳這傢伙……到底想要做什麼？",
  ui_story_5004_50043101_9_dialog_content = "做什麼？我想想啊，研究工作我已經厭倦了，以後當個美食家怎麼樣？",
  ui_story_5004_50043101_10_dialog_content = "對！就像那本我最喜歡的「空裔烹調指南」一樣，我也來寫一本「光靈烹調指南」！",
  ui_story_5004_50043101_11_dialog_content = "哈……嘶……不、不行，光是想想……我就又開始興奮了，我又忍不住想要殺你們了！",
  ui_story_5004_50043101_12_dialog_content = "不行不行……一下就乾掉也太無趣了，我籌備已久的茶會裡怎麼能少得了「王」呢。",
  ui_story_5004_50043101_13_dialog_content = "我的「寂靜君王」，賜予我力量的新主人。他一定會很喜歡用你們做成的茶點。",
  ui_story_5004_50043101_14_dialog_content = "對！讓你們看看我的力量，讓你們感到恐懼，感到絕望……",
  ui_story_5004_50043101_15_dialog_content = "然後你們就會變得更加美味可口了！",
  ui_story_5004_50043101_16_dialog_content = "什麼狗屁力量……盡是些花招！",
  ui_story_5004_50043101_17_dialog_content = "別再大放厥詞了，暗鬼。",
  ui_story_5004_50043101_18_dialog_content = "憑妳製造的這些東西只能拖延我們的腳步。",
  ui_story_5004_50043101_19_dialog_content = "製造和控制這些無意識的傀儡，必然會對妳造成消耗。",
  ui_story_5004_50043101_20_dialog_content = "只要我們逮到妳的本體，就是妳的死期！",
  ui_story_5004_50043101_21_dialog_content = "的確如此，我沒有這樣的力量，但那位「王」卻有。",
  ui_story_5004_50043101_22_dialog_content = "「白夜城的那些人裡，有許多人覬覦著暗鬼強大的力量。」",
  ui_story_5004_50043101_23_dialog_content = "「他們之中有些人會與暗鬼進行交易，甚至獻出身體和生命來獲得暗能。」",
  ui_story_5004_50043101_24_dialog_content = "我看看~這本書好像有十幾年歷史啦，現在白夜城還是這樣嗎？",
  ui_story_5004_50043101_25_dialog_content = "保護那些叛徒的感覺究竟是什麼滋味呢？這位衛隊長大人可不可以告訴我呀。",
  ui_story_5004_50043101_26_dialog_content = "別以為這種話能動搖我的意志，邪門歪道。",
  ui_story_5004_50043101_27_dialog_content = "喔——倒是不傻嘛，看來能爬到衛隊長的位置，不光只有身手。",
  ui_story_5004_50043101_28_dialog_content = "看來妳早已深知白夜城是多麼敗絮其中了吧？",
  ui_story_5004_50043101_29_dialog_content = "啊啊~那座永不陷落的城市，高高的白塔，嘻嘻……哈哈哈哈！！！",
  ui_story_5004_50043101_30_dialog_content = "被人們視為希望的英雄~卻也是滿嘴謊言的貴族啊~",
  ui_story_5004_50043101_31_dialog_content = "那些被人們視為希望，背後卻又爾虞我詐的偽君子啊。",
  ui_story_5004_50043101_32_dialog_content = "虛偽狡詐的人啊~他卻成為了貴族。哈哈哈哈！！",
  ui_story_5004_50043101_33_dialog_content = "對不對！對不對！對不對啊！！",
  ui_story_5004_50043101_34_dialog_content = "<color=#FFB400>拜里厄·戈蒂埃</color>！",
  ui_story_5004_50043101_35_dialog_content = "妳果然認識我……妳到底是誰！為什麼知道我的事！",
  ui_story_5004_50043101_36_dialog_content = "戈蒂埃！戈蒂埃！戈蒂埃！！",
  ui_story_5004_50043101_37_dialog_content = "我當然認識妳，還有妳可笑的家族！",
  ui_story_5004_50043101_38_dialog_content = "我的每本日記裡都有妳家族的名字！",
  ui_story_5004_50043101_39_dialog_content = "妳不正是因為體內流淌的血液與身負的罪孽，才會來這裡贖罪的嗎？",
  ui_story_5004_50043101_40_dialog_content = "明明知道晶石蘊含著強大的力量……",
  ui_story_5004_50043101_41_dialog_content = "卻妄圖馴服死神，多麼可笑！！",
  ui_story_5004_50043101_42_dialog_content = "那可是力量，純粹的力量，就該用來毀滅與征服！",
  ui_story_5004_50043101_43_dialog_content = "而不是給那些小丑們享樂！！那些白夜城的小丑！！",
  ui_story_5004_50043101_44_dialog_content = "為什麼連我家族的事妳都知道……",
  ui_story_5004_50043101_45_dialog_content = "我為什麼知道……？喔！妳記不清了？那太好了，不對，不對，太可憐了！",
  ui_story_5004_50043101_46_dialog_content = "太可憐了、太可憐了……像我一樣多寫日記就不會這樣了嘛。",
  ui_story_5004_50043101_47_dialog_content = "我會幫妳多準備一份茶點的，就用妳身邊那個小女孩做吧！",
  ui_story_5004_50043101_48_dialog_content = "妳休想碰拉斐爾一根汗毛！",
  ui_story_5004_50043101_49_dialog_content = "小拜里厄……",
  ui_story_5004_50043101_50_dialog_content = "喔？好！好啊！我不碰她，嘻嘻……",
  ui_story_5004_50043101_51_dialog_content = "就算我不碰她，憑「棋子」一樣的妳，就能保護她嗎？",
  ui_story_5004_50043101_52_dialog_content = "我會認真地把妳們真摯的感情……全都一五一十地寫成書的！",
  ui_story_5004_50043101_53_dialog_content = "妳們就在死去之後，永遠地活在我的筆下吧！",
  ui_story_5004_50043101_54_dialog_content = "這本書要叫什麼呢？「愚蠢與天真的戀情」？「一枚棋子的悲歌」？",
  ui_story_5004_50043101_55_dialog_content = "你們這些光靈每一個都蠢到令我發笑，每一個我都想綁起來拷問再寫成書呀！",
  ui_story_5004_50043101_56_dialog_content = "喔！喔對！還要把你們做成點心，享受著紅茶！",
  ui_story_5004_50043101_57_dialog_content = "然後一邊看你們的生平，一邊品嚐你們的血肉……",
  ui_story_5004_50043101_58_dialog_content = "就拿那個我準備寫成「愚蠢的音樂家」的可笑光靈來說。",
  ui_story_5004_50043101_59_dialog_content = "那傢伙只是為了演奏一次樂譜……就在毫不自知的情況下解除了封印，嘻嘻。",
  ui_story_5004_50043101_60_dialog_content = "我再派遣暗鬼潛入飯店<color=#FFB400>設下機關</color>……然後舉行潮汐祭汲取飯店周邊所有光靈的光能。",
  ui_story_5004_50043101_61_dialog_content = "「寂靜君王」能夠甦醒，你們也居功厥偉喔！",
  ui_story_5004_50043101_62_dialog_content = "我可真是完美的棋手、戰略家、戰術家、陰謀家……對，還有文學家呀！",
  ui_story_5004_50043101_63_dialog_content = "根本就是瘋子……我看妳是龜縮在這裡太久，精神已經失常了吧！",
  ui_story_5004_50043101_64_dialog_content = "啊……你居然……你居然說出這麼值得記錄的話！",
  ui_story_5004_50043101_65_dialog_content = "在我親手把你做成點心之前，可別被我的新玩具們殺了喔，好不好？",
  ui_story_5004_50043101_66_dialog_content = "拜託你們一定要加油喔~",
  ui_story_5004_50043201_1_dialog_content = "哈……哈……",
  ui_story_5004_50043201_2_dialog_content = "PlayerName，你又在流鼻血……別太勉強了。",
  ui_story_5004_50043201_3_dialog_content = "我沒關係……只是稍微有點累了……",
  ui_story_5004_50043201_4_dialog_content = "（像這樣連續打個不停……對精神的負荷有點太強了……）",
  ui_story_5004_50043201_5_dialog_content = "打完了嗎？我正準備享用下一塊點心呢。",
  ui_story_5004_50043201_6_dialog_content = "我對各位這次的戰鬥評價是——",
  ui_story_5004_50043201_7_dialog_content = "「小孩打群架一般的指揮，加上老婆婆揮動手杖一樣的動作」。",
  ui_story_5004_50043201_8_dialog_content = "說起來你們好像愈來愈慢了嘛，這次我喝了四杯茶，吃了一塊點心。",
  ui_story_5004_50043201_9_dialog_content = "可惡……妳這傢伙！妳以為是在玩嗎！",
  ui_story_5004_50043201_10_dialog_content = "一直用這些鏡像分身之類的傢伙和我們戰鬥有什麼意思！",
  ui_story_5004_50043201_11_dialog_content = "出來堂堂正正地打一場啊！",
  ui_story_5004_50043201_12_dialog_content = "哈哈哈哈，就憑妳？就憑你們嗎！連這些可憐玩具都敵不過的你們？",
  ui_story_5004_50043201_13_dialog_content = "我還想再多瞭解你們一些，我始終認為只有傾注了感情的食物……才最美味呢。",
  ui_story_5004_50043201_14_dialog_content = "況且，「寂靜君王」的力量還在甦醒，我也有時間可以多陪你們聊上一會。",
  ui_story_5004_50043201_15_dialog_content = "喔，我找到第一本日記了，讓我看看上面寫著什麼……",
  ui_story_5004_50043201_16_dialog_content = "噗……噗哈哈哈哈哈！！這真是個寶物呀！！快聽好，我讀給你們聽聽！！",
  ui_story_5004_50043201_17_dialog_content = "咳咳，嗯！我清一清嗓子。",
  ui_story_5004_50043201_18_dialog_content = "戈蒂埃家族的小姑娘，妳可憐的小腦袋為什麼就想不到呢？",
  ui_story_5004_50043201_19_dialog_content = "是誰，對晶石能夠這麼瞭解……又是誰，能在夢中呼喚妳呀？",
  ui_story_5004_50043201_20_dialog_content = "妳……是那個皮洛斯家族裡唯一存活下來……投靠了暗鬼的卡洛琳·皮洛斯！？",
  ui_story_5004_50043201_21_dialog_content = "哈哈哈哈哈！！！是啦！！",
  ui_story_5004_50043201_22_dialog_content = "不好了不好了，聽到以前自己還是光靈那時候的名字，感覺好羞恥呀！！",
  ui_story_5004_50043201_23_dialog_content = "果然日記這東西，不該讀給別人聽呀。",
  ui_story_5004_50043201_24_dialog_content = "不行，但我還是好想讀給你們聽！你們快認真聽我說！",
  ui_story_5004_50043201_25_dialog_content = "妳這傢伙，以前是光靈嗎？",
  ui_story_5004_50043201_26_dialog_content = "又是一個屈服於暗鬼出賣了自己靈魂的傢伙。",
  ui_story_5004_50043201_27_dialog_content = "嘻嘻嘻……是喔，我差點都忘了自己曾經是光靈了。",
  ui_story_5004_50043201_28_dialog_content = "不過日記上寫滿了變成暗鬼之後有多自由，有多快樂。",
  ui_story_5004_50043201_29_dialog_content = "比在白夜城的時候快樂了千萬倍呀！",
  ui_story_5004_50043201_30_dialog_content = "回到正題~就像我剛剛說的，我的家族不同於你的家族，只想把晶石當做能源利用……",
  ui_story_5004_50043201_31_dialog_content = "這殘忍、暴虐的力量本來就該成為武器！",
  ui_story_5004_50043201_34_dialog_content = "它原本可以成為幫助白夜城擊退暗鬼的利刃，甚至可以把所有暗鬼打回極暗之中！",
  ui_story_5004_50043201_35_dialog_content = "卻被妳那些懦弱的家人向白夜城城主告發了。啊！唸到這裡我又開始生氣了！",
  ui_story_5004_50043201_36_dialog_content = "妳們皮洛斯家族那時已經在到處搜捕落魄的光靈，用他們的身體來進行晶石實驗了吧。",
  ui_story_5004_50043201_37_dialog_content = "這種用同族身體做實驗的行為，任何有理智的人都不會接受！",
  ui_story_5004_50043201_38_dialog_content = "喔，年輕時候的我確實很沉迷晶石的實驗啦……嘿嘿嘿……",
  ui_story_5004_50043201_39_dialog_content = "不過沒有我，就沒有現在的拜里厄呀……我得意的實驗品……",
  ui_story_5004_50043201_40_dialog_content = "難道……小拜里厄……",
  ui_story_5004_50043201_41_dialog_content = "……",
  ui_story_5004_50043201_42_dialog_content = "這日記上關於妳的記載好詳細呀，妳喜歡吃什麼、妳喜歡的運動……",
  ui_story_5004_50043201_43_dialog_content = "甚至你睡覺時候喜歡抱什麼都一清二楚。",
  ui_story_5004_50043201_44_dialog_content = "簡直像是作者愛上妳了！",
  ui_story_5004_50043201_45_dialog_content = "喔！不對，作者是我呢，那就該說是變態偷窺狂愛上了純潔少女的橋段。",
  ui_story_5004_50043201_46_dialog_content = "雖然只是個不完美的作品，卻也是我實驗中的重要里程碑呢。",
  ui_story_5004_50043201_47_dialog_content = "我對妳傾注了很多很多愛意~",
  ui_story_5004_50043201_48_dialog_content = "用暗能製成的特殊晶石粉末……它們現在還生長在妳的身體裡吧……",
  ui_story_5004_50043201_49_dialog_content = "它們寄宿在妳的身體裡……以妳的情緒和意志為養料。",
  ui_story_5004_50043201_50_dialog_content = "不要說了……",
  ui_story_5004_50043201_51_dialog_content = "不過實在是太不穩定了……噗嘻嘻嘻嘻——終於到這裡了，我最喜歡的段落呀！",
  ui_story_5004_50043201_52_dialog_content = "啊啊~那場被妳點燃的美妙的大火，被妳殺害的無數光靈尖叫的聲音——",
  ui_story_5004_50043201_53_dialog_content = "不要再說了！！！",
  ui_story_5004_50043201_54_dialog_content = "別太得意忘形了！",
  ui_story_5004_50043201_55_dialog_content = "嘻嘻……「王」在呼喚我了……",
  ui_story_5004_50043201_56_dialog_content = "我等一下就回來，讓大家變成和那些被燒死的光靈一樣美味可口喔。",
  ui_story_5004_50043201_57_dialog_content = "不要……不要不要不要不要！！",
  ui_story_5004_50043201_58_dialog_content = "小拜里厄！妳冷靜點！",
  ui_story_5004_50043201_59_dialog_content = "拉斐爾，讓我試試用精神感應安撫拜里厄的情緒！",
  ui_story_5004_50043201_60_dialog_content = "知道了……請你快一點……她看起來好痛苦……",
  ui_story_5004_50043201_61_dialog_content = "（我能感覺到一股狂暴的力量正在拜里厄身上游走。）",
  ui_story_5004_50043201_62_dialog_content = "（這絕不是光靈所能擁有的力量，又與暗能術不同。）",
  ui_story_5004_50043201_63_dialog_content = "（或許真如卡洛琳所說，是一種象徵著毀滅的殘惡力量。）",
  ui_story_5004_50043201_64_dialog_content = "（一直以來拜里厄明顯是在努力地控制著這股力量，而此刻在卡洛琳的刺激下……）",
  ui_story_5004_50043201_65_dialog_content = "（這種控制也逐漸變得微弱。）",
  ui_story_5004_50043201_66_dialog_content = "小拜里厄……",
  ui_story_5004_50043201_67_dialog_content = "拉斐爾……我沒事了……謝謝你，PlayerName。",
  ui_story_5004_50043201_68_dialog_content = "抱歉……我不是想向大家隱瞞自己的身世……",
  ui_story_5004_50043201_69_dialog_content = "但可能是受到卡洛琳實驗的影響……或者太過痛苦而出於本能地不願回憶……",
  ui_story_5004_50043201_70_dialog_content = "那段往事的回憶對我來說非常模糊……",
  ui_story_5004_50043201_71_dialog_content = "我只記得自己很小的時候……被皮洛斯家族的人擄走……",
  ui_story_5004_50043201_72_dialog_content = "被人關在一個什麼都看不到的房間裡……餵下了那些晶石的粉末。",
  ui_story_5004_50043201_73_dialog_content = "然後我的身體就如同被詛咒一般……無法離開這些每日帶給我痛苦的晶石。",
  ui_story_5004_50043201_74_dialog_content = "後來我才得知……那是皮洛斯家族把光靈改造成兵器的實驗……就是利用這些晶石。",
  ui_story_5004_50043201_75_dialog_content = "沒關係的……小拜里厄，每個人都有自己的過去。",
  ui_story_5004_50043201_76_dialog_content = "快樂的就選擇分享，不愉快的就選擇遺忘。沒人會介意妳想要開始全新的生活。",
  ui_story_5004_50043201_77_dialog_content = "嗯？我是無所謂啦，反正我的過去也不比妳好多少。",
  ui_story_5004_50043201_78_dialog_content = "妳那些事就別說出來丟人了。但說到重新開始，我也完全支持。",
  ui_story_5004_50043201_79_dialog_content = "我們可是夥伴喔，不管以前發生了什麼，我信任現在的你！",
  ui_story_5004_50043201_80_dialog_content = "毫無疑問，當務之急是對犯下如此深重罪行的卡洛琳加以審判，阻止更多慘劇發生。",
  ui_story_5004_50043201_81_dialog_content = "我當然也和大家一樣。",
  ui_story_5004_50043201_82_dialog_content = "謝謝……謝謝大家……",
  ui_story_5004_50043201_83_dialog_content = "那個卡洛琳·皮洛斯……雖然她曾經身為白夜城貴族，卻絲毫沒有榮耀可言。",
  ui_story_5004_50043201_84_dialog_content = "沒想到她不光和暗鬼聯手……還對同族做出這種喪盡天良的事……",
  ui_story_5004_50043201_85_dialog_content = "還有那個她一直掛在嘴邊的「王」，如果真如她所說擁有那麼強大的力量……",
  ui_story_5004_50043201_86_dialog_content = "就必須阻止「王」的覺醒。",
  ui_story_5004_50043201_87_dialog_content = "但在這個空間裡，我們要如何找到她的本體呢？",
  ui_story_5004_50043201_88_dialog_content = "那個……剛剛在PlayerName用精神感應幫助我的時候……",
  ui_story_5004_50043201_89_dialog_content = "我好像也感應到了某個地點集中了龐大的晶石力量……",
  ui_story_5004_50043201_90_dialog_content = "那裡很可能就是它們的藏身處……",
  ui_story_5004_50043201_91_dialog_content = "幹得好！那我們就出發吧！",
  ui_story_5004_50043201_92_dialog_content = "嗯，想必會是一場苦戰。",
  ui_story_5004_50043201_93_dialog_content = "放心吧……小拜里厄。我會幫妳向那個傢伙好好討回公道的！",
  ui_story_5004_50043201_94_dialog_content = "嗯……然後就像約好的一樣，一起回白夜城吧。",
  ui_story_5004_50043201_95_dialog_content = "不管前面等待著怎樣的敵人……我都不會再退縮的！",
  ui_story_5004_50043301_1_dialog_content = "喔？想不到你們居然能找到這裡。",
  ui_story_5004_50043301_2_dialog_content = "咳咳~「我非常感動你們會特地來到<color=#FFB400>謁見之間</color>，向自己的新王叩首臣服。」",
  ui_story_5004_50043301_3_dialog_content = "「這就是我利用晶石的力量所獲得的全新姿態……是與妳相同的力量，拜里厄。」",
  ui_story_5004_50043301_4_dialog_content = "「不同的是，妳只是個實驗品。而我則是可以自由掌握全部晶石力量的完成體。」",
  ui_story_5004_50043301_5_dialog_content = "「而<color=#FFB400>寂靜君王</color>也會藉由晶石的力量甦醒……再次睥睨眾生。」",
  ui_story_5004_50043301_6_dialog_content = "咳咳~我準備用這幾句話當作開場，然後下面記錄你們悲慘的死狀。你們喜歡嗎？",
  ui_story_5004_50043301_7_dialog_content = "<color=#e8d9bb>卡洛琳向後揮手，晶石炸開成粉末，接著「王」吸收了粉末所形成的濃霧。</color>",
  ui_story_5004_50043301_8_dialog_content = "……",
  ui_story_5004_50043301_9_dialog_content = "你們看到了嗎……晶石的力量與暗鬼是如此契合。",
  ui_story_5004_50043301_10_dialog_content = "而過去的我卻錯以為這是神賜給光靈的利刃，簡直愚蠢得令我無地自容呀！",
  ui_story_5004_50043301_11_dialog_content = "這明明就是「神」對暗鬼的贈禮！",
  ui_story_5004_50043301_12_dialog_content = "我徹底受夠妳的聒噪了。",
  ui_story_5004_50043301_13_dialog_content = "開打吧！",
  ui_story_5004_50043301_14_dialog_content = "終於啊，終於……嘻嘻嘻……咿嘻嘻嘻嘻！我終於忍不住想殺你們了！",
  ui_story_5004_50043301_15_dialog_content = "快點、快點快點快點！！再更痛苦、更絕望，變得更加美味吧！！",
  ui_story_5004_50043302_1_dialog_content = "可惡！這些東西殺不完的嗎？",
  ui_story_5004_50043302_2_dialog_content = "別跟這些雜碎糾纏了……哈！燒毀吧！！",
  ui_story_5004_50043302_3_dialog_content = "嘎……嘎……不可能……我居然……",
  ui_story_5004_50043302_4_dialog_content = "好厲害……直接命中了頭部，面部的光芒暗淡下去了！",
  ui_story_5004_50043302_5_dialog_content = "成……成功了……？",
  ui_story_5004_50043302_6_dialog_content = "……",
  ui_story_5004_50043302_7_dialog_content = "咿嘻嘻嘻嘻！騙你們的啦！",
  ui_story_5004_50043302_8_dialog_content = "！！",
  ui_story_5004_50043302_9_dialog_content = "斯莫奇！",
  ui_story_5004_50043302_10_dialog_content = "痛死了……從我身上起來！",
  ui_story_5004_50043302_11_dialog_content = "哈……沒想到被偷襲了，多虧妳啦。",
  ui_story_5004_50043302_12_dialog_content = "等一下！這麼深的傷口，趕快讓拉斐爾幫妳治療一下吧！",
  ui_story_5004_50043302_13_dialog_content = "（可惡，怎麼攻擊都打不倒……而且周圍那些棋子暗鬼也在源源不斷地出現……）",
  ui_story_5004_50043302_14_dialog_content = "（不可能！之前遇到的那些轉變為暗鬼的傢伙裡……根本沒有這麼強大的！）",
  ui_story_5004_50043302_15_dialog_content = "（難道是那個「王」……）",
  ui_story_5004_50043302_16_dialog_content = "PlayerName！集中精神！戰場局勢瞬息萬變，可能轉瞬間就會出現轉機！",
  ui_story_5004_50043302_17_dialog_content = "小心被抓住破綻。",
  ui_story_5004_50043302_18_dialog_content = "妳們在那邊……偷偷摸摸說什麼呀？不大聲點我怎麼把妳們的遺言寫進日記裡！！",
  ui_story_5004_50043302_19_dialog_content = "綻放吧！！",
  ui_story_5004_50043302_20_dialog_content = "咳咳！！好濃的煙塵，拜里厄是在防禦的同時引爆晶石，反擊卡洛琳了嗎？",
  ui_story_5004_50043302_21_dialog_content = "……",
  ui_story_5004_50043302_22_dialog_content = "不錯，不錯。",
  ui_story_5004_50043302_23_dialog_content = "怎麼會沒效果……",
  ui_story_5004_50043302_24_dialog_content = "可惡……這傢伙怎麼連一絲傷痕都沒留下。",
  ui_story_5004_50043302_25_dialog_content = "不對……應該是……",
  ui_story_5004_50043302_26_dialog_content = "哪怕只是這點小花招，對於身為實驗品的妳來說，也已經非常出色了。",
  ui_story_5004_50043302_27_dialog_content = "但是，可憐的拜里厄，我可憐的失敗品啊。",
  ui_story_5004_50043302_28_dialog_content = "妳還是一樣……一樣沒用啊。",
  ui_story_5004_50043302_29_dialog_content = "殺死了那麼多人……殺死了妳的父母……妳現在又救得了誰呢？",
  ui_story_5004_50043302_30_dialog_content = "我早就警告過妳了……妳會害死所有至親之人，然後墜入深淵。",
  ui_story_5004_50043302_31_dialog_content = "我……我沒有……",
  ui_story_5004_50043302_32_dialog_content = "父母……？",
  ui_story_5004_50043302_33_dialog_content = "吼！！",
  ui_story_5004_50043302_34_dialog_content = "可惡！不要擋著我！",
  ui_story_5004_50043302_35_dialog_content = "卡蓮、薇絲！去掩護拉斐爾！",
  ui_story_5004_50043302_36_dialog_content = "我知道妳還記得，妳還記得自己是如何殘忍地殺害了毫無防備的父母……",
  ui_story_5004_50043302_37_dialog_content = "接受妳的死亡吧……這是妳的贖罪、妳的解脫。",
  ui_story_5004_50043302_38_dialog_content = "對不起……大家……對不起……爸爸媽媽……",
  ui_story_5004_50043302_39_dialog_content = "小拜里厄！",
  ui_story_5004_50043302_40_dialog_content = "小拜里厄……別聽這傢伙說的……妳的父母是這傢伙殺的！",
  ui_story_5004_50043302_41_dialog_content = "雖然當時妳的力量失控引起了大火……但妳馬上就失去意識了！",
  ui_story_5004_50043302_42_dialog_content = "這傢伙卻在那時利用妳作為人質，殺死了妳的父母和族人！！",
  ui_story_5004_50043302_43_dialog_content = "……",
  ui_story_5004_50043302_44_dialog_content = "這是被捕的皮洛斯族人供出的真相，絕對是千真萬確！！",
  ui_story_5004_50043302_45_dialog_content = "多管閒事！！",
  ui_story_5004_50043302_46_dialog_content = "嗚！！",
  ui_story_5004_50043302_47_dialog_content = "嘻嘻……沒想到還會有攪局的傢伙。",
  ui_story_5004_50043302_48_dialog_content = "不過啊，不過……哈哈哈哈哈哈！！！",
  ui_story_5004_50043302_49_dialog_content = "妳居然真的相信了！！！",
  ui_story_5004_50043302_50_dialog_content = "！！！",
  ui_story_5004_50043302_51_dialog_content = "怎麼樣，妳還記得醒來之後父母的樣子嗎？",
  ui_story_5004_50043302_52_dialog_content = "那可是我特地親手擺在妳面前的喔——就為了讓妳以為是自己親手殺死了父母！！",
  ui_story_5004_50043302_53_dialog_content = "太蠢了、太蠢了太蠢了太蠢了，居然真的相信了，還信了這麼多年對不對！！",
  ui_story_5004_50043302_54_dialog_content = "……妳竟然敢……",
  ui_story_5004_50043302_55_dialog_content = "我每次翻看日記回憶到這裡時，都會興奮得渾身發抖！",
  ui_story_5004_50043302_56_dialog_content = "妳十幾年來都認為是自己殺死了父母吧！！",
  ui_story_5004_50043302_57_dialog_content = "這本日記可是我最重要的寶藏呀！真開心能與你們分享！",
  ui_story_5004_50043302_58_dialog_content = "我陪你們玩到現在，就是為了看到再親手記下妳現在這絕美的表情咿嘻嘻嘻嘻！！",
  ui_story_5004_50043302_59_dialog_content = "開心嗎？開心嗎？把殺死親人的痛苦埋藏在心底，小心翼翼地苟活這麼多年。",
  ui_story_5004_50043302_60_dialog_content = "然後得知真相的這一瞬間，妳的表情實在太美了！",
  ui_story_5004_50043302_61_dialog_content = "我要把妳的整張臉直接撕下來做成日記封面！！",
  ui_story_5004_50043302_62_dialog_content = "戈蒂埃！戈蒂埃！叛徒戈蒂埃的人，就該是這樣的下場！！",
  ui_story_5004_50043302_63_dialog_content = "妳居然敢做這種事！！！",
  ui_story_5004_50043302_64_dialog_content = "就憑妳這個失敗品，還妄圖與完美的我和即將甦醒的王對抗嗎！",
  ui_story_5004_50043302_65_dialog_content = "不管是妳讓我背負罪孽的謊言，還是妳想要傷害我的朋友——",
  ui_story_5004_50043302_66_dialog_content = "我都無法原諒，我絕對不會放過妳！！",
  ui_story_5004_50043302_67_dialog_content = "這是……拜里厄一直壓制著的力量嗎……？！",
  ui_story_5004_50043302_68_dialog_content = "如果放任這種力量的話，妳可能會變成卡洛琳那樣的怪物……！",
  ui_story_5004_50043302_69_dialog_content = "我以前因為弱小而失去了親人，自己也深陷痛苦和自責……",
  ui_story_5004_50043302_70_dialog_content = "而這一切的元凶就站在我面前，還企圖傷害我重要的人！",
  ui_story_5004_50043302_71_dialog_content = "卡洛琳·皮洛斯！",
  ui_story_5004_50043302_72_dialog_content = "即使失去控制，我也要拉妳一起進地獄！",
  ui_story_5004_50043302_73_dialog_content = "這種誇張的晶石攻擊……",
  ui_story_5004_50043302_74_dialog_content = "卡洛琳被困住了！不行……晶石雖然能卡住它的身體，但是無法徹底擊敗它！",
  ui_story_5004_50043302_75_dialog_content = "雕蟲小技——！王啊！再給予我更多力量吧！！讓我懲罰這些膽敢忤逆你的傢伙！！",
  ui_story_5004_50043302_76_dialog_content = "……",
  ui_story_5004_50043302_77_dialog_content = "我明白了！雖然還只是猜測。",
  ui_story_5004_50043302_78_dialog_content = "卡洛琳那不死一般的力量，很可能與「王」有關！",
  ui_story_5004_50043302_79_dialog_content = "大家！趁卡洛琳被困住時，快集中攻擊它！！",
  ui_story_5004_50043402_1_dialog_content = "……！！",
  ui_story_5004_50043402_2_dialog_content = "你們居然！你們這些螻蟻居然敢！！",
  ui_story_5004_50043402_3_dialog_content = "毀掉我多年的心血！！",
  ui_story_5004_50043402_4_dialog_content = "接下來該輪到我們反擊了！",
  ui_story_5004_50043402_5_dialog_content = "敢讓我受傷的罪，就用妳的命來清算！",
  ui_story_5004_50043402_6_dialog_content = "不可能、不可能！我絕不可能輸給你們這些螻蟻！",
  ui_story_5004_50043402_7_dialog_content = "你們這些棋子……絕對不能……我是白夜城的晶石學者……我是這裡的……王后！",
  ui_story_5004_50043402_8_dialog_content = "我的王！再給我力量吧！我怎麼聽不到您的聲音了！",
  ui_story_5004_50043402_9_dialog_content = "我還要……再繼續……還沒結束！我的茶會……我……！",
  ui_story_5004_50043402_10_dialog_content = "詛咒你們！！大家一起……我還有更多點心，美味的光靈！！無恥之徒！背叛者！！",
  ui_story_5004_50043402_11_dialog_content = "我要把你們永遠囚禁在——！！",
  ui_story_5004_50043402_12_dialog_content = "我不會再聽信妳任何一句胡言亂語了……！消失吧……！！",
  ui_story_5004_50043402_13_dialog_content = "茶會……絕不可能被妳——啊啊啊啊啊——！！！",
