  ui_story_5004_50043402_15_dialog_content = "這、這次終於成功了……？",
  ui_story_5004_50043402_16_dialog_content = "小拜里厄！妳身上的晶石怎麼變得這麼多！",
  ui_story_5004_50043402_17_dialog_content = "沒關係……拉斐爾，只要妳和大家都安全就好……",
